$('theme-btn').onclick=()=>{state.settings.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';save();theme();if(currentView==='settings')renderSettings()};$('settings-btn').innerHTML=icon('settings');matchMedia('(prefers-color-scheme: dark)').addEventListener?.('change',theme);
function activity(kind){const k=dayKey();state.activity[k]??={cards:0,readings:0};state.activity[k][kind]++;save();chrome();}
function streak(){let n=0,d=new Date();if(!state.activity[dayKey(d)]||!(state.activity[dayKey(d)].cards+state.activity[dayKey(d)].readings))d.setDate(d.getDate()-1);while(state.activity[dayKey(d)]&&(state.activity[dayKey(d)].cards+state.activity[dayKey(d)].readings)){n++;d.setDate(d.getDate()-1)}return n;}
