const chapterCards=()=>courseChapters().map(([id,title,sub,glyph])=>{const p=progress(id);return `<button class="chapter" onclick="openChapter('${id}')"><div class="chapter-top"><span class="chapter-num">${id==='I'?'START HERE':'CHAPTER '+String(id).padStart(2,'0')}</span><span class="chapter-glyph">${text(glyph)}</span></div><h3>${title}</h3><div class="chapter-meta">${p.total} characters · ${READINGS.filter(r=>r.lesson===id).length} readings</div><div class="progress"><span style="width:${p.percent}%"></span></div><div class="progress-caption"><span>${p.practiced}/${p.total} practiced · ${p.known} familiar</span><span>${p.percent}%</span></div></button>`}).join('');
function renderHomeBase(){const ch=CHAPTERS.find(x=>x[0]===state.lastChapter)||courseChapters()[1];const total=Object.values(state.cards).filter(x=>x.streak>=1).length,today=state.activity[dayKey()]?.cards||0;const hour=new Date().getHours();$('view').innerHTML=`<div class="heading"><div><h1>${hour<12?'Good morning':hour<18?'Good afternoon':'Good evening'}.</h1></div><span class="badge">${state.settings.script==='traditional'?'Traditional':'Simplified'}</span></div><section class="hero"><div><div class="eyebrow">Current chapter</div><h2>${ch[1]}</h2><p class="muted">${ch[2]}</p><button class="btn primary" onclick="openChapter('${ch[0]}')">Continue learning ${icon('arrow')}</button></div><div class="hero-art"><span class="orbit"></span><span class="orbit small"></span><span class="hero-han">${text(ch[3])}</span></div></section><div class="stats-grid"><div class="stat"><div class="stat-icon">${icon('learn')}</div><strong>${total}<span style="font-size:13px"> / 400</span></strong><span>Familiar characters</span></div><div class="stat"><div class="stat-icon">${icon('review')}</div><strong>${dueCards().length}</strong><span>Ready for review</span></div><div class="stat"><div class="stat-icon">${icon('read')}</div><strong>${Object.keys(state.read).length}<span style="font-size:13px"> / 22</span></strong><span>Readings completed</span></div><div class="stat"><div class="stat-icon">${icon('check')}</div><strong>${today}<span style="font-size:13px"> / ${state.settings.goal}</span></strong><span>Today's card reviews</span></div></div><div class="section-title"><h2>Your chapters</h2><button class="textbtn" onclick="navigate('learn')">Explore all ${icon('arrow')}</button></div><div class="chapter-grid">${chapterCards()}</div><div class="activity"><section class="panel"><h2>Your week</h2><div class="week">${weekMarkup()}</div></section><section class="panel"><h2>Review</h2><p class="muted">${dueCards().length?dueCards().length+' characters due for review.':'No reviews due.'}</p><button class="btn" onclick="navigate('review')">Open review ${icon('arrow')}</button></section></div>`;}
function weekMarkup(){return Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);const a=state.activity[dayKey(d)],done=a&&(a.cards+a.readings)>0;return `<div class="day">${d.toLocaleDateString(undefined,{weekday:'short'})}<div class="day-dot ${done?'done':''}">${done?icon('check'):d.getDate()}</div>${a?.cards||0} cards</div>`}).join('');}
