function storyCards(id){return `<div class="story-grid">${READINGS.filter(r=>!id||r.lesson===id).map(r=>`<button class="story-card" onclick="openReading('${r.id}')"><div class="row" style="justify-content:space-between"><span class="story-icon">${icon('read')}</span><span class="badge">${readingCompletionLabel(r)}</span></div><h3>${r.title}</h3><p>${r.subtitle}</p><div class="small muted">${r.lines.length} paragraphs · ${state.read[r.id]?'Read again':'Start reading'} →</div></button>`).join('')}</div>`;}
function shuffle(a){a=a.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function startSession(mode,id){let pool=id?CARDS.filter(c=>c.lesson===id):CARDS.filter((c,i,a)=>a.findIndex(x=>x.character===c.character)===i);if(mode==='review')pool=dueCards();if(mode==='saved')pool=pool.filter(c=>state.bookmarks.includes(c.character));if(mode==='weak')pool=pool.filter(c=>state.cards[c.character]&&state.cards[c.character].streak<2);if(mode==='learn'){pool=pool.sort((a,b)=>(state.cards[a.character]?.streak||0)-(state.cards[b.character]?.streak||0));pool=pool.slice(0,10);}else pool=shuffle(pool);session={queue:pool.slice(0,mode==='all'?pool.length:30),mode,id,pos:0,attempts:0,right:0,revealed:false,done:false,hint:false,started:Date.now()};currentView='session';chrome();renderSession();window.scrollTo({top:0,behavior:'instant'});}
function renderSessionBase(){const s=session,c=s.queue[s.pos];if(!c){s.done=true;const pct=s.attempts?Math.round(s.right/s.attempts*100):0;$('view').innerHTML=`<div class="session-wrap"><section class="panel empty"><div class="empty-glyph">${s.attempts?'好':'✓'}</div><div class="eyebrow">${s.attempts?'Session complete':'All clear'}</div><h1>${s.attempts?'Nice work. Keep it growing.':'Nothing here to practice yet.'}</h1>${s.attempts?`<div class="score-ring">${pct}%</div><p class="muted">${s.right} confident answers across ${s.attempts} reviews.</p><p class="small muted">Your next reviews are scheduled.</p>`:'<p class="muted">Learn a few characters or try another chapter.</p>'}<div class="row" style="justify-content:center"><button class="btn primary" onclick="${s.id?`openChapter('${s.id}');chapterTab('read')`:`navigate('read')`}">Try a reading ${icon('arrow')}</button><button class="btn" onclick="navigate('home')">Go home</button></div></section></div>`;return;}
$('view').innerHTML=`<div class="session-wrap"><div class="session-top"><button class="textbtn" onclick="navigate('home')">${icon('close')} Finish later</button><span class="muted">${s.pos+1} / ${s.queue.length}</span></div><div class="progress" style="margin-bottom:20px"><span style="width:${s.pos/s.queue.length*100}%"></span></div><div class="flashcard"><div class="eyebrow">${CHAPTERS.find(x=>x[0]===c.lesson)[1]}</div><button class="iconbtn save-btn" aria-label="${state.bookmarks.includes(c.character)?'Remove bookmark':'Bookmark character'}" onclick="qolBookmarkPractice('${c.character}')" style="color:${state.bookmarks.includes(c.character)?'var(--accent)':'var(--muted)'}">${star(c.character)}</button><div class="han">${han(c)}</div>${s.revealed?`<div class="row" style="justify-content:center"><span class="pinyin">${esc(c.pinyin)}</span><button class="iconbtn" aria-label="Hear this character" onclick="speak('${c.character}')">${icon('sound')}</button></div><div>${esc(c.meaning)}</div>${exampleMarkup(c,true)}`:`<p class="hintprompt">Can you read this character?</p><p class="small muted">Think of a word you already know.</p><button class="textbtn" onclick="flashHint()">${s.hint?'Hide hint':'Need a hint?'}</button>${s.hint?`<p class="cue">${esc(c.cue)}</p>`:''}`}</div>${s.revealed?`<div class="rate-row"><button class="btn danger" onclick="rate('again')">Again<small>1 · another look</small></button><button class="btn" onclick="rate('hard')">Almost<small>2 · revisit soon</small></button><button class="btn primary" onclick="rate('good')">Got it<small>3 · keep going</small></button></div>`:`<button class="btn primary full" style="margin-top:18px" onclick="reveal()">Show answer <span class="small">· Space</span></button>`}</div>`;}
function flashHint(){if(!session||session.revealed||session.done)return;session.hintLevel=(session.hintLevel||0)+1;if(session.hintLevel>3){session.hintLevel=0;session.hint=false}else{session.hint=true;session.usedHint=true}renderSession()}
function reveal(){if(!session||session.done)return;session.revealed=true;renderSession()}
function schedule(old,r,now=Date.now()){const x=old||{seen:0,streak:0,interval:0,due:0,last:0};if(r==='again')return {seen:x.seen+1,streak:0,interval:0,due:now+10*60000,last:now};if(r==='hard')return {seen:x.seen+1,streak:Math.max(0,x.streak-1),interval:.25,due:now+6*3600000,last:now};const interval=x.streak===0?1:x.streak===1?3:Math.min(365,Math.max(3,Math.round(x.interval*2)));return {seen:x.seen+1,streak:x.streak+1,interval,due:now+interval*86400000,last:now};}
function rate(r){const s=session;if(!s||s.done||!s.revealed)return;const c=s.queue[s.pos];state.cards[c.character]=schedule(state.cards[c.character],r==='good'&&s.hint?'hard':r);s.attempts++;if(r==='good'&&!s.hint)s.right++;const hinted=s.hint;if(r==='again'&&s.attempts<60){s.queue.splice(Math.min(s.queue.length,s.pos+5),0,c)}activity('cards');s.pos++;s.revealed=false;s.hint=false;renderSession();}
function bookmark(c){if(!cardByChar[c])return;const i=state.bookmarks.indexOf(c);if(i>=0)state.bookmarks.splice(i,1);else state.bookmarks.push(c);save();if(currentView==='search')dictionaryResults();toast(i>=0?'Bookmark removed':'Character bookmarked')}
function renderReviewBase(){const due=dueCards(),studied=Object.keys(state.cards).length,weak=Object.values(state.cards).filter(x=>x.streak<1).length;$('view').innerHTML=`<div class="heading"><div><div class="eyebrow">Keep it familiar</div><h1>Review</h1><p class="muted">Return to the characters you've met.</p></div></div><section class="hero"><div><div class="eyebrow">Ready when you are</div><h2>${due.length?due.length+' characters to revisit.':'You’re caught up.'}</h2><p class="muted">${due.length?'A quick check before something new.':'Your reviews will appear here when they are due.'}</p><button class="btn primary" onclick="${due.length?`startSession('review')`:`navigate('learn')`}">${due.length?'Start review':'Explore chapters'} ${icon('arrow')}</button></div><div class="hero-art"><span class="orbit"></span><span class="hero-han">习</span></div></section><div class="stats-grid"><div class="stat"><strong>${studied}</strong><span>Characters practiced</span></div><div class="stat"><strong>${weak}</strong><span>Still getting familiar</span></div><div class="stat"><strong>${state.bookmarks.length}</strong><span>Bookmarked</span></div><div class="stat"><strong>${streak()}</strong><span>Day streak</span></div></div><div class="story-grid"><section class="panel"><h2>The tricky ones</h2><p class="muted">Give uncertain characters a little extra attention.</p><button class="btn" onclick="startSession('weak')">Practice tricky cards</button></section><section class="panel"><h2>Your bookmarks</h2><p class="muted">A personal collection to return to.</p><button class="btn" onclick="startSession('saved')">Practice bookmarks</button></section></div><section class="panel"><h2>This week</h2><div class="week">${weekMarkup()}</div></section>`;}
function renderReadBeforeTools(){$('view').innerHTML=`<div class="heading"><div><div class="eyebrow">From characters to stories</div><h1>A little more to read.</h1><p class="muted">Tap a character for help. Reveal pinyin when you need it.</p></div></div><div class="row" style="margin-bottom:22px"><select aria-label="Reading chapter" onchange="readingFilter(this.value)"><option value="">All chapters</option>${courseChapters().map(c=>`<option value="${c[0]}">${c[1]}</option>`).join('')}</select><span class="small muted">${Object.keys(state.read).length} of 22 completed</span></div><div id="stories">${storyCards()}</div>`;}
function readingFilter(id){$('stories').innerHTML=storyCards(id)}
let activeReading=null;function openReading(id){const reading=READINGS.find(r=>r.id===id);if(!reading)return;ensureLessonCourse(reading.lesson);rememberPage('reader',true);activeReading=id;currentView='reader';chrome();renderReader(id);window.scrollTo({top:0,behavior:'instant'})}
function readingSupportMarkup(r){return r.support?.length?`<details class="quiet-details reading-prep" open><summary>Before you read · ${r.support.length} supporting characters</summary><p class="small muted">These few characters help connect the ones from Foundations.</p><div class="reading-support-grid">${r.support.map(([ch,py,meaning])=>`<div><button class="textbtn" lang="zh" onclick="openStudyCharacter('${ch}')" aria-label="Look up ${text(ch)}">${text(ch)}</button><span>${esc(py)}</span><small>${esc(meaning)}</small><button class="iconbtn" aria-label="Listen to ${text(ch)}" onclick="speak(text('${ch}'))">${icon('sound')}</button></div>`).join('')}</div></details>`:''}
function renderReaderBeforeTools(id){const r=READINGS.find(x=>x.id===id);$('view').innerHTML=`<div class="reader"><button class="textbtn back" onclick="navigate('read')">${icon('back')} Reading library</button><div class="eyebrow">${r.lesson==='I'?'Foundations':lessonLabel(r.lesson)} · ${r.lines.length} paragraphs</div><h1>${r.title}</h1><p class="muted">${r.subtitle}</p><div class="reader-controls"><button class="btn" aria-pressed="${readerOptions.pinyin}" onclick="readerOptions.pinyin=!readerOptions.pinyin;renderReader('${id}')">Pinyin</button><button class="btn" aria-pressed="${readerOptions.translation}" onclick="readerOptions.translation=!readerOptions.translation;renderReader('${id}')">Translation</button><button class="btn" onclick="speak(READINGS.find(r=>r.id==='${id}').lines.map(l=>l[0]).join(''))">${icon('sound')} Listen</button><select aria-label="Reading text size" onchange="setSetting('size',Number(this.value));renderReader('${id}')">${[23,27,32].map(n=>`<option value="${n}" ${state.settings.size===n?'selected':''}>${n===23?'Small':n===27?'Medium':'Large'} text</option>`).join('')}</select></div>${readingSupportMarkup(r)}<section class="panel">${r.lines.map((l,i)=>`<div class="reader-line"><div class="zh-line">${[...l[0]].map(c=>/[\u3400-\u9fff]/.test(c)?`<button class="char-tap ${readerOptions.highlight!==false&&!state.cards[c]?.streak?'unfamiliar-char':''}" aria-label="Look up ${text(c)}${!state.cards[c]?.streak?' · unfamiliar':''}" onclick="openStudyCharacter('${c}')">${text(c)}</button>`:esc(c)).join('')}<button class="textbtn" aria-label="Listen to paragraph ${i+1}" onclick="speak(READINGS.find(r=>r.id==='${id}').lines[${i}][0])">${icon('sound')}</button></div>${readerOptions.pinyin?`<div class="reading-pinyin">${l[1]}</div>`:''}${readerOptions.translation?`<div class="reading-en">${l[2]}</div>`:''}</div>`).join('')}</section><section id="reading-quiz" class="panel reading-quiz">${readingQuizMarkup(id)}</section></div>`;}
function completeReading(id){startReadingQuiz(id)}
let lookupFocus=null;function showCharacterBase(ch){lookupFocus=document.activeElement;const c=cardByChar[ch]||extra[ch];if(!c)return;$('overlay').innerHTML=`<div class="modal-bg" onclick="if(event.target===this)closeModal()"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="lookup-title"><button class="iconbtn modal-close" onclick="closeModal()" aria-label="Close character">${icon('close')}</button><div class="han">${han(c)}</div><div class="row character-pronunciation"><h2 id="lookup-title">${esc(c.pinyin)}</h2></div><p>${esc(c.meaning)}</p><p class="small muted">${c.traditional!==c.character?'Simplified '+c.character+' · Traditional '+c.traditional:''}</p><div class="row"><button class="btn" aria-label="Listen to ${c.character}" onclick="speak('${c.character}')">${icon('sound')} Listen</button>${c.lesson!=='extra'? `<button class="btn" onclick="bookmark('${ch}');showCharacter('${ch}')">${star(ch)} ${state.bookmarks.includes(ch)?'Saved':'Save'}</button>`:''}</div>${exampleMarkup(c)}</section></div>`;const modal=document.querySelector('.modal');modal.querySelector('button').focus();}
function closeModal(){if(lookupCardHistory.length){$('overlay').innerHTML=lookupCardHistory.pop();activateStudyCharacters(document.querySelector('.modal'));document.querySelector('.modal button')?.focus();return}$('overlay').innerHTML='';if(lookupFocus?.isConnected)lookupFocus.focus()}
function speak(s,rateOverride){if(!('speechSynthesis' in window)){toast('Audio is not supported in this browser.');return}const voices=speechSynthesis.getVoices(),voice=voices.find(v=>/zh[-_]CN/i.test(v.lang))||voices.find(v=>/^zh/i.test(v.lang));speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(s);u.lang='zh-CN';if(voice)u.voice=voice;u.rate=[.65,.8,1].includes(rateOverride)?rateOverride:[.65,.8,1].includes(state.settings.audioRate)?state.settings.audioRate:.8;u.onerror=()=>toast('Audio could not play. Check your device’s Chinese speech voices.');speechSynthesis.speak(u);}
function renderDictionaryBase(){$('view').innerHTML=`<div class="heading"><div><div class="eyebrow">Find a familiar word</div><h1>Dictionary</h1><p class="muted">Search by character, pinyin, or meaning.</p></div></div><div class="searchbar"><input class="input" id="dict-search" aria-label="Search dictionary" placeholder="Try 妈, mā, or mom" value="${esc(dictQuery)}" oninput="dictQuery=this.value;dictionaryResults()"><select aria-label="Dictionary filter" id="dict-filter" onchange="dictFilter=this.value;dictionaryResults()"><option value="all">All characters</option><option value="saved">Bookmarked</option>${courseChapters().map(c=>`<option value="${c[0]}">${c[1]}</option>`).join('')}</select></div><div id="dictionary-results"></div>`;$('dict-filter').value=dictFilter;dictionaryResults();}
const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
function dictionaryResults(){const q=normalize(dictQuery.trim()),cc=CARDS.filter((c,i,a)=>a.findIndex(x=>x.character===c.character)===i).filter(c=>(dictFilter==='all'||dictFilter==='saved'&&state.bookmarks.includes(c.character)||c.lesson===dictFilter)&&normalize([c.character,c.traditional,c.pinyin,c.meaning,c.word].join(' ')).includes(q));if(state.settings.savedFirst)cc.sort((a,b)=>Number(state.bookmarks.includes(b.character))-Number(state.bookmarks.includes(a.character)));$('dictionary-results').innerHTML=`<p class="small muted">${cc.length} characters</p><div class="dictionary-list">${cc.map(c=>`<div class="dict-card"><button class="textbtn dict-char" onclick="showCharacter('${c.character}')">${han(c)}</button><div class="dict-body"><strong style="color:var(--green)">${esc(c.pinyin)}</strong><p>${esc(c.meaning)}</p><small>${text(c.word)}</small></div><button class="iconbtn" aria-label="${state.bookmarks.includes(c.character)?'Remove bookmark':'Bookmark'} ${han(c)}" onclick="bookmark('${c.character}');dictionaryResults()" style="color:${state.bookmarks.includes(c.character)?'var(--accent)':'var(--muted)'}">${star(c.character)}</button></div>`).join('')}</div>${cc.length?'':'<div class="empty muted">No matches. Try a different word.</div>'}`;}
function renderSettingsBeforeQoL(){$('view').innerHTML=`<div class="heading"><div><div class="eyebrow">Make it yours</div><h1>Chinese 1, your way.</h1><p class="muted">A comfortable place to keep coming back to.</p></div></div><div class="settings-grid"><section class="panel"><h2>Appearance & learning</h2><div class="palette-section"><strong>Color palette</strong><p class="small muted">Soft colors, in light or dark.</p><div class="palette-options">${Object.entries(PALETTES).map(([id,p])=>`<button class="palette-choice ${state.settings.palette===id?'selected':''}" aria-pressed="${state.settings.palette===id}" onclick="setSetting('palette','${id}');renderSettings()"><span class="palette-dot" style="background:${p.brandPale};border-color:${p.brandDark}"></span><span>${p.name}</span></button>`).join('')}</div></div><div class="setting-row"><div><strong>Theme</strong><p>Choose your light.</p></div><select aria-label="Theme" onchange="setSetting('theme',this.value)">${['system','light','dark'].map(v=>`<option value="${v}" ${state.settings.theme===v?'selected':''}>${v[0].toUpperCase()+v.slice(1)}</option>`).join('')}</select></div><div class="setting-row"><div><strong>Characters</strong><p>Your preferred script.</p></div><select aria-label="Character script" onchange="setSetting('script',this.value)">${['simplified','traditional'].map(v=>`<option value="${v}" ${state.settings.script===v?'selected':''}>${v[0].toUpperCase()+v.slice(1)}</option>`).join('')}</select></div><div class="setting-row"><div><strong>Daily goal</strong><p>Card reviews per day.</p></div><select aria-label="Daily goal" onchange="setSetting('goal',Number(this.value))">${[10,20,30,50].map(v=>`<option value="${v}" ${state.settings.goal===v?'selected':''}>${v} reviews</option>`).join('')}</select></div><div class="setting-row"><div><strong>Reading size</strong><p>Give your eyes some room.</p></div><select aria-label="Reading size" onchange="setSetting('size',Number(this.value))">${[23,27,32].map(v=>`<option value="${v}" ${state.settings.size===v?'selected':''}>${v===23?'Small':v===27?'Medium':'Large'}</option>`).join('')}</select></div></section><section class="panel"><h2>Your progress</h2><p class="muted small">Progress saves on this device. Export a backup to move it to another phone or computer.</p><div class="row" style="margin:20px 0"><button class="btn" onclick="exportBackup()">${icon('download')} Export backup</button><button class="btn" onclick="$('backup-file').click()">Import backup</button></div><p class="small muted">${storageOK?'Automatic saving is available.':'Automatic saving is unavailable in this browser. Export a backup before leaving.'}</p><div class="setting-row"><div><strong>Start fresh</strong><p>Clear learning progress and bookmarks.</p></div><button class="btn danger" onclick="resetProgress()">Reset</button></div></section></div><section class="panel"><h2>Controls & references</h2><p class="small muted">Desktop: the sidebar button hides or pins navigation. Move to the left edge to show it. Space shows the answer. 1 = Again, 2 = Almost, 3 = Got it. Escape closes a character card.</p><p class="small muted">Phone: tap to reveal answers, save characters, and look up words as you read.</p><p class="small muted">Audio uses a Chinese speech voice installed on your device. New readings are written for practice; character cues are memory aids.</p><details><summary>Character component reference</summary><p class="small muted">Selected structural data from <a href="https://github.com/skishore/makemeahanzi" target="_blank" rel="noopener">Make Me a Hanzi</a>, derived from Unihan and CJKlib, under <a href="https://www.gnu.org/licenses/lgpl-3.0.html" target="_blank" rel="noopener">LGPL 3 or later</a>. This app selects structural fields and adds original learning explanations and visual notes. The source includes uncertain stroke groups; those are labeled rather than given invented meanings.</p><button class="btn" onclick="exportComponents()">Download component data</button></details></section>`;}
function setSetting(k,v){if(k==='sessionLength'&&![5,10,20].includes(v)||k==='writingMethod'&&!['draw','type','paper'].includes(v)||['compactExplanations','detailedExamples'].includes(k)&&typeof v!=='boolean')return;state.settings[k]=v;save();theme();chrome();if(k==='script'){if(currentView==='quiz')renderQuiz();else if(currentView==='session')renderSession();else if(currentView==='chapter')renderChapter();else if(currentView==='search')dictionaryResults();else if(currentView==='home')renderHome();else if(currentView==='write')renderWrite();else if(currentView==='reader')renderReader(activeReading);else if(currentView==='components')renderComponents();else if(currentView==='confusions')renderConfusions();else if(currentView==='results')renderResults()}}
function exportBackup(){syncCourseState();const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='Chinese_1_Progress_'+dayKey()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('Progress backup exported')}
$('backup-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>2000000)throw Error('That file is too large for a progress backup.');const next=validateState(JSON.parse(await f.text()));if(!confirm('Replace this device’s progress with this backup?'))return;captureSafetyCopy('Before import',true);state=next;adoptCourseState();save();theme();chrome();renderSettings();toast('Progress restored');}catch(err){toast(err.message||'That backup could not be opened.')}finally{e.target.value=''}};
function resetProgress(){if(!confirm('Clear all character progress, completed readings, activity, and bookmarks? Export a backup first if you want to keep them.'))return;clearSavedSession();const settings=state.settings;state=defaults();state.settings=settings;save();chrome();renderSettings();toast('Progress reset');}
document.addEventListener('keydown',handlePracticeKeydown);
// Modal keyboard focus is handled once by the visibility-aware handler below.

function renderWriteBeforeQoL(){if(writeSession){renderWritingSession();return}$('view').innerHTML=`<div class="heading"><div><div class="eyebrow">Writing studio</div><h1>Write it. Then take a look.</h1><p class="muted">Draw, type, or write on paper.</p></div></div><section class="panel"><div class="row"><div><label class="label" for="write-chapter">Chapter</label><select id="write-chapter">${courseChapters().map(c=>`<option value="${c[0]}" ${c[0]===chapter?'selected':''}>${c[1]}</option>`).join('')}</select></div><div><label class="label" for="write-kind">Practice</label><select id="write-kind"><option value="characters">Characters</option><option value="words">Useful words</option></select></div><div><label class="label" for="write-prompt">Prompt</label><select id="write-prompt"><option value="pinyin">Pinyin & meaning</option><option value="meaning">Meaning only</option></select></div></div><button class="btn primary" style="margin-top:22px" onclick="startWriting($('write-chapter').value,$('write-kind').value,$('write-prompt').value)">Start writing ${icon('arrow')}</button></section><div class="story-grid writing-methods"><section class="panel"><h2>Draw</h2><p class="muted">Use your finger, stylus, or mouse on the drawing pad. Reveal the character and compare your writing.</p></section><section class="panel"><h2>Type</h2><p class="muted">Use a Chinese keyboard to enter the character or word. For example, type 你好 for nǐ hǎo. Reveal checks whether your answer matches.</p></section><section class="panel"><h2>Paper</h2><p class="muted">Write on paper, reveal the model, and mark whether you wrote it correctly.</p></section></div>`;}
function startWriting(id,kind='characters',prompt='pinyin'){rememberPage('write',true);const pool=kind==='words'?WORDS[id].map(w=>({target:w[0],pinyin:w[1],meaning:w[2]})):CARDS.filter(c=>c.lesson===id).map(c=>({target:c.character,pinyin:c.pinyin,meaning:c.meaning}));writeSession={id,kind,prompt,queue:shuffle(pool).slice(0,state.settings.sessionLength),pos:0,revealed:false,hint:false,usedHint:false,done:false,tool:state.settings.writingMethod,strokes:[],typed:'',right:0,attempts:0};currentView='write';chrome();renderWrite();window.scrollTo({top:0,behavior:'instant'});}
function writingHint(w){return [...w.target].map(c=>{const card=cardByChar[c];return card?card.cue.split(c).join('□'):'Think of the word you already know.'}).join(' ');}
function renderWritingSessionBase(){const s=writeSession,w=s.queue[s.pos];if(!w){$('view').innerHTML=`<section class="panel empty"><div class="empty-glyph">写</div><div class="eyebrow">Writing complete</div><h1>A little more familiar.</h1><p class="muted">${s.right} correct without hints across ${s.attempts} attempts.</p><div class="row" style="justify-content:center"><button class="btn primary" onclick="writeSession=null;renderWrite()">Another session</button><button class="btn" onclick="openChapter('${s.id}')">Back to chapter</button></div></section>`;return;}
$('view').innerHTML=`<div class="session-wrap"><div class="session-top"><button class="textbtn" onclick="finishWriting()">${icon('close')} Finish later</button><span class="muted">${s.pos+1} / ${s.queue.length}</span></div><div class="progress" style="margin-bottom:18px"><span style="width:${s.pos/s.queue.length*100}%"></span></div><section class="panel" style="text-align:center"><div class="eyebrow">${s.kind==='words'?'Write the word':'Write the character'}</div>${s.prompt==='pinyin'?`<h1 style="font-size:32px;color:var(--green);margin-top:24px">${esc(w.pinyin)}</h1>`:''}<h2 style="margin:18px 0">${esc(w.meaning)}</h2><p class="muted small">${[...w.target].length} character${[...w.target].length===1?'':'s'} · ${state.settings.script}</p>${!s.revealed?`<button class="textbtn" onclick="writingHintToggle()">${s.hint?'Hide hint':'Need a hint?'}</button>${s.hint?`<p class="cue">${esc(writingHint(w))}</p>`:''}`:''}<div class="tabs" style="margin:20px auto"><button class="${s.tool==='draw'?'active':''}" onclick="writingTool('draw')">Draw</button><button class="${s.tool==='type'?'active':''}" onclick="writingTool('type')">Type</button><button class="${s.tool==='paper'?'active':''}" onclick="writingTool('paper')">Paper</button></div>${s.tool==='draw'?`<canvas id="write-canvas" aria-label="Optional handwriting pad" style="display:block;width:100%;height:260px;border:1px solid var(--line);border-radius:12px;touch-action:none;background:var(--bg)"></canvas><div class="row" style="justify-content:center;margin:10px 0"><button class="textbtn" onclick="writeSession.strokes.pop();paintCanvas();checkpointCurrent()">Undo</button><button class="textbtn" onclick="writeSession.strokes=[];paintCanvas();checkpointCurrent()">Clear</button></div>`:s.tool==='type'?`<p id="typing-help" class="small muted">Type Chinese characters using your device’s Chinese keyboard, then reveal to compare. Pinyin alone won’t match the answer.</p><input class="input" id="typed-answer" style="font-size:28px;width:100%;text-align:center" aria-label="Type your Chinese answer" aria-describedby="typing-help" lang="zh" autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="Enter Chinese characters…" value="${esc(s.typed)}" oninput="writeSession.typed=this.value;checkpointCurrent()" ${s.revealed?'readonly':''}>`:`<p class="muted" style="padding:15px 0">Write on paper, then reveal when you're ready.</p>`}${s.revealed?`<div class="han" style="font-size:${w.target.length>3?50:75}px;line-height:1.6">${text(w.target)}</div><div class="pinyin">${esc(w.pinyin)}</div><button class="textbtn" onclick="speak('${w.target}')">${icon('sound')} Listen</button>${s.tool==='type'&&s.typed?`<p class="${s.typed.trim()===text(w.target)?'success':'muted'}">${s.typed.trim()===text(w.target)?'Your typed answer matches.':'Compare your answer with the model above.'}</p>`:''}<p class="small muted">Compare your writing with the model.</p>`:''}</section>${s.revealed?`<div class="rate-row" style="grid-template-columns:1fr 1fr"><button class="btn danger" onclick="rateWriting(false)">Try again</button><button class="btn primary" onclick="rateWriting(true)">Wrote it correctly</button></div>`:`<button class="btn primary full" onclick="revealWriting()">Reveal answer</button>`}</div>`;if(s.tool==='draw')initCanvas();}
function writingTool(tool){if(!['draw','type','paper'].includes(tool))return;writeSession.tool=tool;state.settings.writingMethod=tool;save();renderWritingSession();if(tool==='type')$('typed-answer')?.focus()}
function finishWriting(){if(confirm('Finish this writing session? Completed attempts are saved.')){writeSession=null;renderWrite()}}
function rateWriting(got){const s=writeSession;if(!s?.revealed)return;const w=s.queue[s.pos];s.attempts++;if(got&&!s.hint){s.right++;state.writing??={};state.writing[w.target]=(state.writing[w.target]||0)+1;}else if(!got&&s.attempts<40){s.queue.splice(Math.min(s.queue.length,s.pos+4),0,w)}save();activity('cards');s.pos++;s.revealed=false;s.hint=false;s.typed='';s.strokes=[];renderWritingSession();}
function paintCanvas(){const canvas=$('write-canvas');if(!canvas)return;const ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height;ctx.clearRect(0,0,w,h);ctx.strokeStyle=getComputedStyle(document.documentElement).getPropertyValue('--line');ctx.lineWidth=1;ctx.setLineDash([6,6]);ctx.beginPath();ctx.moveTo(w/2,0);ctx.lineTo(w/2,h);ctx.moveTo(0,h/2);ctx.lineTo(w,h/2);ctx.moveTo(0,0);ctx.lineTo(w,h);ctx.moveTo(w,0);ctx.lineTo(0,h);ctx.stroke();ctx.setLineDash([]);ctx.strokeStyle=getComputedStyle(document.documentElement).getPropertyValue('--ink');ctx.lineWidth=4*devicePixelRatio;ctx.lineCap='round';ctx.lineJoin='round';for(const points of writeSession.strokes){if(!points.length)continue;ctx.beginPath();ctx.moveTo(points[0][0]*w,points[0][1]*h);if(points.length===1)ctx.lineTo(points[0][0]*w+.1,points[0][1]*h+.1);for(const p of points.slice(1))ctx.lineTo(p[0]*w,p[1]*h);ctx.stroke();}}
function initCanvas(){const c=$('write-canvas');c.width=c.clientWidth*devicePixelRatio;c.height=(c.clientHeight||260)*devicePixelRatio;paintCanvas();let drawing=false;const point=e=>{const b=c.getBoundingClientRect();return [Math.max(0,Math.min(1,(e.clientX-b.left)/b.width)),Math.max(0,Math.min(1,(e.clientY-b.top)/b.height))]};c.onpointerdown=e=>{if(writeSession.revealed)return;e.preventDefault();drawing=true;c.setPointerCapture(e.pointerId);writeSession.strokes.push([point(e)]);paintCanvas()};c.onpointermove=e=>{if(!drawing)return;writeSession.strokes.at(-1).push(point(e));paintCanvas()};c.onpointerup=c.onpointercancel=()=>{drawing=false;checkpointCurrent()};}
window.addEventListener('resize',()=>{if(currentView==='write'&&writeSession?.tool==='draw'&&$('write-canvas'))initCanvas()});
// Study flow, quizzes, and navigation.
let quizSession=null,sidebarTimer=null;
function uniqueCards(id){const pool=CARDS.filter(c=>id?c.lesson===id:currentCourse().lessons.includes(c.lesson));return pool.filter((c,i,a)=>a.findIndex(x=>x.character===c.character)===i)}
function familiar(c){return (state.cards[c.character]?.streak||0)>=1}
function progress(id){const cc=uniqueCards(id),known=cc.filter(familiar).length,practiced=cc.filter(c=>state.cards[c.character]?.seen>0).length;return {total:cc.length,known,practiced,percent:Math.round(practiced/cc.length*100),familiarPercent:Math.round(known/cc.length*100)}}
function coverageMarkup(id){const p=progress(id);return `<div class="progress-caption"><span>Chapter coverage · ${p.practiced}/${p.total} practiced</span><span>${p.percent}%</span></div><div class="progress" role="progressbar" aria-label="Chapter coverage" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${p.percent}"><span style="width:${p.percent}%"></span></div><div class="progress-caption"><span>Familiar · ${p.known}/${p.total}</span><span>${p.familiarPercent}%</span></div><div class="progress familiar-progress" role="progressbar" aria-label="Familiar characters" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${p.familiarPercent}"><span style="width:${p.familiarPercent}%"></span></div>`}
function star(ch){return `<svg viewBox="0 0 24 24" aria-hidden="true" class="${state.bookmarks.includes(ch)?'filled-star':''}"><path d="${PATHS.star}"/></svg>`}
function updateSidebar(){const pinned=state.settings.sidebarPinned!==false;document.body.classList.toggle('sidebar-auto',!pinned);const b=$('sidebar-toggle');b.innerHTML=icon(pinned?'hidebar':'pin');b.setAttribute('aria-label',pinned?'Hide sidebar':'Keep sidebar pinned');b.setAttribute('title',pinned?'Hide sidebar':'Keep sidebar pinned');b.setAttribute('aria-pressed',String(pinned));if(pinned)document.body.classList.remove('sidebar-open')}
function toggleSidebar(){state.settings.sidebarPinned=state.settings.sidebarPinned===false;save();updateSidebar();document.body.classList.remove('sidebar-open');if(!state.settings.sidebarPinned){$('view').setAttribute('tabindex','-1');$('view').focus()}}
function showSidebar(){clearTimeout(sidebarTimer);if(state.settings.sidebarPinned===false&&matchMedia('(min-width: 761px)').matches)document.body.classList.add('sidebar-open')}
function hideSidebar(){clearTimeout(sidebarTimer);sidebarTimer=setTimeout(()=>{const sb=document.querySelector('.sidebar');if(!sb.contains(document.activeElement))document.body.classList.remove('sidebar-open')},160)}
function startSession(mode,id,characters){if(id&&!ensureLessonCourse(id))return;rememberPage('session',true);let pool=characters?characters.map(c=>courseCard(c,id)).filter(Boolean):uniqueCards(id);if(mode==='review')pool=dueCards();if(mode==='saved')pool=pool.filter(c=>state.bookmarks.includes(c.character));if(mode==='weak')pool=pool.filter(c=>state.cards[c.character]&&!familiar(c));if(mode==='learn'){const unseen=pool.filter(c=>!state.cards[c.character]?.seen);pool=unseen.length?unseen:pool.filter(c=>!familiar(c)).length?pool.filter(c=>!familiar(c)):shuffle(pool);pool=pool.slice(0,state.settings.sessionLength)}else pool=shuffle(pool);pool=pool.slice(0,mode==='all'?pool.length:state.settings.sessionLength);session={queue:pool.slice(),batch:pool.map(c=>c.character),mode,id,pos:0,attempts:0,right:0,revealed:false,done:false,hint:false,usedHint:false,started:Date.now()};currentView='session';chrome();renderSession();window.scrollTo({top:0,behavior:'instant'})}
function nextStep(id){const next=courseChapters()[courseChapters().findIndex(c=>c[0]===id)+1];if(!id)return {label:'Continue learning',action:`openChapter('${state.lastChapter}')`};const p=progress(id);if(p.practiced<p.total)return {label:'Next session',action:`startSession('learn','${id}')`};if(!state.quizzes.chapters[id]?.passed)return {label:'Continue to chapter quiz',action:`startQuiz('chapter','${id}')`};return next?{label:`Continue to ${next[0]==='I'?'Foundations':'Chapter '+next[0]}`,action:`openChapter('${next[0]}')`}:{label:'Continue with a review quiz',action:`startQuiz('review')`}}
function continuationMarkup(id,chars,kind='cards'){const n=nextStep(id);const relevant=id&&kind==='cards'&&READINGS.some(r=>r.lesson===id);return `<div class="completion-actions"><button class="btn primary continue-btn" onclick="${n.action}">${n.label} ${icon('arrow')}</button><div class="row completion-secondary">${chars?.length?`<button class="btn" onclick="startWritingBatch('${id||state.lastChapter}','${chars.join('')}')">${icon('write')} Write these ${chars.length} characters</button>`:''}<button class="btn" onclick="navigate('home')">Home</button>${relevant?`<button class="btn reading-next" onclick="openChapter('${id}');chapterTab('read')">${icon('read')} Try a reading</button>`:''}</div></div>`}
function renderSessionBeforeTools(){const s=session;if(!s)return navigate('learn');const c=s.queue[s.pos];if(!c){s.done=true;const pct=s.attempts?Math.round(s.right/s.attempts*100):0;$('view').innerHTML=`<div class="session-wrap"><section class="panel completion"><div class="eyebrow">${s.attempts?'Session complete':'Nothing to review'}</div><h1>${s.attempts?'Practice complete':'Choose your next session'}</h1>${s.attempts?`<div class="score-ring">${pct}%</div><p class="muted">${s.right} correct without hints · ${s.attempts} reviews</p>${s.id?coverageMarkup(s.id):''}`:''}${continuationMarkup(s.id,s.attempts?s.batch:[])}</section></div>`;return}renderSessionBase();if(s.revealed){const flash=document.querySelector('.flashcard');flash.insertAdjacentHTML('beforeend',studyDetailsMarkup(c));activateStudyCharacters(flash)}}
function flashHint(){if(!session||session.revealed||session.done)return;session.hintLevel=(session.hintLevel||0)+1;if(session.hintLevel>3){session.hintLevel=0;session.hint=false}else{session.hint=true;session.usedHint=true}renderSession()}
function rateBeforeTools(r){const s=session;if(!s||s.done||!s.revealed||!['again','hard','good'].includes(r))return;const c=s.queue[s.pos],hinted=s.usedHint||s.hint;state.cards[c.character]=schedule(state.cards[c.character],r==='good'&&hinted?'hard':r);s.attempts++;if(r==='good'&&!hinted)s.right++;if(r==='again'&&s.attempts<60)s.queue.splice(Math.min(s.queue.length,s.pos+5),0,c);activity('cards');s.pos++;s.revealed=false;s.hint=false;s.usedHint=false;s.hintLevel=0;s.covered=false;renderSession()}
function renderChapterBeforeTools(){renderChapterBase();const p=progress(chapter);const view=$('view');view.innerHTML=view.innerHTML.replace(/<div class="progress"><span style="width:[^]*?<div class="tabs">/,coverageMarkup(chapter)+'<div class="tabs">');const tabs=view.querySelector('.tabs');tabs.insertAdjacentHTML('beforeend',`<button class="${tab==='quiz'?'active':''}" onclick="chapterTab('quiz')">Quiz ${state.quizzes.chapters[chapter]?.passed?'✓':''}</button>`);if(tab==='quiz'){const status=state.quizzes.chapters[chapter];const content=`<section class="panel"><h2>Chapter quiz</h2><p class="muted">${p.total} characters · 80% correct without hints to pass</p><p>Choose the character matching each pinyin and meaning. Review each answer’s components before continuing.</p>${status?`<p class="badge">Last result: ${status.score}% · ${status.passed?'Passed':'Practice and retry'}</p>`:''}<button class="btn primary full continue-btn" onclick="startQuiz('chapter','${chapter}')">${status?.passed?'Retake chapter quiz':'Start chapter quiz'} ${icon('arrow')}</button></section>`;view.innerHTML=view.innerHTML.slice(0,view.innerHTML.indexOf('</div>',view.innerHTML.indexOf('<div class="tabs">'))+6)+content}else view.insertAdjacentHTML('beforeend',`<section class="panel chapter-check"><div class="row" style="justify-content:space-between"><div><h2>Chapter quiz</h2><p class="small muted">${state.quizzes.chapters[chapter]?.passed?'Passed · ready for the next chapter':p.percent===100?'All characters practiced · check what you remember':p.total+' questions · take it when you are ready'}</p></div><button class="btn ${p.percent===100?'primary':''}" onclick="startQuiz('chapter','${chapter}')">${state.quizzes.chapters[chapter]?.passed?'Retake quiz':'Take chapter quiz'}</button></div></section>`)}
function renderHomeBeforeTools(){renderHomeBase();const total=uniqueCards().filter(familiar).length;const stat=document.querySelector('.stat');stat.insertAdjacentHTML('beforeend',`<div class="progress" role="progressbar" aria-label="Familiar characters" aria-valuemin="0" aria-valuemax="400" aria-valuenow="${total}"><span style="width:${total/400*100}%"></span></div><small class="muted">${Math.round(total/400*1000)/10}% familiar</small>`)}
function renderReviewBeforeTools(){renderReviewBase();const count=uniqueCards().filter(familiar).length;$('view').insertAdjacentHTML('beforeend',`<section class="panel"><h2>Quiz learned characters</h2><p class="muted">${count} familiar characters · up to ${state.settings.sessionLength} questions per quiz</p><button class="btn" onclick="startReviewPrep()">Study cards first</button> <button class="btn primary" ${count?'':'disabled'} onclick="startQuiz('review')">Start review quiz ${icon('arrow')}</button>${state.quizzes.review?`<p class="small muted" style="margin-top:12px">Last quiz: ${state.quizzes.review.score}%</p>`:''}<p class="small muted" style="margin-top:14px">To unlearn a character, open it in the dictionary and choose Unlearn.</p></section>`)}
function renderDictionaryBeforeTools(){renderDictionaryBase();$('view').querySelector('.searchbar').insertAdjacentHTML('afterend',`<label class="saved-first"><input type="checkbox" ${state.settings.savedFirst?'checked':''} onchange="setSetting('savedFirst',this.checked);dictionaryResults()"> Bookmarks first</label>`)}
function showCharacter(ch){if(!$('overlay').innerHTML)lookupCardHistory=[];showCharacterBase(ch);const modal=document.querySelector('.modal'),c=cardByChar[ch]||extra[ch];if(!c)return;modal.insertAdjacentHTML('beforeend',componentMarkup(ch));if(state.cards[ch]||state.writing[ch])modal.insertAdjacentHTML('beforeend',`<div class="unlearn-row"><button class="btn danger" onclick="unlearn('${ch}')">Unlearn ${han(c)}</button><p class="small muted">Removes familiarity and writing progress for this character.</p></div>`)}
function unlearn(ch){if(!cardByChar[ch]||!confirm(`Unlearn ${text(ch)}? This resets its learning and writing progress and affected chapter quiz results. Your bookmarks and activity history stay saved.`))return;clearSavedSession();delete state.quizMisses[ch];delete state.cards[ch];for(const w of Object.keys(state.writing))if(w.includes(ch))delete state.writing[w];for(const c of CARDS.filter(c=>c.character===ch))delete state.quizzes.chapters[c.lesson];state.quizzes.review=null;save();closeModal();chrome();if(currentView==='search')dictionaryResults();else if(currentView==='chapter')renderChapter();else if(currentView==='home')renderHome();else if(currentView==='review')renderReview();toast(`${text(ch)} marked as unlearned`)}
function startWritingBatch(id,chars){startWriting(id);const pool=[...new Set([...chars])].map(ch=>cardByChar[ch]).filter(Boolean);writeSession.queue=pool.slice(0,state.settings.sessionLength).map(c=>({target:c.character,pinyin:c.pinyin,meaning:c.meaning}));writeSession.batch=pool.map(c=>c.character);writeSession.usedHint=false;renderWritingSession()}
function revealWriting(){if(!writeSession||writeSession.revealed)return;writeSession.revealed=true;renderWritingSession()}
function writingHintToggle(){if(!writeSession||writeSession.revealed)return;writeSession.hintLevel=(writeSession.hintLevel||0)+1;if(writeSession.hintLevel>3){writeSession.hintLevel=0;writeSession.hint=false}else{writeSession.hint=true;writeSession.usedHint=true}renderWritingSession()}
function renderWritingSessionBeforeTools(){const s=writeSession,w=s.queue[s.pos];if(!w){s.done=true;$('view').innerHTML=`<div class="session-wrap"><section class="panel completion"><div class="eyebrow">Writing complete</div><h1>Writing session complete</h1><p class="muted">${s.right} correct without hints · ${s.attempts} attempts</p>${continuationMarkup(s.id,null,'write')}<button class="textbtn" style="margin-top:18px" onclick="writeSession=null;renderWrite()">Choose another writing session</button></section></div>`;return}renderWritingSessionBase();if(s.revealed)$('view').querySelector('section.panel').insertAdjacentHTML('beforeend',[...new Set([...w.target])].map(ch=>componentMarkup(ch)).join(''))}
function rateWritingBeforeTools(got){const s=writeSession;if(!s?.revealed||s.done)return;const w=s.queue[s.pos];s.attempts++;for(const ch of new Set([...w.target]))if(cardByChar[ch])state.cards[ch]=schedule(state.cards[ch],got&&!s.hint&&!s.usedHint?'good':got?'hard':'again');if(got&&!s.hint&&!s.usedHint){s.right++;state.writing[w.target]=(state.writing[w.target]||0)+1}else if(!got&&s.attempts<40)s.queue.splice(Math.min(s.queue.length,s.pos+4),0,w);activity('cards');s.pos++;s.revealed=false;s.hint=false;s.usedHint=false;s.hintLevel=0;s.typed='';s.strokes=[];renderWritingSession()}
function startQuiz(kind,id){if(kind==='chapter'&&!ensureLessonCourse(id))return;rememberPage('quiz',true);if(kind==='chapter'){chapter=id;state.lastChapter=id;save()}let pool=kind==='chapter'?uniqueCards(id):uniqueCards().filter(familiar);if(!pool.length){toast('Learn some characters first, then take a review quiz.');return}pool=shuffle(pool);if(kind==='review')pool=pool.slice(0,state.settings.sessionLength);quizSession={kind,id,questions:pool.map(c=>{const distractors=similarQuizChoices(c);return {card:c,choices:shuffle([c,...distractors.slice(0,3)]),choice:null,hint:false,usedHint:false}}),pos:0,right:0,missed:[],done:false,recorded:false};currentView='quiz';chrome();renderQuiz();window.scrollTo({top:0,behavior:'instant'})}
function quizHint(){const q=quizSession?.questions[quizSession.pos];if(!q||q.choice!==null)return;q.hint=!q.hint;q.usedHint=true;renderQuiz()}
function quizChooseBeforeTools(ch){const s=quizSession,q=s?.questions[s.pos];if(!q||s.done||q.choice!==null||!q.choices.some(c=>c.character===ch))return;q.choice=ch;const correct=ch===q.card.character&&!q.usedHint;if(correct)s.right++;else if(cardByChar[q.card.character])s.missed.push(q.card.character);if(cardByChar[q.card.character])state.cards[q.card.character]=schedule(state.cards[q.card.character],correct?'good':'again');activity('cards');renderQuiz()}
function quizNext(){const s=quizSession;if(!s||s.done||s.questions[s.pos]?.choice===null)return;s.pos++;renderQuiz();window.scrollTo({top:0,behavior:'instant'})}
function renderQuizBeforeTools(){const s=quizSession;if(!s)return navigate('review');const q=s.questions[s.pos];if(!q){s.done=true;const score=Math.round(s.right/s.questions.length*100),passed=score>=80;if(!s.recorded){const result={score,passed,total:s.questions.length,right:s.right,at:Date.now()};if(s.kind==='chapter')state.quizzes.chapters[s.id]=result;else if(s.kind==='confusion')state.quizzes.confusion=result;else if(s.skill==='listening')state.quizzes.listening=result;else state.quizzes.review=result;s.recorded=true;save()}const next=s.kind==='confusion'?{label:'Next shape quiz',action:`startConfusionQuiz(${s.group})`}:s.kind==='chapter'&&passed?nextStep(s.id):{label:s.kind==='chapter'?'Retry chapter quiz':'Next review quiz',action:`startQuiz('${s.kind}'${s.id?`, '${s.id}'`:''})`};$('view').innerHTML=`<div class="session-wrap"><section class="panel completion"><div class="eyebrow">${s.kind==='chapter'?'Chapter':s.kind==='confusion'?'Shape':'Review'} quiz complete</div><h1>${s.kind==='chapter'?(passed?'Chapter passed':'Review and retry'):'Quiz results'}</h1><div class="score-ring">${score}%</div><p class="muted">${s.right}/${s.questions.length} correct without hints${s.kind==='chapter'?' · pass mark 80%':''}</p><div class="completion-actions"><button class="btn primary continue-btn" onclick="${next.action}">${next.label} ${icon('arrow')}</button><div class="row">${s.missed.length?`<button class="btn" onclick="practiceQuizMisses()">Practice missed characters (${s.missed.length})</button>`:''}<button class="btn" onclick="writeQuizBatch()">${icon('write')} Practice writing</button>${s.kind==='chapter'&&passed?`<button class="btn" onclick="openChapter('${s.id}');chapterTab('read')">Read this chapter</button>`:''}<button class="btn" onclick="navigate('review')">Review</button></div></div></section></div>`;return}const answered=q.choice!==null;$('view').innerHTML=`<div class="session-wrap"><div class="session-top"><button class="textbtn" onclick="navigate('${s.kind==='chapter'?'chapter':'review'}')">${icon('close')} Finish later</button><span>${s.pos+1} / ${s.questions.length}</span></div><div class="progress"><span style="width:${s.pos/s.questions.length*100}%"></span></div><section class="panel quiz-panel"><div class="eyebrow">${s.kind==='chapter'?'Chapter '+(s.id==='I'?'intro':s.id):s.kind==='confusion'?'Similar character quiz':'Learned character review'}</div><h1 class="quiz-pinyin">${esc(q.card.pinyin)}</h1><p>${esc(q.card.meaning)}</p><p class="small muted">Choose the matching character.</p><div class="quiz-choices">${q.choices.map(c=>`<button class="quiz-choice ${answered?(c.character===q.card.character?'correct':c.character===q.choice?'incorrect':''):''}" ${answered?'disabled':''} onclick="quizChoose('${c.character}')"><span>${han(c)}</span>${answered&&c.character===q.card.character?icon('check'):''}${answered&&c.character===q.choice&&q.choice!==q.card.character?icon('close'):''}</button>`).join('')}</div>${!answered?`<button class="textbtn" onclick="quizHint()">${q.hint?'Hide hint':'Need a hint?'}</button>${q.hint?`<p class="cue">${esc(quizComponentHint(q.card.character))}</p>`:''}`:`<div class="quiz-feedback" role="status"><strong>${q.choice!==q.card.character?'Incorrect':q.usedHint?'Correct with a hint':'Correct'}</strong><p>${han(q.card)} · ${esc(q.card.pinyin)} · ${esc(q.card.meaning)}</p><div class="familiar">${text(q.card.word)}</div>${componentMarkup(q.card.character)}<p class="cue">Memory cue: ${esc(q.card.cue)}</p></div>`}</section>${answered?`<button class="btn primary full continue-btn" onclick="quizNext()">${s.pos===s.questions.length-1?'See results':'Next question'} ${icon('arrow')}</button>`:''}</div>`}
function practiceQuizMisses(){const s=quizSession;startSession('missed',s.id,s.missed)}
function writeQuizBatch(){const s=quizSession;startWritingBatch(s.id||state.lastChapter,s.questions.map(q=>q.card.character).join(''))}


