function libraryReadingMatches(r){const q=readingLibraryQuery.trim().toLocaleLowerCase();return (readingLibraryStatus==='all'||(readingLibraryStatus==='completed'?!!state.read[r.id]:!state.read[r.id]))&&(!q||[r.title,r.subtitle,r.kind||'',...r.lines.flat()].join(' ').toLocaleLowerCase().includes(q))}
