function readingFolderMarkup(){const searching=!!readingLibraryQuery.trim()||readingLibraryStatus!=='all';const folders=courseChapters().map(([id,title,subtitle])=>{const all=READINGS.filter(r=>r.lesson===id),matches=all.filter(libraryReadingMatches),done=all.filter(r=>state.read[r.id]).length;if(searching&&!matches.length)return '';return `<details class="reading-folder" ${searching||readingFoldersOpened?.has(id)?'open':''} ontoggle="readingFolderToggle(this,'${id}')"><summary><span class="reading-folder-icon">${icon('folder')}</span><span class="reading-folder-label"><strong>${id==='I'?'Foundations':`${lessonLabel(id)} · ${esc(title)}`}</strong><span class="small muted">${searching?`${matches.length} matching readings · `:''}${done} of ${all.length} completed</span></span><span class="reading-folder-chevron">${icon('chevron')}</span></summary><div class="reading-folder-body"><p class="small muted">${esc(subtitle)}</p><div class="progress" role="progressbar" aria-label="${esc(title)} reading progress" aria-valuemin="0" aria-valuemax="${all.length}" aria-valuenow="${done}"><span style="width:${all.length?done/all.length*100:0}%"></span></div>${readingStoryCards(matches)}</div></details>`}).join('');return folders||'<section class="panel"><h2>No readings found</h2><p class="muted">Try a different search or choose All readings.</p></section>'}
function readingStoryCards(readings){return `<div class="story-grid">${readings.map(r=>`<button class="story-card" onclick="openReading('${r.id}')"><div class="row" style="justify-content:space-between"><span class="story-icon">${icon('read')}</span><span class="badge">${readingCompletionLabel(r)}</span></div><h3>${esc(r.title)}</h3><p>${esc(r.subtitle)}</p><div class="small muted">${r.lines.length} paragraphs${readingQuizCurrent(r.id)?` · Best quiz: ${state.readingQuizzes[r.id].best}%`:''} · ${state.read[r.id]?'Read again':'Start reading'} ${icon('arrow')}</div></button>`).join('')}</div>`}
function storyCards(id){return readingStoryCards(courseReadings().filter(r=>!id||r.lesson===id))}
function updateReadingLibrary(){const matched=courseReadings().filter(libraryReadingMatches).length;$('reading-library-count').textContent=`${readingLibraryQuery.trim()||readingLibraryStatus!=='all'?matched+' matching · ':''}${courseReadings().filter(r=>state.read[r.id]).length} of ${courseReadings().length} completed`;$('reading-folders').innerHTML=readingFolderMarkup()}
function renderRead(){if(!readingFoldersOpened)readingFoldersOpened=new Set([Object.keys(state.cards).length?state.lastChapter:'I']);$('view').innerHTML=`<div class="heading"><div><h1>Reading library</h1></div></div><div class="reading-library-controls"><label class="reading-library-search"><span class="small muted">Search readings</span><input type="search" aria-label="Search reading titles or text" placeholder="Title, Chinese, pinyin, or English" value="${esc(readingLibraryQuery)}" oninput="readingLibraryQuery=this.value;updateReadingLibrary()"></label><label><span class="small muted">Show</span><select aria-label="Filter readings by completion" onchange="readingLibraryStatus=this.value;updateReadingLibrary()">${[['all','All readings'],['unread','Not yet read'],['completed','Completed']].map(([value,label])=>`<option value="${value}" ${readingLibraryStatus===value?'selected':''}>${label}</option>`).join('')}</select></label></div><p id="reading-library-count" class="small muted" role="status">${courseReadings().filter(r=>state.read[r.id]).length} of ${courseReadings().length} completed</p><div id="reading-folders" class="reading-folders">${readingFolderMarkup()}</div>`;updateReadingLibrary()}
function renderReader(id){renderReaderBeforeTools(id);const r=READINGS.find(r=>r.id===id),fit=readingFit(r);const controls=$('view').querySelector('.reader-controls');controls.insertAdjacentHTML('afterend',`<details class="quiet-details reading-options"><summary>Reading options · ${fit.percent}% familiar</summary><div class="row"><button class="btn" aria-pressed="${readerOptions.highlight!==false}" onclick="readerOptions.highlight=readerOptions.highlight===false;renderReader('${id}')">${readerOptions.highlight===false?'Highlight unfamiliar':'Hide highlights'}</button><span class="small muted">${fit.unknown.length} unfamiliar characters; tap any character for help.</span></div></details>`);}
function renderChapterBeforeQoL(){renderChapterBeforeTools();$('view').insertAdjacentHTML('beforeend',`<section class="panel"><h2>Chapter results</h2><p class="muted">Recognition, writing, and characters that need practice.</p><button class="btn" onclick="openResults('${chapter}')">View results ${icon('arrow')}</button></section>`)}
function renderDictionary(){$('view').innerHTML=`<div class="heading"><div><h1>Dictionary</h1></div></div><div class="tabs"><button class="active" aria-current="page" onclick="navigate('search')">Characters</button><button onclick="selectedComponent=null;navigate('components')">Components</button></div><div class="searchbar"><input type="search" class="input" id="dict-search" aria-label="Search dictionary" placeholder="Character, pinyin, or meaning" value="${esc(dictQuery)}" oninput="dictQuery=this.value;dictionaryResults()"><select aria-label="Dictionary filter" id="dict-filter" onchange="dictFilter=this.value;dictionaryResults()"><option value="all">All characters</option><option value="saved">Bookmarked</option>${courseChapters().map(c=>`<option value="${c[0]}">${c[1]}</option>`).join('')}</select></div><label class="saved-first"><input type="checkbox" ${state.settings.savedFirst?'checked':''} onchange="setSetting('savedFirst',this.checked);dictionaryResults()"> Bookmarks first</label><div id="dictionary-results"></div>`;$('dict-filter').value=dictFilter;dictionaryResults();}
function renderSessionBeforeQoL(){renderSessionBeforeTools();if(session?.mode==='daily'&&!session.done){const ch=session.queue[session.pos]?.character;if(ch&&session.reasons?.[ch])$('view').querySelector('.session-top').insertAdjacentHTML('afterend',`<span class="badge daily-reason">Daily practice · ${session.reasons[ch]}</span>`)}$('view').insertAdjacentHTML('beforeend',undoMarkup())}
function renderWritingSessionBeforeQoL(){renderWritingSessionBeforeTools();$('view').insertAdjacentHTML('beforeend',undoMarkup())}
function renderQuizBeforeQoL(){renderQuizBeforeTools();const q=quizSession?.questions[quizSession.pos];if(q?.choice!==null&&q?.confusion!==undefined)$('view').querySelector('.quiz-feedback').insertAdjacentHTML('beforeend',`<details open><summary>Shape differences</summary>${compareMarkup(q.confusion)}</details>`);$('view').insertAdjacentHTML('beforeend',undoMarkup())}
function rate(r){if(!session||session.done||!session.revealed||!['again','hard','good'].includes(r))return;const ch=session.queue[session.pos].character;rememberAnswer('cards',session,[ch]);recordPracticeAnswer(session,ch,r);if(r==='good'&&!session.usedHint&&!session.hint)delete state.quizMisses[ch];rateBeforeTools(r)}
function rateWriting(got){if(!writeSession?.revealed||writeSession.done)return;const w=writeSession.queue[writeSession.pos];rememberAnswer('write',writeSession,[...w.target].filter(ch=>cardByChar[ch]),[w.target]);recordPracticeAnswer(writeSession,w.target,got?'good':'again');if(got&&!writeSession.hint&&!writeSession.usedHint)for(const ch of w.target)delete state.quizMisses[ch];rateWritingBeforeTools(got)}
function quizChoose(ch){const s=quizSession,q=s?.questions[s.pos];if(!q||s.done||q.choice!==null||!q.choices.some(c=>c.character===ch))return;rememberAnswer('quiz',s,[q.card.character]);if(ch===q.card.character&&!q.usedHint)delete state.quizMisses[q.card.character];else if(cardByChar[q.card.character])state.quizMisses[q.card.character]=Date.now();quizChooseBeforeTools(ch)}


// Session comfort and resume.
const RESUME_KEY=KEY+'-resume';let savedResume=null,resumeSavingFailed=false;
function sessionLengthControl(){return `<label class="session-size-control">Session size <select aria-label="Session size" onchange="setSetting('sessionLength',Number(this.value));if(currentView==='home')renderHome();else if(currentView==='review')renderReview();else if(currentView==='chapter')renderChapter()">${[5,10,20].map(n=>`<option value="${n}" ${state.settings.sessionLength===n?'selected':''}>${n} items</option>`).join('')}</select></label>`}
function checkpointSession(kind,scope){if(!scope)return;if(scope.done||(kind==='quiz'?scope.pos>=scope.questions.length:scope.pos>=scope.queue.length)){savedResume=null;try{localStorage.removeItem(RESUME_KEY)}catch{}persistCourseResume();return}try{const data=clone(scope);if(kind==='quiz')data.questions=data.questions.map(q=>({...q,card:q.card.character,choices:q.choices.map(c=>c.character)}));else if(kind==='cards'){data.queue=data.queue.map(c=>c.character)}else data.queue=data.queue.map(w=>w.target);savedResume={version:1,kind,chapter,data,savedAt:Date.now()};localStorage.setItem(RESUME_KEY,JSON.stringify(savedResume));persistCourseResume();resumeSavingFailed=false}catch(e){if(!resumeSavingFailed){resumeSavingFailed=true;toast('This session could not be saved for reopening. Progress backups remain available in Settings.')}}}
function checkpointCurrent(){if(currentView==='session')checkpointSession('cards',session);else if(currentView==='write'&&writeSession)checkpointSession('write',writeSession);else if(currentView==='quiz')checkpointSession('quiz',quizSession)}
function validSessionNumber(n,max=2000){return Number.isInteger(n)&&n>=0&&n<=max}
function decodeResume(raw){if(!raw||raw.version!==1||!['cards','write','quiz'].includes(raw.kind)||!raw.data||!CHAPTERS.some(c=>c[0]===raw.chapter))throw Error('Invalid resume');const d=clone(raw.data),id=d.id==null?null:d.id;if(id!==null&&!CHAPTERS.some(c=>c[0]===id))throw Error('Invalid chapter');if(d.done||!validSessionNumber(d.pos,600)||!validSessionNumber(d.right)||!validSessionNumber(d.attempts??0))throw Error('Invalid counts');
if(raw.kind==='quiz'){if(!['chapter','review','confusion'].includes(d.kind)||!Array.isArray(d.questions)||!d.questions.length||d.questions.length>400||d.pos>=d.questions.length||d.right>d.questions.length||d.recorded)throw Error('Invalid quiz');if(d.kind==='chapter'&&(id===null||d.questions.length!==uniqueCards(id).length||new Set(d.questions.map(q=>q.card)).size!==d.questions.length))throw Error('Invalid chapter quiz');if(d.kind==='confusion'&&(!Number.isInteger(d.group)||d.group< -1||d.group>=CONFUSIONS.length))throw Error('Invalid comparison');d.questions=d.questions.map(q=>{const allowed=ch=>d.kind==='confusion'?(!!cardByChar[ch]||CONFUSIONS.some(g=>[...g.chars].includes(ch))):!!cardByChar[ch];if(!q||!allowed(q.card)||!Array.isArray(q.choices)||q.choices.length<2||q.choices.length>4||q.choices.some(ch=>!allowed(ch))||new Set(q.choices).size!==q.choices.length||!q.choices.includes(q.card)||q.choice!==null&&!q.choices.includes(q.choice))throw Error('Invalid question');if(d.kind==='chapter'&&!uniqueCards(id).some(c=>c.character===q.card))throw Error('Invalid chapter character');if(d.kind==='confusion'){if(!Number.isInteger(q.confusion)||q.confusion<0||q.confusion>=CONFUSIONS.length||![...CONFUSIONS[q.confusion].chars].includes(q.card)||q.choices.some(ch=>![...CONFUSIONS[q.confusion].chars].includes(ch)))throw Error('Invalid comparison question')}else delete q.confusion;return {...q,card:d.kind==='chapter'?uniqueCards(id).find(c=>c.character===q.card):contrastCard(q.card),choices:q.choices.map(ch=>ch===q.card&&d.kind==='chapter'?uniqueCards(id).find(c=>c.character===ch):contrastCard(ch)),hint:q.hint===true,usedHint:q.usedHint===true}});d.missed=(Array.isArray(d.missed)?d.missed:[]).filter(ch=>cardByChar[ch]);if(d.questions.slice(0,d.pos).some(q=>q.choice===null))throw Error('Unanswered earlier question');}
else{if(!Array.isArray(d.queue)||!d.queue.length||d.queue.length>600||d.pos>=d.queue.length||d.right>d.attempts)throw Error('Invalid queue');if(raw.kind==='cards'){if(!['learn','all','review','saved','weak','missed','daily','component'].includes(d.mode)||d.queue.some(ch=>!cardByChar[ch]))throw Error('Invalid card');d.queue=d.queue.map(ch=>id?CARDS.find(c=>c.lesson===id&&c.character===ch)||cardByChar[ch]:cardByChar[ch]);d.batch=[...new Set((Array.isArray(d.batch)?d.batch:d.queue.map(c=>c.character)).filter(ch=>cardByChar[ch]))];const reasons={};for(const [ch,r]of Object.entries(d.reasons||{}))if(cardByChar[ch]&&['missed quiz','due review','needs practice','similar character','new','extra review'].includes(r))reasons[ch]=r;if(d.reasons)d.reasons=reasons;}
else{if(!['characters','words'].includes(d.kind)||!['pinyin','meaning'].includes(d.prompt)||!['draw','type','paper'].includes(d.tool)||id===null)throw Error('Invalid writing');const wordMap=Object.fromEntries(Object.values(WORDS).flat().map(w=>[w[0],{target:w[0],pinyin:w[1],meaning:w[2]}]));d.queue=d.queue.map(target=>{if(d.kind==='characters'&&cardByChar[target]){const c=cardByChar[target];return {target,pinyin:c.pinyin,meaning:c.meaning}}if(d.kind==='words'&&wordMap[target])return wordMap[target];throw Error('Invalid writing target')});if(typeof d.typed!=='string'||d.typed.length>200)throw Error('Invalid answer');if(!Array.isArray(d.strokes)||d.strokes.length>500)throw Error('Invalid strokes');let points=0;for(const stroke of d.strokes){if(!Array.isArray(stroke))throw Error('Invalid stroke');points+=stroke.length;if(points>100000)throw Error('Drawing too large');for(const p of stroke)if(!Array.isArray(p)||p.length!==2||p.some(n=>!Number.isFinite(n)||n<0||n>1))throw Error('Invalid point')}if(Array.isArray(d.batch))d.batch=d.batch.filter(ch=>cardByChar[ch]);}
d.hint=d.hint===true;d.revealed=d.revealed===true;d.usedHint=d.usedHint===true;}
if(raw.kind==='quiz'&&d.skill==='listening'){if(d.kind!=='review')throw Error('Invalid listening session');d.questions.forEach(q=>q.heard=q.heard===true)}else if(raw.kind==='quiz')delete d.skill;
if(raw.kind!=='quiz'){d.hintLevel=Number.isInteger(d.hintLevel)&&d.hintLevel>=0&&d.hintLevel<=3?d.hintLevel:0;const allowed=new Set(raw.kind==='cards'?d.queue.map(c=>c.character):d.queue.map(w=>w.target));d.everMissed=[...new Set((Array.isArray(d.everMissed)?d.everMissed:[]).filter(ch=>allowed.has(ch)))];const ratings={};for(const [ch,r]of Object.entries(d.lastRatings||{}))if(allowed.has(ch)&&['again','hard','good'].includes(r))ratings[ch]=r;if(d.lastRatings)d.lastRatings=ratings;}
const recoveredAllowed=new Set(raw.kind==='quiz'?d.questions.map(q=>q.card.character):raw.kind==='cards'?d.queue.map(c=>c.character):d.queue.map(w=>w.target));d.recoveredCharacters=[...new Set((Array.isArray(d.recoveredCharacters)?d.recoveredCharacters:[]).filter(ch=>recoveredAllowed.has(ch)))];if(raw.kind==='quiz')d.questions.forEach(q=>q.recoveredRecall=q.recoveredRecall===true&&q.choice===q.card.character&&!q.usedHint);d.targetedPractice=raw.kind==='cards'&&d.targetedPractice===true;validateMemorySession(d,raw.kind);d.done=false;return {kind:raw.kind,chapter:raw.chapter,data:d,savedAt:Number.isFinite(raw.savedAt)?raw.savedAt:Date.now()}}
function loadSavedSession(){try{const text=localStorage.getItem(RESUME_KEY);const raw=state.courses.records[selectedCourseId].resume||(text?JSON.parse(text):null);if(!raw)return;if(courseForLesson(raw.chapter)?.id!==selectedCourseId)return;decodeResume(raw);savedResume=raw}catch(e){savedResume=null;try{localStorage.removeItem(RESUME_KEY)}catch{}}}
function resumeSession(){if(!savedResume)return;let r;try{r=decodeResume(savedResume)}catch{savedResume=null;return}rememberPage(r.kind==='cards'?'session':r.kind==='write'?'write':'quiz',true);chapter=r.chapter;undoAnswers=[];if(r.kind==='cards'){session=r.data;currentView='session'}else if(r.kind==='write'){writeSession=r.data;currentView='write'}else{quizSession=r.data;currentView='quiz'}chrome();if(r.kind==='cards')renderSession();else if(r.kind==='write')renderWritingSession();else renderQuiz();window.scrollTo({top:0,behavior:'instant'})}
function resumePanel(){if(!savedResume)return '';const kind=savedResume.kind,data=savedResume.data,total=kind==='quiz'?data.questions.length:data.queue.length;return `<section class="panel resume-panel"><div class="row" style="justify-content:space-between"><div><h2>Resume ${kind==='cards'?'practice':kind==='write'?'writing':'quiz'}</h2><p class="muted">Item ${data.pos+1} of ${total}</p></div><button class="btn primary" onclick="resumeSession()">Resume ${icon('arrow')}</button></div></section>`}
function clearSavedSession(){savedResume=null;undoAnswers=[];try{localStorage.removeItem(RESUME_KEY)}catch{}if(courseRuntimeReady&&state.courses?.records[selectedCourseId])state.courses.records[selectedCourseId].resume=null}
function renderSession(){
const s=session;if(!s)return navigate('learn');const c=s.queue[s.pos];setPracticeViewport(!!c);
if(!c){s.done=true;renderPracticeCompletion(s,'cards');checkpointSession('cards',s);return}
const hint=practiceHintMarkup(c,s),label=CHAPTERS.find(x=>x[0]===c.lesson)?.[1]||'Review';
$('view').innerHTML=`<div class="session-wrap focus-session"><div class="focus-top"><span class="small muted">${esc(label)} · ${s.pos+1} / ${s.queue.length}</span><div class="row">${undoAvailable()?'<button class="iconbtn" aria-label="Undo last answer (U)" title="Undo · U" onclick="undoLastAnswer()">'+icon('back')+'</button>':''}<button class="iconbtn" aria-label="Practice help" title="How to study and keyboard controls" onclick="showPracticeShortcuts()">${icon('help')}</button></div></div><div class="progress"><span style="width:${s.pos/s.queue.length*100}%"></span></div><section class="flashcard focus-card learning-card" aria-label="Character practice"><button class="iconbtn save-btn" aria-label="${state.bookmarks.includes(c.character)?'Remove bookmark':'Bookmark character'}" onclick="qolBookmarkPractice('${c.character}')">${star(c.character)}</button><div class="han" lang="zh">${han(c)}</div>${s.revealed?`<div class="focus-answer"><div class="row" style="justify-content:center"><span class="pinyin">${esc(c.pinyin)}</span><button class="btn focus-listen" onclick="speak('${c.character}')" aria-label="Listen to character (L)">${icon('sound')} Listen</button></div>${tonePill(c)}<p class="focus-meaning">${esc(c.meaning)}</p></div>${memoryTile(c)}<div class="practice-tools"><button class="btn" onclick="openPronunciation('${c.character}')">${icon('sound')} Sound guide</button><button class="btn" onclick="openPracticeDetails('${c.character}')">${icon('layers')} Usage &amp; parts</button></div>`:`<p class="focus-question">Read this character</p>${hint}<button class="textbtn focus-hint" onclick="flashHint()">${(s.hintLevel||0)>=3?'Hide hints':s.hint?'Next hint':'Hint'} <span class="keyboard-label">H</span></button>`}</section><div class="focus-actions">${s.revealed?`<div class="rate-row"><button class="btn danger" onclick="rate('again')">Again <kbd>1</kbd></button><button class="btn" onclick="rate('hard')">Almost <kbd>2</kbd></button><button class="btn primary" onclick="rate('good')">Got it <kbd>3</kbd></button></div>`:'<button class="btn primary full" onclick="reveal()">Show answer <span class="keyboard-label">Space / Enter</span></button>'}</div></div>`;
checkpointSession('cards',s);
}
function renderWritingSession(){const s=writeSession;if(!s)return renderWrite();const w=s.queue[s.pos];setPracticeViewport(!!w);if(!w){s.done=true;renderPracticeCompletion(s,'write');checkpointSession('write',s);return}const hint=s.hint?[...w.target].map(ch=>cardByChar[ch]||extra[ch]).filter(Boolean).map(c=>characterHints(c)[Math.max(0,Math.min(2,(s.hintLevel||1)-1))]).join(' '):'';$('view').innerHTML=`<div class="session-wrap focus-session focus-writing"><div class="focus-top"><span class="small muted">Writing · ${s.pos+1} / ${s.queue.length}</span><div class="row">${undoAvailable()?'<button class="iconbtn" onclick="undoLastAnswer()" aria-label="Undo last answer (U)">'+icon('back')+'</button>':''}<button class="iconbtn" aria-label="Practice help" title="How to study and keyboard controls" onclick="showPracticeShortcuts()">${icon('help')}</button></div></div><div class="progress"><span style="width:${s.pos/s.queue.length*100}%"></span></div><section class="focus-card writing-focus-card"><div class="writing-prompt">${s.prompt==='pinyin'?'<h1>'+esc(w.pinyin)+'</h1>':''}<p>${esc(w.meaning)}</p></div><div class="writing-methods focus-writing-methods">${['draw','type','paper'].map(tool=>`<button class="btn ${s.tool===tool?'soft':''}" aria-pressed="${s.tool===tool}" onclick="writingTool('${tool}')">${tool[0].toUpperCase()+tool.slice(1)}</button>`).join('')}</div>${hint?'<div class="focus-hint-box" role="status"><p>'+esc(hint)+'</p></div>':''}<div class="writing-response ${s.revealed?'writing-revealed':''}">${s.tool==='draw'?'<div class="focus-drawing"><canvas id="write-canvas" aria-label="Optional handwriting pad"></canvas><div class="row"><button class="textbtn" onclick="writeSession.strokes.pop();paintCanvas();checkpointCurrent()">Undo stroke</button><button class="textbtn" onclick="writeSession.strokes=[];paintCanvas();checkpointCurrent()">Clear</button></div></div>':s.tool==='type'?`<div class="focus-type"><input id="typed-answer" class="input" lang="zh" aria-label="Type your Chinese answer" autocomplete="off" value="${esc(s.typed)}" placeholder="Type Chinese characters" oninput="writeSession.typed=this.value;checkpointCurrent()" ${s.revealed?'readonly':''}><p class="small muted">Use your Chinese keyboard or IME.</p></div>`:'<div class="focus-paper muted">Write on paper, then reveal.</div>'}${s.revealed?`<div class="writing-model"><div class="han" lang="zh">${text(w.target)}</div><p class="small muted">${esc(w.pinyin)}</p><button class="btn" onclick="speak('${w.target}')">${icon('sound')} Listen</button>${s.tool==='type'&&s.typed?'<p class="small">'+(s.typed.trim()===text(w.target)?'Your answer matches.':'Compare your answer.')+'</p>':''}</div>`:''}</div>${s.revealed?[...new Set([...w.target])].filter(ch=>cardByChar[ch]).map(ch=>`<button class="textbtn" onclick="openPracticeDetails('${ch}','components')">${text(ch)} · Components</button>`).join(''):`<button class="textbtn focus-hint" onclick="writingHintToggle()">${(s.hintLevel||0)>=3?'Hide hints':s.hint?'Next hint':'Hint'} <span class="keyboard-label">H</span></button>`}</section><div class="focus-actions">${s.revealed?'<div class="rate-row" style="grid-template-columns:1fr 1fr"><button class="btn danger" onclick="rateWriting(false)">Try again <kbd>1</kbd></button><button class="btn primary" onclick="rateWriting(true)">Correct <kbd>3</kbd></button></div>':'<button class="btn primary full" onclick="revealWriting()">Reveal answer <span class="keyboard-label">Space / Enter</span></button>'}</div></div>`;if(s.tool==='draw')initCanvas();checkpointSession('write',s)}
function renderQuiz(){const s=quizSession,q=s?.questions[s.pos];setPracticeViewport(!!q);if(!q){renderQuizBeforeQoL();checkpointSession('quiz',s);return}const answered=q.choice!==null;$('view').innerHTML=`<div class="session-wrap focus-session focus-quiz"><div class="focus-top"><span class="small muted">${s.kind==='chapter'?lessonLabel(s.id):s.kind==='confusion'?'Similar shapes':'Review quiz'} · ${s.pos+1} / ${s.questions.length}</span><div class="row">${undoAvailable()?'<button class="iconbtn" onclick="undoLastAnswer()" aria-label="Undo last answer (U)">'+icon('back')+'</button>':''}<button class="iconbtn" aria-label="Practice help" title="How to study and keyboard controls" onclick="showPracticeShortcuts()">${icon('help')}</button></div></div><div class="progress"><span style="width:${s.pos/s.questions.length*100}%"></span></div><section class="focus-card focus-quiz-card"><h1 class="quiz-pinyin">${esc(q.card.pinyin)}</h1><p class="focus-meaning">${esc(q.card.meaning)}</p><div class="quiz-choices">${q.choices.map((c,i)=>`<button class="quiz-choice ${answered?(c.character===q.card.character?'correct':c.character===q.choice?'incorrect':''):''}" ${answered?'disabled':''} aria-label="Answer ${i+1}: ${esc(han(c))}" onclick="quizChoose('${c.character}')"><span lang="zh">${han(c)}</span><kbd>${i+1}</kbd>${answered&&c.character===q.card.character?icon('check'):''}${answered&&c.character===q.choice&&q.choice!==q.card.character?icon('close'):''}</button>`).join('')}</div>${answered?`<div class="quiz-feedback focus-quiz-feedback" role="status"><strong>${q.choice!==q.card.character?'Not quite':q.usedHint?'Correct with a hint':'Correct'}</strong><p>${han(q.card)} · ${esc(q.card.pinyin)} · ${esc(q.card.meaning)}</p><button class="textbtn" onclick="openPracticeDetails('${q.card.character}','components')">Usage &amp; components</button>${q.choice!==q.card.character?`<button class="textbtn" onclick="showQuizAnswerComparison('${q.card.character}','${q.choice}')">Compare my answer</button>`:''}${q.confusion!==undefined?`<button class="textbtn" onclick="showShapeComparison(${q.confusion})">Compare these shapes</button>`:''}</div>`:`${q.hint?'<div class="focus-hint-box" role="status"><p>'+esc(quizComponentHint(q.card.character))+'</p></div>':''}<button class="textbtn" onclick="quizHint()">${q.hint?'Hide hint':'Hint'} <span class="keyboard-label">H</span></button>`}</section><div class="focus-actions">${answered?`<button class="btn primary full" onclick="quizNext()">${s.pos===s.questions.length-1?'See results':'Next question'} ${icon('arrow')} <span class="keyboard-label">Enter</span></button>`:'<p class="small muted">Choose a character · <span class="keyboard-label">1–4</span></p>'}</div></div>`;checkpointSession('quiz',s)}
function learningPathStep(id){
 const index=courseChapters().findIndex(c=>c[0]===id),title=courseChapters()[index]?.[1]||'Foundations',p=progress(id),quizPassed=!!state.quizzes.chapters[id]?.passed,reading=READINGS.find(r=>r.lesson===id),readPassed=READINGS.some(r=>r.lesson===id&&state.read[r.id]);
 if(p.practiced<p.total)return {step:0,heading:'Continue '+title,label:'Learn next characters',action:`startSession('learn','${id}')`,description:`${p.practiced} of ${p.total} characters practiced. Finish the set, then check them in a quiz.`};
 if(!quizPassed)return {step:1,heading:title+' · Check your recall',label:'Start chapter quiz',action:`startQuiz('chapter','${id}')`,description:'All characters practiced. Score 80% without hints to pass. Review missed characters and retry as needed.'};
 if(reading&&!readPassed)return {step:2,heading:title+' · Read a passage',label:'Start reading',action:`openReading('${reading.id}')`,description:'Chapter quiz passed. Read with pinyin if needed, tap unfamiliar characters, and answer the passage questions.'};
 const next=courseChapters()[index+1];return {step:3,heading:next?'Next: '+next[1]:'Course review',label:next?'Open next chapter':'Review learned characters',action:next?`openChapter('${next[0]}')`:"startQuiz('review')",description:next?'Chapter practice and reading complete. Continue when you’re ready.':'Continue with due reviews, readings, and course challenges.'};
}
function learningPathMarkup(id){const path=learningPathStep(id),beginner=!state.quizzes.chapters['1']?.passed;return `<section class="learning-path" aria-label="Chapter learning path"><strong>${id==='I'?'Foundations':lessonLabel(id)} · Your path</strong><ol>${['Learn characters','Chapter quiz','Read a passage','Next chapter'].map((label,i)=>`<li class="${i===path.step?'active':''}" ${i===path.step?'aria-current="step"':''}><span>${i<path.step?'✓':i+1}</span>${label}</li>`).join('')}</ol>${beginner?'<details><summary>New here? How to study</summary><p><strong>Learn:</strong> Try reading the character before revealing. Pinyin gives its pronunciation; marks above vowels show tones. Listen to the audio to check the sound.</p><p><strong>Rate:</strong> 1 = Again, 2 = Almost, 3 = Got it. If you needed a hint or didn’t know it, review it again. Writing is optional.</p><p><strong>Read:</strong> Use the chapter passages to recognize characters in context. This app focuses on reading characters; a new speaker will also need spoken vocabulary and grammar instruction.</p></details>':''}</section>`}
function renderHome(){
const practiced=uniqueCards().filter(c=>state.cards[c.character]?.seen>0),known=uniqueCards().filter(familiar).length,today=state.activity[dayKey()]?.cards||0,goal=state.settings.goal,due=dueCards().length;
const ch=CHAPTERS.find(c=>c[0]===(practiced.length?state.lastChapter:'I'))||courseChapters()[0],p=progress(ch[0]),hour=new Date().getHours(),reading=practiced.length?readingRecommendations()[0]:{reading:READINGS.find(r=>r.lesson==='I')||READINGS[0]};
const focus=uniqueCards().filter(c=>state.quizMisses[c.character]||(state.cards[c.character]&&!familiar(c))).sort((a,b)=>(state.quizMisses[b.character]||0)-(state.quizMisses[a.character]||0)||(state.cards[b.character]?.last||0)-(state.cards[a.character]?.last||0)).slice(0,6);
const r=reading?.reading,fit=r?readingFit(r):null,resume=savedResume,kind=resume?.kind,resumeLabel=kind==='write'?'writing':kind==='quiz'?'quiz':'practice';
const path=learningPathStep(ch[0]),heading=resume?'Resume '+resumeLabel:!practiced.length?'Start with Foundations':path.heading;
const description=resume?`Item ${resume.data.pos+1} of ${kind==='quiz'?resume.data.questions.length:resume.data.queue.length}`:practiced.length?path.description:'Learn the shapes, reveal the answer, then mark how well you knew it.';
$('view').innerHTML=`<div class="heading"><div><h1>${hour<12?'Good morning':hour<18?'Good afternoon':'Good evening'}.</h1></div><span class="badge">${state.settings.script==='traditional'?'Traditional':'Simplified'}</span></div>
<section class="hero home-continue"><div><div class="eyebrow">${resume?'Where you left off':practiced.length?'Your next session':'Getting started'}</div><h2>${esc(heading)}</h2><p class="muted">${esc(description)}</p><div class="row"><button class="btn primary" onclick="${resume?'resumeSession()':path.action}">${resume?'Resume session':practiced.length?path.label:'Start learning'} ${icon('arrow')}</button><button class="textbtn" onclick="openChapter('${ch[0]}')">View chapter</button>${practiced.length?'<button class="textbtn" onclick="startDailyPractice()">Daily mix</button>':''}</div></div><div class="home-goal"><span class="small muted">Daily goal</span><strong>${today}<span> / ${goal}</span></strong><div class="progress" role="progressbar" aria-label="Daily review goal" aria-valuemin="0" aria-valuemax="${goal}" aria-valuenow="${Math.min(today,goal)}"><span style="width:${Math.min(today/goal*100,100)}%"></span></div><span class="small muted">${today>=goal?'Goal reached':`${goal-today} to your goal`}</span></div></section>
<div class="stats-grid home-stats"><div class="stat"><strong>${known}<span style="font-size:13px"> / 400</span></strong><span>Familiar characters</span><div class="progress" role="progressbar" aria-label="Familiar characters" aria-valuemin="0" aria-valuemax="400" aria-valuenow="${known}"><span style="width:${known/400*100}%"></span></div></div><div class="stat"><strong>${due}</strong><span>Due for review</span></div><div class="stat"><strong>${streak()}</strong><span>Day streak</span></div></div>
<div class="home-grid ${focus.length||state.bookmarks.length?'':'single'}">${focus.length||state.bookmarks.length?`<section class="panel"><div class="row home-panel-heading"><h2>${focus.length?'Needs practice':'Your saved characters'}</h2><button class="textbtn" onclick="navigate('${focus.length?'review':'search'}')">${focus.length?'Review':'Dictionary'} ${icon('arrow')}</button></div>${focus.length?`<div class="home-character-strip">${focus.map(c=>`<button class="home-character" aria-label="Look up ${esc(han(c))}" onclick="showCharacter('${c.character}')"><span lang="zh">${esc(han(c))}</span><small>${esc(c.pinyin)}</small></button>`).join('')}</div><button class="btn" onclick="startSession('all',null,'${focus.map(c=>c.character).join('')}'.split(''))">Practice these ${focus.length}</button>`:state.bookmarks.length?`<div class="home-character-strip">${state.bookmarks.slice(0,6).map(ch=>cardByChar[ch]).filter(Boolean).map(c=>`<button class="home-character" aria-label="Look up ${esc(han(c))}" onclick="showCharacter('${c.character}')"><span lang="zh">${esc(han(c))}</span><small>${esc(c.pinyin)}</small></button>`).join('')}</div><button class="btn" onclick="startSession('saved')">Practice saved characters</button>`:''}</section>`:''}
<section class="panel"><div class="row home-panel-heading"><h2>Suggested reading</h2><button class="textbtn" onclick="navigate('read')">Library ${icon('arrow')}</button></div>${r?`<span class="badge">${r.lesson==='I'?'Foundations':lessonLabel(r.lesson)}${state.read[r.id]?' · Completed':''}</span><h3 class="home-reading-title">${esc(r.title)}</h3><p class="muted small">${esc(r.subtitle)}</p><p class="small muted">${practiced.length?`${fit.percent}% of characters familiar · ${fit.unknown.length} unfamiliar characters`:'Read with pinyin and tap characters for help.'}</p><button class="btn" onclick="openReading('${r.id}')">${icon('read')} ${state.read[r.id]?'Read again':'Try a reading'}</button>`:''}</section></div>
<div class="home-footer"><button class="textbtn" onclick="navigate('learn')">All chapters ${icon('arrow')}</button><details class="quiet-details"><summary>Weekly activity</summary><div class="week">${weekMarkup()}</div></details></div>`;
}
function renderSettings(){const options=(key,choices)=>`<select aria-label="${key}" onchange="setSetting('${key}',${['goal','size'].includes(key)?'Number(this.value)':'this.value'})">${choices.map(([value,label])=>`<option value="${value}" ${state.settings[key]===value?'selected':''}>${label}</option>`).join('')}</select>`;const row=(label,control,note='')=>`<div class="setting-row"><div><strong>${label}</strong>${note?`<p>${note}</p>`:''}</div>${control}</div>`;$('view').innerHTML=`<div class="heading"><div><h1>Settings</h1></div></div><div class="settings-grid clean-settings"><section class="panel"><h2>Appearance</h2><div class="palette-section"><strong>Color palette</strong><div class="palette-options">${Object.entries(PALETTES).map(([id,p])=>`<button class="palette-choice ${state.settings.palette===id?'selected':''}" aria-pressed="${state.settings.palette===id}" onclick="setSetting('palette','${id}');renderSettings()"><span class="palette-dot" style="background:${p.brandPale};border-color:${p.brandDark}"></span><span>${p.name}</span></button>`).join('')}</div></div>${row('Theme',options('theme',[['system','System'],['light','Light'],['dark','Dark']]))}${row('Reading text size',options('size',[[23,'Small'],[27,'Medium'],[32,'Large']]))}</section><section class="panel"><h2>Study preferences</h2>${row('Characters',options('script',[['simplified','Simplified'],['traditional','Traditional']]))}${row('Daily goal',options('goal',[10,20,30,50].map(n=>[n,n+' reviews'])))}${row('Session size',sessionLengthControl())}${row('Default writing method',options('writingMethod',[['draw','Draw'],['type','Type'],['paper','Paper']]))}<details class="quiet-details"><summary>Explanation preferences</summary>${row('Compact explanations',`<input type="checkbox" aria-label="Compact explanations" ${state.settings.compactExplanations?'checked':''} onchange="setSetting('compactExplanations',this.checked)">`,'Expand a character for more detail.')}${row('Expand usage details by default',`<input type="checkbox" aria-label="Detailed examples" ${state.settings.detailedExamples?'checked':''} onchange="setSetting('detailedExamples',this.checked)">`)}</details></section></div><section class="panel"><h2>Saved data</h2><p class="muted small">Saved in this browser. Use a backup to transfer your progress to another device.</p><div class="row"><button class="btn" onclick="exportBackup()">${icon('download')} Export backup</button><button class="btn" onclick="$('backup-file').click()">Import backup</button></div>${storageOK?'':'<p class="small" role="alert">Automatic saving is unavailable. Export a backup before leaving.</p>'}<details class="quiet-details"><summary>Reset progress</summary><p class="small muted">Clear learning progress and bookmarks.</p><button class="btn danger" onclick="resetProgress()">Reset progress</button></details></section><details class="panel quiet-details"><summary>Help &amp; references</summary><button class="btn" onclick="showPracticeShortcuts()">Keyboard shortcuts</button><p class="small muted">Unfinished practice, writing, and quiz sessions resume in the same browser. Audio uses your device’s installed Chinese voice.</p><p class="small muted">Selected structural data from <a href="https://github.com/skishore/makemeahanzi" target="_blank" rel="noopener">Make Me a Hanzi</a>, derived from Unihan and CJKlib, under <a href="https://www.gnu.org/licenses/lgpl-3.0.html" target="_blank" rel="noopener">LGPL 3 or later</a>. The app selects structural fields and adds original explanations and visual notes. Uncertain stroke groups are labeled.</p><button class="btn" onclick="exportComponents()">Download component data</button></details>`;}
function renderWrite(){if(writeSession){renderWritingSession();return}$('view').innerHTML=`<div class="heading"><div><h1>Writing</h1><p class="muted">Write from the prompt, then check your answer.</p></div></div><section class="panel writing-setup"><div class="form-grid"><label>Chapter<select id="write-chapter">${courseChapters().map(c=>`<option value="${c[0]}" ${c[0]===chapter?'selected':''}>${c[1]}</option>`).join('')}</select></label><label>Practice<select id="write-kind"><option value="characters">Characters</option><option value="words">Useful words</option></select></label><label>Prompt<select id="write-prompt"><option value="pinyin">Pinyin & meaning</option><option value="meaning">Meaning only</option></select></label><label>Writing method<select aria-label="Writing method" onchange="setSetting('writingMethod',this.value)">${['draw','type','paper'].map(k=>`<option value="${k}" ${state.settings.writingMethod===k?'selected':''}>${k[0].toUpperCase()+k.slice(1)}</option>`).join('')}</select></label>${sessionLengthControl()}</div><button class="btn primary" onclick="startWriting($('write-chapter').value,$('write-kind').value,$('write-prompt').value)">Start writing ${icon('arrow')}</button><details class="quiet-details"><summary>How writing practice works</summary><p class="small muted"><strong>Draw:</strong> Use a finger, stylus, or mouse. Reveal and compare the model yourself.</p><p class="small muted"><strong>Type:</strong> Enter Chinese characters with a Chinese keyboard. Reveal checks your answer.</p><p class="small muted"><strong>Paper:</strong> Write off-screen, reveal, and mark your answer correct or incorrect.</p></details></section>`;}
function renderChapter(){const ch=CHAPTERS.find(c=>c[0]===chapter),p=progress(chapter),status=state.quizzes.chapters[chapter];$('view').innerHTML=`<button class="textbtn back" onclick="navigate('learn')">${icon('back')} All chapters</button><div class="heading"><div><div class="eyebrow">${chapter==='I'?'Foundations':lessonLabel(chapter)}</div><h1>${ch[1]}</h1><p class="muted">${p.practiced}/${p.total} practiced · ${p.known} familiar${status?.passed?' · Quiz passed':''}</p></div><button class="btn" onclick="openResults('${chapter}')">Results</button></div><div class="progress chapter-coverage" role="progressbar" aria-label="Chapter coverage" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${p.percent}"><span style="width:${p.percent}%"></span></div><div class="tabs">${[['cards','Characters'],['read','Reading'],['write','Writing'],['quiz','Quiz']].map(([key,label])=>`<button class="${tab===key?'active':''}" aria-pressed="${tab===key}" onclick="chapterTab('${key}')">${label}</button>`).join('')}</div>${tab==='cards'?`<section class="panel compact-launch"><div class="row launch-row"><button class="btn primary" onclick="startSession('learn','${chapter}')">Start practice ${icon('arrow')}</button>${sessionLengthControl()}</div><details class="quiet-details"><summary>More practice options</summary><div class="row"><button class="btn" onclick="startSession('all','${chapter}')">All ${p.total} characters</button><button class="btn" onclick="startSession('weak','${chapter}')">Needs practice</button></div></details></section><div class="word-grid">${CARDS.filter(c=>c.lesson===chapter).map(c=>`<button class="word-card" onclick="showCharacter('${c.character}')"><div class="char">${han(c)}</div><div class="sound">${esc(c.pinyin)}</div><small>${esc(c.meaning)}</small></button>`).join('')}</div>`:tab==='read'?storyCards(chapter):tab==='write'?`<section class="panel compact-launch"><h2>Write from memory</h2><p class="muted small">Reveal the character and compare your answer.</p><div class="row launch-row"><button class="btn primary" onclick="startWriting('${chapter}')">Start writing ${icon('arrow')}</button>${sessionLengthControl()}</div></section>`:`<section class="panel compact-launch"><h2>Chapter quiz</h2><p class="muted">${p.total} questions · 80% without hints to pass</p>${status?`<p class="small muted">Last score: ${status.score}% · ${status.passed?'Passed':'Needs practice'}</p>`:''}<button class="btn primary" onclick="startQuiz('chapter','${chapter}')">${status?'Retake quiz':'Start quiz'} ${icon('arrow')}</button></section>`}`;}
function renderReview(){const due=dueCards().length,studied=uniqueCards().filter(c=>state.cards[c.character]?.seen).length,known=uniqueCards().filter(familiar).length,weak=uniqueCards().filter(c=>state.cards[c.character]&&!familiar(c)).length;$('view').innerHTML=`<div class="heading"><div><h1>Review</h1></div></div><div class="practice-preferences">${sessionLengthControl()}</div><div class="review-modes"><section class="panel"><h2>Due now</h2><p class="muted">${due} characters due</p><button class="btn primary" ${due?'':'disabled'} onclick="startSession('review')">Review due cards</button></section><section class="panel"><h2>Prepare first</h2><p class="muted">Revisit studied characters, weakest first.</p><button class="btn" ${studied?'':'disabled'} onclick="startReviewPrep()">Study before a quiz</button></section><section class="panel"><h2>Quiz learned characters</h2><p class="muted">${known} familiar characters</p><button class="btn" ${known?'':'disabled'} onclick="startQuiz('review')">Start review quiz</button>${state.quizzes.review?'<p class="small muted">Last score: '+state.quizzes.review.score+'%</p>':''}</section></div><section class="panel review-extras"><details><summary>Saved &amp; difficult characters</summary><div class="row"><button class="btn" ${weak?'':'disabled'} onclick="startSession('weak')">Needs practice (${weak})</button><button class="btn" ${state.bookmarks.length?'':'disabled'} onclick="startSession('saved')">Saved (${state.bookmarks.length})</button></div></details><details><summary>Compare similar shapes</summary><p class="small muted">Study differences in components, stroke positions, and lengths before a shape quiz.</p><button class="btn" onclick="openConfusions()">Browse comparisons</button></details></section>`}
function componentMarkup(ch){if(!state.settings.compactExplanations)return componentMarkupBeforeQoL(ch);const c=cardByChar[ch]||extra[ch];if(!c)return '';const glyph=han(c),d=COMPONENT_DATA[glyph];if(!d)return componentMarkupBeforeQoL(ch);const tree=parseIDS(d.d),parts=tree?.children||[];return `<section class="components compact-components"><h3>${glyph} · Components</h3><p class="small"><strong>Indexing radical:</strong> <button class="textbtn component-glyph" onclick="openComponentCard('${d.r}')">${esc(d.r)}</button> ${esc(partName(d.r))}</p>${parts.length?`<p class="small"><strong>Shape:</strong> ${esc(IDS_LAYOUT[tree.op])} · ${parts.map(n=>esc(partGlyph(n))).join(' + ')}</p>`:''}${d.f?`<p class="small"><strong>Sound clue:</strong> ${esc(d.f)}${COMPONENT_DATA[d.f]?.p?.[0]?' ('+esc(COMPONENT_DATA[d.f].p[0])+')':''} → ${esc(c.pinyin)}</p>`:''}<p class="small"><strong>${glyph===c.character?'Memory cue':'Simplified memory cue'}:</strong> ${esc(c.cue)}</p><details class="full-explanation"><summary>Full explanation & memory help</summary>${componentMarkupBeforeQoL(ch)}</details></section>`}
window.addEventListener('pagehide',checkpointCurrent);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')checkpointCurrent()});

const EXAMPLE_CONTEXT={"八个":{"word":"八个","pinyin":"bā ge","meaning":"eight items","sentence":["这里有八个苹果。","Zhè lǐ yǒu bā ge píngguǒ.","There are eight apples here."],"note":"个 is a general counter: number + 个 + noun. 八个 tells you there are eight items."},"贝壳":{"word":"贝壳","pinyin":"bèi ké","meaning":"seashell","sentence":["我在海边找到一个贝壳。","Wǒ zài hǎi biān zhǎo dào yí ge bèi ké.","I found a seashell by the sea."],"note":"贝壳 names the shell itself. 贝 is also a component associated with shells and, historically, money."},"一寸":{"word":"一寸","pinyin":"yí cùn","meaning":"one cun (a unit of length)","note":"寸 is a unit of length. 一 gives the amount: one. Read 寸 alone as cùn; the whole example is yí cùn.","sentence":["这条线长一寸。","Zhè tiáo xiàn cháng yí cùn.","This line is one cun long."]},"大家":{"word":"大家","pinyin":"dà jiā","meaning":"everyone","sentence":["大家都来了。","Dà jiā dōu lái le.","Everyone has arrived."],"note":"大家 means everyone as a group; it does not mean a large house in this expression."},"小刀":{"word":"小刀","pinyin":"xiǎo dāo","meaning":"small knife","sentence":["这把小刀很小。","Zhè bǎ xiǎo dāo hěn xiǎo.","This small knife is very small."],"note":"小 describes the size of 刀. Knives are usually counted with 把."},"耳朵":{"word":"耳朵","pinyin":"ěrduo","meaning":"ear","sentence":["我的耳朵有点疼。","Wǒ de ěrduo yǒu diǎn téng.","My ear hurts a little."],"note":"耳朵 is the everyday word for an ear. 朵 usually has a neutral tone in this word."},"两个":{"word":"两个","pinyin":"liǎng ge","meaning":"two items","sentence":["我有两个哥哥。","Wǒ yǒu liǎng ge gēge.","I have two older brothers."],"note":"Use 两 rather than 二 before most counters. 两个 is two + the general counter 个."},"干戈":{"word":"干戈","pinyin":"gān gē","meaning":"weapons; warfare","note":"干 and 戈 are ancient weapons. 化干戈为玉帛 is an idiom about replacing conflict with peace.","sentence":["他们终于化干戈为玉帛。","Tāmen zhōngyú huà gān gē wéi yù bó.","They finally turned conflict into peace."]},"工作":{"word":"工作","pinyin":"gōng zuò","meaning":"work; a job","sentence":["我今天要工作。","Wǒ jīntiān yào gōng zuò.","I have to work today."],"note":"工作 can be an activity (to work) or a noun (a job). Here it is an action after 要."},"弓箭":{"word":"弓箭","pinyin":"gōng jiàn","meaning":"bow and arrow","sentence":["他会用弓箭。","Tā huì yòng gōng jiàn.","He knows how to use a bow and arrow."],"note":"弓 is a bow and 箭 is an arrow. Together, 弓箭 names the weapon."},"火山":{"word":"火山","pinyin":"huǒ shān","meaning":"volcano","sentence":["那是一座火山。","Nà shì yí zuò huǒ shān.","That is a volcano."],"note":"火 means fire and 山 means mountain. 座 is a counter used for mountains."},"金色":{"word":"金色","pinyin":"jīn sè","meaning":"golden; gold-colored","sentence":["这支笔是金色的。","Zhè zhī bǐ shì jīn sè de.","This pen is gold-colored."],"note":"色 names a color. 金色 describes a gold color, not necessarily an object made of gold."},"九个":{"word":"九个","pinyin":"jiǔ ge","meaning":"nine items","sentence":["这里有九个学生。","Zhè lǐ yǒu jiǔ ge xuésheng.","There are nine students here."],"note":"Place 九个 before the noun to say how many there are. 个 is a general counter."},"人口":{"word":"人口","pinyin":"rén kǒu","meaning":"population","sentence":["这个城市的人口很多。","Zhè ge chéng shì de rén kǒu hěn duō.","This city has a large population."],"note":"人口 refers to the number of people living in a place; it is a fixed word, not a literal person-mouth."},"力气":{"word":"力气","pinyin":"lìqi","meaning":"physical strength","sentence":["他很有力气。","Tā hěn yǒu lìqi.","He is very strong."],"note":"有力气 means to have physical strength. 气 has a neutral tone in 力气."},"六个":{"word":"六个","pinyin":"liù ge","meaning":"six items","sentence":["我买了六个苹果。","Wǒ mǎi le liù ge píngguǒ.","I bought six apples."],"note":"六个 expresses a quantity. The thing being counted follows it."},"马上":{"word":"马上","pinyin":"mǎ shàng","meaning":"right away","note":"This is a fixed expression meaning “right away.” Its meaning is not the literal “on a horse.”","sentence":["我马上来。","Wǒ mǎ shàng lái.","I’ll be right there."]},"门口":{"word":"门口","pinyin":"mén kǒu","meaning":"doorway; entrance","sentence":["我在门口等你。","Wǒ zài mén kǒu děng nǐ.","I’m waiting for you at the entrance."],"note":"门口 is the area at a doorway or entrance. 在门口 tells you where someone is."},"丝线":{"word":"丝线","pinyin":"sī xiàn","meaning":"silk thread","sentence":["这根丝线很细。","Zhè gēn sī xiàn hěn xì.","This silk thread is very thin."],"note":"丝 names silk; 线 names a thread or line. 根 counts long, thin things such as threads."},"木头":{"word":"木头","pinyin":"mùtou","meaning":"wood","sentence":["这张桌子是木头做的。","Zhè zhāng zhuōzi shì mùtou zuò de.","This table is made of wood."],"note":"木头 is the everyday noun for wood. 头 has a neutral tone here."},"目的":{"word":"目的","pinyin":"mùdì","meaning":"purpose; goal","sentence":["你的目的是什么？","Nǐ de mùdì shì shénme?","What is your goal?"],"note":"目的 means a purpose or goal. 的 is pronounced dì in this word, unlike the possessive particle de."},"女人":{"word":"女人","pinyin":"nǚ rén","meaning":"woman","sentence":["那个女人是我的老师。","Nà ge nǚ rén shì wǒ de lǎoshī.","That woman is my teacher."],"note":"女人 names an adult woman. In ordinary speech, identify someone politely by their name or role when possible."},"七个":{"word":"七个","pinyin":"qī ge","meaning":"seven items","sentence":["我们有七个问题。","Wǒmen yǒu qī ge wèntí.","We have seven questions."],"note":"七个 comes before the things being counted. Here those things are 问题, questions."},"日子":{"word":"日子","pinyin":"rìzi","meaning":"day; days","sentence":["今天是个好日子。","Jīntiān shì ge hǎo rìzi.","Today is a good day."],"note":"日子 can mean a day, a period of days, or life as it is lived. 子 has a neutral tone here."},"三个":{"word":"三个","pinyin":"sān ge","meaning":"three items","sentence":["桌上有三个杯子。","Zhuō shàng yǒu sān ge bēizi.","There are three cups on the table."],"note":"三个 gives the quantity; 杯子 names the cups. 个 is a general counter."},"食物":{"word":"食物","pinyin":"shí wù","meaning":"food","sentence":["这里的食物很好吃。","Zhè lǐ de shí wù hěn hǎo chī.","The food here is delicious."],"note":"食物 is a general noun for food. 好吃 describes food that tastes good."},"十个":{"word":"十个","pinyin":"shí ge","meaning":"ten items","sentence":["我们班有十个学生。","Wǒmen bān yǒu shí ge xuésheng.","Our class has ten students."],"note":"十个 expresses the number of students. 班 means a class or group."},"表示":{"word":"表示","pinyin":"biǎo shì","meaning":"express; indicate","sentence":["我想表示感谢。","Wǒ xiǎng biǎo shì gǎn xiè.","I want to express my thanks."],"note":"表示 is used to express a feeling, attitude, or meaning. Here it introduces 感谢, thanks."},"手机":{"word":"手机","pinyin":"shǒu jī","meaning":"mobile phone","sentence":["我的手机在这里。","Wǒ de shǒu jī zài zhè lǐ.","My phone is here."],"note":"手机 means a mobile phone. 手 suggests something held in the hand; 机 refers to a machine."},"水果":{"word":"水果","pinyin":"shuǐ guǒ","meaning":"fruit","sentence":["我喜欢吃水果。","Wǒ xǐhuan chī shuǐ guǒ.","I like eating fruit."],"note":"水果 is the general category of fruit. Eat fruit is 吃水果."},"四个":{"word":"四个","pinyin":"sì ge","meaning":"four items","sentence":["我有四个朋友。","Wǒ yǒu sì ge péngyou.","I have four friends."],"note":"四个 gives the quantity before 朋友. 个 is a general counter for people and things."},"田地":{"word":"田地","pinyin":"tián dì","meaning":"farmland","sentence":["这片田地很大。","Zhè piàn tián dì hěn dà.","This farmland is very large."],"note":"田地 refers to land used for farming. 片 counts an area or stretch of land."},"土地":{"word":"土地","pinyin":"tǔ dì","meaning":"land","sentence":["这里的土地很贵。","Zhè lǐ de tǔ dì hěn guì.","Land here is expensive."],"note":"土地 is a general word for land. 田地 is more specifically farmland."},"国 (outer frame)":{"word":"国","pinyin":"guó","meaning":"the outer enclosure in 国 (country)","note":"囗 is the outer enclosure in 国. 国 means country; 中国 names China.","sentence":["我是中国人。","Wǒ shì Zhōngguó rén.","I am Chinese."]},"五个":{"word":"五个","pinyin":"wǔ ge","meaning":"five items","sentence":["我买了五个苹果。","Wǒ mǎi le wǔ ge píngguǒ.","I bought five apples."],"note":"五个 means five items; place the noun after it to identify what those items are."},"夕阳":{"word":"夕阳","pinyin":"xī yáng","meaning":"setting sun","sentence":["今天的夕阳很美。","Jīntiān de xī yáng hěn měi.","Today’s setting sun is beautiful."],"note":"夕阳 refers to the sun near sunset, rather than the sun at any time of day."},"小孩":{"word":"小孩","pinyin":"xiǎo hái","meaning":"child","sentence":["那个小孩在看书。","Nà ge xiǎo hái zài kàn shū.","That child is reading a book."],"note":"小孩 is an everyday word for a child. 在 before an action can mark what is happening now."},"心情":{"word":"心情","pinyin":"xīn qíng","meaning":"mood","sentence":["我今天心情很好。","Wǒ jīntiān xīn qíng hěn hǎo.","I’m in a good mood today."],"note":"心情 means someone’s emotional state or mood. 心情好 means to be in a good mood."},"语言":{"word":"语言","pinyin":"yǔ yán","meaning":"language","sentence":["中文是一种语言。","Zhōngwén shì yì zhǒng yǔ yán.","Chinese is a language."],"note":"语言 is the general word for language. 种 counts types or kinds."},"幼 (left component)":{"word":"幼","pinyin":"yòu","meaning":"the left component in 幼 (young)","note":"幺 is the component on the left of 幼. 幼 means young; 幼儿园 is a kindergarten.","sentence":["幼儿园在学校旁边。","Yòu'éryuán zài xuéxiào páng biān.","The kindergarten is next to the school."]},"衣服":{"word":"衣服","pinyin":"yīfu","meaning":"clothes","sentence":["这件衣服很漂亮。","Zhè jiàn yīfu hěn piàoliang.","This item of clothing is beautiful."],"note":"衣服 means clothing. 件 counts individual items of clothing, and 服 is neutral-toned here."},"一个":{"word":"一个","pinyin":"yí ge","meaning":"one item","sentence":["我有一个问题。","Wǒ yǒu yí ge wèntí.","I have a question."],"note":"一个 is one + the general counter 个. Before 个, 一 is pronounced yí in normal connected speech."},"又来":{"word":"又来","pinyin":"yòu lái","meaning":"come again","sentence":["你怎么又来了？","Nǐ zěnme yòu lái le?","Why have you come again?"],"note":"又 marks an action happening again. It commonly describes something that has already repeated."},"下雨":{"word":"下雨","pinyin":"xià yǔ","meaning":"rain; be raining","sentence":["今天下雨了。","Jīntiān xià yǔ le.","It has started raining today."],"note":"下雨 means rain is falling. The 下 here is part of the weather expression, not a direction instruction."},"月亮":{"word":"月亮","pinyin":"yuèliang","meaning":"moon","sentence":["今晚的月亮很亮。","Jīn wǎn de yuèliang hěn liàng.","The moon is bright tonight."],"note":"月亮 is the everyday word for the moon. The second 亮 in this sentence means bright."},"谁 (right component)":{"word":"谁","pinyin":"shéi","meaning":"the right component in 谁 (who)","note":"隹 is the component on the right of 谁. 谁 asks who someone is; the example sentence asks for the identity of your teacher.","sentence":["谁是你的老师？","Shéi shì nǐ de lǎoshī?","Who is your teacher?"]},"孩子":{"word":"孩子","pinyin":"háizi","meaning":"child","sentence":["她有两个孩子。","Tā yǒu liǎng ge háizi.","She has two children."],"note":"孩子 is the everyday word for a child or someone’s children. 子 is neutral-toned here."},"走路":{"word":"走路","pinyin":"zǒu lù","meaning":"walk","sentence":["我走路去学校。","Wǒ zǒu lù qù xué xiào.","I walk to school."],"note":"走路 describes walking as a way of moving. Place it before 去 to say you go somewhere on foot."},"足球":{"word":"足球","pinyin":"zú qiú","meaning":"soccer; football","sentence":["他喜欢踢足球。","Tā xǐhuan tī zú qiú.","He likes playing soccer."],"note":"Use 踢, to kick, with 足球. 打球 is used for many ball sports played with the hands."},"北京":{"word":"北京","pinyin":"běi jīng","meaning":"Beijing","sentence":["我想去北京。","Wǒ xiǎng qù Běijīng.","I want to go to Beijing."],"note":"北京 is a place name. 北 means north and 京 is associated with a capital city."},"不是":{"word":"不是","pinyin":"bù shì","meaning":"is not; am not; are not","sentence":["他不是我的老师。","Tā bú shì wǒ de lǎoshī.","He is not my teacher."],"note":"Put 不 before 是 to say someone or something is not something."},"贵姓":{"word":"贵姓","pinyin":"guì xìng","meaning":"your surname (polite)","note":"A polite way to ask someone’s surname, usually in 您贵姓？","sentence":["请问，您贵姓？","Qǐng wèn, nín guì xìng?","May I ask your surname?"]},"中国":{"word":"中国","pinyin":"Zhōngguó","meaning":"China","sentence":["我住在中国。","Wǒ zhù zài Zhōngguó.","I live in China."],"note":"中国 is the country name. 国 means country; it appears in many country names."},"你好":{"word":"你好","pinyin":"nǐ hǎo","meaning":"hello","sentence":["你好，我叫李明。","Nǐ hǎo, wǒ jiào Lǐ Míng.","Hello, my name is Li Ming."],"note":"你好 is a greeting. For a more respectful greeting, use 您好."},"我叫":{"word":"我叫","pinyin":"wǒ jiào","meaning":"my name is…","note":"Use 我叫 followed by your name to introduce yourself. 叫 here means “be called.”","sentence":["我叫李明。","Wǒ jiào Lǐ Míng.","My name is Li Ming."]},"姐姐":{"word":"姐姐","pinyin":"jiějie","meaning":"older sister","sentence":["我姐姐是老师。","Wǒ jiějie shì lǎoshī.","My older sister is a teacher."],"note":"姐姐 specifically means an older sister. The second 姐 is neutral-toned in this word."},"老师":{"word":"老师","pinyin":"lǎoshī","meaning":"teacher","sentence":["我的老师姓王。","Wǒ de lǎoshī xìng Wáng.","My teacher’s surname is Wang."],"note":"老师 names a teacher. A surname followed by 老师 is a common respectful form of address."},"李老师":{"word":"李老师","pinyin":"lǐ lǎo shī","meaning":"Teacher Li","sentence":["李老师教中文。","Lǐ lǎoshī jiāo Zhōngwén.","Teacher Li teaches Chinese."],"note":"Place the family name before 老师 when addressing or referring to a teacher."},"好吗":{"word":"好吗","pinyin":"hǎo ma","meaning":"is that okay?","note":"吗 turns the phrase into a yes-or-no question.","sentence":["我们明天见，好吗？","Wǒmen míng tiān jiàn, hǎo ma?","Let’s meet tomorrow, okay?"]},"美国":{"word":"美国","pinyin":"měi guó","meaning":"United States","sentence":["他在美国学习。","Tā zài Měiguó xué xí.","He studies in the United States."],"note":"美国 is the Chinese name for the United States. Do not translate 美 literally when reading this country name."},"名字":{"word":"名字","pinyin":"míngzi","meaning":"name","sentence":["你的名字是什么？","Nǐ de míngzi shì shénme?","What is your name?"],"note":"名字 means a name. 子 has a neutral tone here."},"什么":{"word":"什么","pinyin":"shénme","meaning":"what","sentence":["你想喝什么？","Nǐ xiǎng hē shénme?","What would you like to drink?"],"note":"什么 asks what something is. It stays where the missing information belongs, rather than always moving to the start."},"你呢":{"word":"你呢","pinyin":"nǐ ne","meaning":"what about you?","note":"呢 returns the question to the other person: “What about you?”","sentence":["我很好，你呢？","Wǒ hěn hǎo, nǐ ne?","I’m fine. What about you?"]},"纽约":{"word":"纽约","pinyin":"niǔ yuē","meaning":"New York","sentence":["我朋友住在纽约。","Wǒ péngyou zhù zài Niǔyuē.","My friend lives in New York."],"note":"纽约 is the Chinese transliteration of New York; read it as a place name."},"朋友":{"word":"朋友","pinyin":"péngyou","meaning":"friend","sentence":["她是我的朋友。","Tā shì wǒ de péngyou.","She is my friend."],"note":"朋友 means friend. 友 has a neutral tone in common speech in this word."},"请问":{"word":"请问","pinyin":"qǐng wèn","meaning":"excuse me; may I ask…","note":"A polite way to start a question. Follow it with what you want to ask.","sentence":["请问，你叫什么名字？","Qǐng wèn, nǐ jiào shénme míngzi?","Excuse me, what is your name?"]},"中国人":{"word":"中国人","pinyin":"Zhōngguó rén","meaning":"Chinese person","note":"人 after a country name identifies a person from that country.","sentence":["她是中国人。","Tā shì Zhōngguó rén.","She is Chinese."]},"学生":{"word":"学生","pinyin":"xuésheng","meaning":"student","sentence":["我是学生。","Wǒ shì xuésheng.","I am a student."],"note":"学生 names a person who studies. In common speech, 生 may be neutral-toned in this word."},"我是":{"word":"我是","pinyin":"wǒ shì","meaning":"I am…","sentence":["我是你的朋友。","Wǒ shì nǐ de péngyou.","I am your friend."],"note":"我是 introduces your identity or role. Put the person, role, or category after 是."},"王老师":{"word":"王老师","pinyin":"wáng lǎo shī","meaning":"Teacher Wang","sentence":["王老师在教室里。","Wáng lǎoshī zài jiàoshì lǐ.","Teacher Wang is in the classroom."],"note":"王 is a family name here. Put the surname before the title 老师."},"先生":{"word":"先生","pinyin":"xiānsheng","meaning":"Mr.; gentleman","sentence":["王先生，您好！","Wáng xiānsheng, nín hǎo!","Hello, Mr. Wang!"],"note":"先生 follows a surname as a polite title. 生 has a neutral tone in this use."},"你姓什么":{"word":"你姓什么","pinyin":"nǐ xìng shénme","meaning":"what is your surname?","sentence":["你姓什么？","Nǐ xìng shénme?","What is your surname?"],"note":"姓 is a verb meaning to have a particular surname. This question asks for the family name, not the full name."},"我也是":{"word":"我也是","pinyin":"wǒ yě shì","meaning":"I am too","sentence":["她是学生，我也是。","Tā shì xuésheng, wǒ yě shì.","She is a student, and I am too."],"note":"也 means also. 我也是 repeats the earlier identity without naming it again."},"我爱你":{"word":"我爱你","pinyin":"wǒ ài nǐ","meaning":"I love you","sentence":["妈妈，我爱你。","Māma, wǒ ài nǐ.","Mom, I love you."],"note":"爱 takes the person or thing you love after it. 我 and 你 identify who loves whom."},"爸爸":{"word":"爸爸","pinyin":"bàba","meaning":"dad","sentence":["我爸爸在家。","Wǒ bàba zài jiā.","My dad is at home."],"note":"爸爸 is an everyday family word for dad. The second 爸 is neutral-toned."},"白色":{"word":"白色","pinyin":"bái sè","meaning":"white","sentence":["这件衣服是白色的。","Zhè jiàn yīfu shì bái sè de.","This item of clothing is white."],"note":"色 turns 白 into a color name. 是白色的 describes an object’s color."},"我的":{"word":"我的","pinyin":"wǒ de","meaning":"my; mine","note":"的 marks possession: 我 → I; 我的 → my or mine.","sentence":["这是我的书。","Zhè shì wǒ de shū.","This is my book."]},"弟弟":{"word":"弟弟","pinyin":"dìdi","meaning":"younger brother","sentence":["我弟弟喜欢音乐。","Wǒ dìdi xǐhuan yīnyuè.","My younger brother likes music."],"note":"弟弟 specifically means a younger brother. The second 弟 is neutral-toned."},"都是":{"word":"都是","pinyin":"dōu shì","meaning":"all are","sentence":["他们都是学生。","Tāmen dōu shì xuésheng.","They are all students."],"note":"都 includes every member of the group. Put it before 是 or another verb."},"儿子":{"word":"儿子","pinyin":"érzi","meaning":"son","sentence":["他儿子在学校。","Tā érzi zài xuéxiào.","His son is at school."],"note":"儿子 means someone’s son. 子 has a neutral tone in this word."},"高兴":{"word":"高兴","pinyin":"gāo xìng","meaning":"happy","sentence":["我今天很高兴。","Wǒ jīntiān hěn gāo xìng.","I’m happy today."],"note":"高兴 describes feeling happy or pleased. 很 can connect the subject with this adjective."},"哥哥":{"word":"哥哥","pinyin":"gēge","meaning":"older brother","sentence":["我哥哥会开车。","Wǒ gēge huì kāi chē.","My older brother can drive."],"note":"哥哥 specifically means an older brother. The second 哥 is neutral-toned."},"我和你":{"word":"我和你","pinyin":"wǒ hé nǐ","meaning":"you and I","sentence":["我和你一起去。","Wǒ hé nǐ yìqǐ qù.","You and I will go together."],"note":"和 connects the two people. 一起 then describes doing the action together."},"几个":{"word":"几个","pinyin":"jǐ ge","meaning":"how many items?; a few items","sentence":["你有几个问题？","Nǐ yǒu jǐ ge wèntí?","How many questions do you have?"],"note":"几个 can ask how many, usually when a relatively small number is expected. It can also mean a few in a statement."},"我家":{"word":"我家","pinyin":"wǒ jiā","meaning":"my home; my family","sentence":["我家在学校旁边。","Wǒ jiā zài xuéxiào páng biān.","My home is next to the school."],"note":"我家 can refer to your home or your household. Here the location makes the home meaning clear."},"律师":{"word":"律师","pinyin":"lǜ shī","meaning":"lawyer","sentence":["她是一位律师。","Tā shì yí wèi lǜ shī.","She is a lawyer."],"note":"律师 names a profession. 位 is a respectful counter for a person."},"妈妈":{"word":"妈妈","pinyin":"māma","meaning":"mom","sentence":["我妈妈喜欢喝茶。","Wǒ māma xǐhuan hē chá.","My mom likes drinking tea."],"note":"妈妈 is an everyday family word for mom. The second 妈 is neutral-toned."},"没有":{"word":"没有","pinyin":"méi yǒu","meaning":"do not have; there is no","sentence":["我没有电脑。","Wǒ méi yǒu diànnǎo.","I don’t have a computer."],"note":"没有 negates having or the existence of something. Use it rather than 不有."},"妹妹":{"word":"妹妹","pinyin":"mèimei","meaning":"younger sister","sentence":["我妹妹在看书。","Wǒ mèimei zài kàn shū.","My younger sister is reading a book."],"note":"妹妹 specifically means a younger sister. The second 妹 is neutral-toned."},"那个":{"word":"那个","pinyin":"nà ge","meaning":"that one","sentence":["那个学生是谁？","Nà ge xuésheng shì shéi?","Who is that student?"],"note":"那个 points to something farther away or already mentioned. Follow it with a noun to identify the thing."},"男孩":{"word":"男孩","pinyin":"nán hái","meaning":"boy","sentence":["那个男孩是我弟弟。","Nà ge nán hái shì wǒ dìdi.","That boy is my younger brother."],"note":"男孩 means a boy; 女孩 means a girl. 男 identifies the male child here."},"照片":{"word":"照片","pinyin":"zhàopiàn","meaning":"photo","sentence":["这是我家的照片。","Zhè shì wǒ jiā de zhàopiàn.","This is a photo of my family."],"note":"照片 means a photograph. Use 张 to count individual photos."},"是谁":{"word":"是谁","pinyin":"shì shéi","meaning":"who is it?","sentence":["那个人是谁？","Nà ge rén shì shéi?","Who is that person?"],"note":"谁 asks for a person’s identity. In 是谁, it fills the same position as the person’s name in an answer."},"她是":{"word":"她是","pinyin":"tā shì","meaning":"she is…","sentence":["她是我的姐姐。","Tā shì wǒ de jiějie.","She is my older sister."],"note":"她 is the written pronoun for she. It sounds the same as 他 and 它."},"他是":{"word":"他是","pinyin":"tā shì","meaning":"he is…","sentence":["他是我的哥哥。","Tā shì wǒ de gēge.","He is my older brother."],"note":"他 is the written pronoun for he. Its pronunciation is the same as 她 and 它."},"中文":{"word":"中文","pinyin":"zhōng wén","meaning":"Chinese (language)","sentence":["我在学中文。","Wǒ zài xué Zhōngwén.","I’m learning Chinese."],"note":"中文 refers to the Chinese language, including written Chinese. 学中文 means to learn it."},"医生":{"word":"医生","pinyin":"yīshēng","meaning":"doctor","sentence":["她是一位医生。","Tā shì yí wèi yīshēng.","She is a doctor."],"note":"医生 names a medical doctor. 位 is a respectful counter for the person."},"英文":{"word":"英文","pinyin":"yīng wén","meaning":"English (language)","sentence":["这本书是英文的。","Zhè běn shū shì Yīngwén de.","This book is in English."],"note":"英文 refers to English, especially in written-language contexts. 英语 is also a common word for English."},"这个":{"word":"这个","pinyin":"zhè ge","meaning":"this one","sentence":["这个问题很难。","Zhè ge wèntí hěn nán.","This question is difficult."],"note":"这个 points to this one or something near you. Put a noun after it to specify what you mean."},"做饭":{"word":"做饭","pinyin":"zuò fàn","meaning":"cook; prepare a meal","sentence":["我爸爸正在做饭。","Wǒ bàba zhèng zài zuò fàn.","My dad is cooking."],"note":"做饭 refers to preparing a meal, not only cooking rice. 正在 marks the action as in progress."},"三点半":{"word":"三点半","pinyin":"sān diǎn bàn","meaning":"half past three","note":"点 marks the hour; 半 adds half an hour. 三点半 is 3:30.","sentence":["现在是三点半。","Xiànzài shì sān diǎn bàn.","It is 3:30 now."]},"中国菜":{"word":"中国菜","pinyin":"Zhōngguó cài","meaning":"Chinese food","sentence":["我喜欢吃中国菜。","Wǒ xǐhuan chī Zhōngguó cài.","I like eating Chinese food."],"note":"菜 can mean dishes or cuisine, as well as vegetables. 中国菜 means Chinese cuisine."},"吃饭":{"word":"吃饭","pinyin":"chī fàn","meaning":"eat a meal","sentence":["我们一起吃饭吧。","Wǒmen yìqǐ chī fàn ba.","Let’s eat together."],"note":"吃饭 generally means to have a meal. 饭 does not restrict the meal to rice."},"三点":{"word":"三点","pinyin":"sān diǎn","meaning":"three o’clock","sentence":["我们三点见。","Wǒmen sān diǎn jiàn.","We’ll meet at three o’clock."],"note":"点 after a number marks an hour on the clock. Put the time before the verb."},"多少":{"word":"多少","pinyin":"duō shǎo","meaning":"how many; how much","sentence":["你有多少本书？","Nǐ yǒu duō shǎo běn shū?","How many books do you have?"],"note":"多少 asks for a quantity or amount. It does not require an expected small number."},"还有":{"word":"还有","pinyin":"hái yǒu","meaning":"also have; there is also","sentence":["我还有一个问题。","Wǒ hái yǒu yí ge wèntí.","I have one more question."],"note":"还 means also or still here. 还有 introduces something additional that remains."},"几号":{"word":"几号","pinyin":"jǐ hào","meaning":"what date?","sentence":["今天是几号？","Jīntiān shì jǐ hào?","What is today’s date?"],"note":"几号 asks for the day of the month. 号 follows the number in the answer."},"很好":{"word":"很好","pinyin":"hěn hǎo","meaning":"very good","sentence":["这本书很好。","Zhè běn shū hěn hǎo.","This book is good."],"note":"很好 describes something positively. 很 often links a subject with an adjective without heavily stressing very."},"喜欢":{"word":"喜欢","pinyin":"xǐhuan","meaning":"like","sentence":["我喜欢看书。","Wǒ xǐhuan kàn shū.","I like reading books."],"note":"喜欢 can take a noun or an activity after it. Here 看书 names the activity you enjoy."},"再见":{"word":"再见","pinyin":"zài jiàn","meaning":"goodbye","sentence":["老师，再见！","Lǎoshī, zài jiàn!","Goodbye, teacher!"],"note":"再见 is a farewell. Its literal parts suggest seeing someone again."},"今天":{"word":"今天","pinyin":"jīntiān","meaning":"today","sentence":["我今天有课。","Wǒ jīntiān yǒu kè.","I have class today."],"note":"今天 is a time word. It normally goes before the verb, either before or after the subject."},"可是":{"word":"可是","pinyin":"kě shì","meaning":"but; however","sentence":["我想去，可是我没时间。","Wǒ xiǎng qù, kě shì wǒ méi shíjiān.","I want to go, but I don’t have time."],"note":"可是 introduces a contrast or obstacle. It is similar to 但是 in this use."},"一刻":{"word":"一刻","pinyin":"yí kè","meaning":"a quarter of an hour","note":"刻 here is a quarter of an hour. 三点一刻 means 3:15.","sentence":["现在是三点一刻。","Xiànzài shì sān diǎn yí kè.","It is 3:15 now."]},"吃了":{"word":"吃了","pinyin":"chī le","meaning":"ate; have eaten","sentence":["我已经吃了。","Wǒ yǐjīng chī le.","I’ve already eaten."],"note":"了 here marks the action as completed. It does not make every verb a past-tense verb by itself."},"很忙":{"word":"很忙","pinyin":"hěn máng","meaning":"busy","note":"很 is often used before adjectives. 很忙 can simply mean “busy,” without strongly stressing “very.”","sentence":["我今天很忙。","Wǒ jīntiān hěn máng.","I’m busy today."]},"我们":{"word":"我们","pinyin":"wǒmen","meaning":"we; us","sentence":["我们一起学习。","Wǒmen yìqǐ xué xí.","We study together."],"note":"我们 means we or us. 们 marks the plural form of the pronoun."},"明天":{"word":"明天","pinyin":"míng tiān","meaning":"tomorrow","sentence":["我明天去学校。","Wǒ míng tiān qù xué xiào.","I’m going to school tomorrow."],"note":"明天 tells you when the action happens. Chinese verbs do not need a future-tense ending here."},"今年":{"word":"今年","pinyin":"jīn nián","meaning":"this year","sentence":["我今年十八岁。","Wǒ jīn nián shí bā suì.","I’m eighteen years old this year."],"note":"今年 refers to the current year. 年 is the unit year."},"星期":{"word":"星期","pinyin":"xīngqī","meaning":"week","sentence":["一个星期有七天。","Yí ge xīngqī yǒu qī tiān.","A week has seven days."],"note":"星期 means week. Add a number after it for a weekday, such as 星期一 for Monday."},"认识":{"word":"认识","pinyin":"rènshi","meaning":"know someone; recognize","sentence":["我认识王老师。","Wǒ rènshi Wáng lǎoshī.","I know Teacher Wang."],"note":"认识 often means knowing or being acquainted with a person. 知道 is more often used for knowing a fact."},"上午":{"word":"上午","pinyin":"shàng wǔ","meaning":"morning (before noon)","sentence":["我上午有课。","Wǒ shàng wǔ yǒu kè.","I have class in the morning."],"note":"上午 is the part of the day before noon. It goes before the action it times."},"有事":{"word":"有事","pinyin":"yǒu shì","meaning":"have something to do; be occupied","sentence":["我今天有事。","Wǒ jīntiān yǒu shì.","I have something to do today."],"note":"有事 says you have a matter to attend to or are occupied. It can explain why you are unavailable."},"几岁":{"word":"几岁","pinyin":"jǐ suì","meaning":"how old?","sentence":["你弟弟几岁？","Nǐ dìdi jǐ suì?","How old is your younger brother?"],"note":"几岁 asks age, especially for a child or a small expected age. 岁 comes after the number in an answer."},"太好了":{"word":"太好了","pinyin":"tài hǎo le","meaning":"that’s great!","sentence":["你能来，太好了！","Nǐ néng lái, tài hǎo le!","You can come—that’s great!"],"note":"太…了 expresses a strong degree or reaction. 太好了 is a common happy response."},"同学":{"word":"同学","pinyin":"tóng xué","meaning":"classmate","sentence":["他是我的同学。","Tā shì wǒ de tóng xué.","He is my classmate."],"note":"同学 names someone who studies in the same class or school. It can also address students collectively."},"晚上":{"word":"晚上","pinyin":"wǎnshang","meaning":"evening; night","sentence":["我晚上看书。","Wǒ wǎnshang kàn shū.","I read in the evening."],"note":"晚上 names the evening or nighttime. It normally appears before the verb."},"因为":{"word":"因为","pinyin":"yīn wèi","meaning":"because","sentence":["因为下雨，我们不出去。","Yīn wèi xià yǔ, wǒmen bù chūqù.","Because it’s raining, we aren’t going out."],"note":"因为 introduces a reason. The result can follow it, sometimes introduced by 所以."},"现在":{"word":"现在","pinyin":"xiànzài","meaning":"now","sentence":["我现在有空。","Wǒ xiànzài yǒu kòng.","I have free time now."],"note":"现在 marks the present time. Put it before the action or state you describe."},"谢谢":{"word":"谢谢","pinyin":"xièxie","meaning":"thank you","sentence":["谢谢你的帮忙。","Xièxie nǐ de bāng máng.","Thank you for your help."],"note":"谢谢 can stand alone or be followed by the person or help you are grateful for."},"怎么样":{"word":"怎么样","pinyin":"zěnmeyàng","meaning":"how is it?; how about it?","sentence":["你觉得这本书怎么样？","Nǐ juéde zhè běn shū zěnmeyàng?","What do you think of this book?"],"note":"怎么样 asks about quality, condition, or someone’s opinion. The context tells you which."},"在哪里":{"word":"在哪里","pinyin":"zài nǎ lǐ","meaning":"where is it?","sentence":["你的书在哪里？","Nǐ de shū zài nǎ lǐ?","Where is your book?"],"note":"在 asks about location with 哪里. An answer can use 在 followed by a place."},"怎么":{"word":"怎么","pinyin":"zěnme","meaning":"how","sentence":["这个字怎么读？","Zhè ge zì zěnme dú?","How do you read this character?"],"note":"怎么 before a verb asks how to do something. 读 here means to read or pronounce."},"别人":{"word":"别人","pinyin":"bié rén","meaning":"other people","sentence":["不要拿别人的书。","Bú yào ná bié rén de shū.","Don’t take someone else’s book."],"note":"别人 means other people or someone else. 别人的 marks something belonging to them."},"常常":{"word":"常常","pinyin":"cháng cháng","meaning":"often","sentence":["我常常去图书馆。","Wǒ cháng cháng qù túshūguǎn.","I often go to the library."],"note":"常常 tells how frequently an action happens. Place it before the verb."},"唱歌":{"word":"唱歌","pinyin":"chàng gē","meaning":"sing","sentence":["她喜欢唱歌。","Tā xǐhuan chàng gē.","She likes singing."],"note":"唱 is the action of singing and 歌 means song. Together they name the activity."},"不错":{"word":"不错","pinyin":"bù cuò","meaning":"pretty good","sentence":["这家店不错。","Zhè jiā diàn bù cuò.","This shop is pretty good."],"note":"不错 is a positive judgment: not bad, or pretty good. It is not a claim that something is literally error-free."},"打球":{"word":"打球","pinyin":"dǎ qiú","meaning":"play ball","sentence":["我们下午去打球。","Wǒmen xià wǔ qù dǎ qiú.","We’re going to play ball this afternoon."],"note":"打球 refers to many ball sports. For soccer, use 踢足球 rather than 打足球."},"说得好":{"word":"说得好","pinyin":"shuō de hǎo","meaning":"said it well; speak well","sentence":["你说得好。","Nǐ shuō de hǎo.","You said it well."],"note":"得 connects an action with how well it is done. 好 evaluates the speaking."},"电话":{"word":"电话","pinyin":"diàn huà","meaning":"telephone; phone call","sentence":["我给妈妈打电话。","Wǒ gěi māma dǎ diàn huà.","I’m calling my mom."],"note":"打电话 means to make a phone call. 给 marks the person you are calling here."},"对不对":{"word":"对不对","pinyin":"duì bu duì","meaning":"is that right?","sentence":["这样写对不对？","Zhè yàng xiě duì bu duì?","Is it right to write it this way?"],"note":"对不对 asks whether something is correct using a positive-negative question form."},"时候":{"word":"时候","pinyin":"shíhou","meaning":"time; when","sentence":["你什么时候回家？","Nǐ shénme shíhou huí jiā?","When are you going home?"],"note":"时候 means a time or occasion. 什么时候 asks when."},"很久":{"word":"很久","pinyin":"hěn jiǔ","meaning":"a long time","sentence":["我等了很久。","Wǒ děng le hěn jiǔ.","I waited a long time."],"note":"很久 describes a long duration. Put it after an action to say how long the action lasted."},"觉得":{"word":"觉得","pinyin":"juéde","meaning":"think; feel","note":"觉 is pronounced jué here. The whole word means “think” or “feel.”","sentence":["我觉得这本书很好。","Wǒ juéde zhè běn shū hěn hǎo.","I think this book is good."]},"看书":{"word":"看书","pinyin":"kàn shū","meaning":"read a book","sentence":["我晚上喜欢看书。","Wǒ wǎnshang xǐhuan kàn shū.","I like reading books in the evening."],"note":"看书 is the usual expression for reading a book. 看 has a reading sense here, not only looking."},"客人":{"word":"客人","pinyin":"kè rén","meaning":"guest","sentence":["今天家里有客人。","Jīntiān jiā lǐ yǒu kè rén.","We have guests at home today."],"note":"客人 means a guest or visitor. 有客人 says guests are present."},"周末":{"word":"周末","pinyin":"zhōu mò","meaning":"weekend","sentence":["我周末去看电影。","Wǒ zhōu mò qù kàn diànyǐng.","I’m going to see a movie this weekend."],"note":"周末 means weekend. It functions as a time expression before the action."},"去学校":{"word":"去学校","pinyin":"qù xué xiào","meaning":"go to school","sentence":["我每天去学校。","Wǒ měi tiān qù xué xiào.","I go to school every day."],"note":"去 marks movement toward a destination. 学校 is the destination after it."},"电视":{"word":"电视","pinyin":"diàn shì","meaning":"television","sentence":["他在看电视。","Tā zài kàn diàn shì.","He is watching television."],"note":"Use 看电视 for watching TV. 电视 can refer to television or a TV set, depending on context."},"睡觉":{"word":"睡觉","pinyin":"shuì jiào","meaning":"sleep","note":"觉 is pronounced jiào in 睡觉, meaning “sleep.”","sentence":["我想早点睡觉。","Wǒ xiǎng zǎo diǎn shuì jiào.","I want to go to sleep a little earlier."]},"意思":{"word":"意思","pinyin":"yìsi","meaning":"meaning","sentence":["这个词是什么意思？","Zhè ge cí shì shénme yìsi?","What does this word mean?"],"note":"意思 means meaning or an intention. In this question, it asks for a word’s meaning."},"算了":{"word":"算了","pinyin":"suàn le","meaning":"forget it; never mind","sentence":["太贵了，算了吧。","Tài guì le, suàn le ba.","It’s too expensive. Never mind."],"note":"算了 is a fixed way to drop an idea or stop pursuing something. 吧 can soften the response."},"所以":{"word":"所以","pinyin":"suǒ yǐ","meaning":"so; therefore","sentence":["下雨了，所以我不出去。","Xià yǔ le, suǒ yǐ wǒ bù chūqù.","It’s raining, so I’m not going out."],"note":"所以 introduces a result or conclusion. It often follows a reason given with 因为."},"跳舞":{"word":"跳舞","pinyin":"tiào wǔ","meaning":"dance","sentence":["她会跳舞。","Tā huì tiào wǔ.","She can dance."],"note":"跳舞 names dancing. 会 before it describes knowing how to do the activity."},"听音乐":{"word":"听音乐","pinyin":"tīng yīn yuè","meaning":"listen to music","sentence":["我喜欢听音乐。","Wǒ xǐhuan tīng yīn yuè.","I like listening to music."],"note":"听 is listening, and 音乐 is music. 乐 is pronounced yuè in this word."},"外国":{"word":"外国","pinyin":"wài guó","meaning":"foreign country","sentence":["他想去外国学习。","Tā xiǎng qù wài guó xué xí.","He wants to study abroad."],"note":"外国 refers to foreign countries. It is a general category rather than a particular country name."},"我想":{"word":"我想","pinyin":"wǒ xiǎng","meaning":"I want to…; I think…","note":"想 before an action means “want to.” Before a statement, it can mean “think.” 我想 is the start of a sentence, so add what you want to do or what you think.","sentence":["我想喝茶。","Wǒ xiǎng hē chá.","I want to drink tea."]},"音乐":{"word":"音乐","pinyin":"yīnyuè","meaning":"music","sentence":["我很喜欢这段音乐。","Wǒ hěn xǐhuan zhè duàn yīnyuè.","I really like this piece of music."],"note":"音乐 means music. 乐 is pronounced yuè here, rather than lè as in 快乐."},"电影":{"word":"电影","pinyin":"diànyǐng","meaning":"movie","sentence":["我们去看电影吧。","Wǒmen qù kàn diànyǐng ba.","Let’s go see a movie."],"note":"看电影 means watch a movie. 部 is a common counter for films."},"找人":{"word":"找人","pinyin":"zhǎo rén","meaning":"look for someone","sentence":["他来这里找人。","Tā lái zhè lǐ zhǎo rén.","He came here to look for someone."],"note":"找 is to look for or seek. 人 is the person being sought."},"只有":{"word":"只有","pinyin":"zhǐ yǒu","meaning":"only have; only","sentence":["我只有一个问题。","Wǒ zhǐ yǒu yí ge wèntí.","I have only one question."],"note":"只有 limits what is present or available. Here it says there is just one question."},"昨天":{"word":"昨天","pinyin":"zuó tiān","meaning":"yesterday","sentence":["我昨天去了学校。","Wǒ zuó tiān qù le xuéxiào.","I went to school yesterday."],"note":"昨天 locates the action in the previous day. The time word makes the past time clear."},"走吧":{"word":"走吧","pinyin":"zǒu ba","meaning":"let’s go","sentence":["我们走吧。","Wǒmen zǒu ba.","Let’s go."],"note":"吧 at the end makes this a suggestion. 走 here means leave or get going."},"一杯水":{"word":"一杯水","pinyin":"yì bēi shuǐ","meaning":"a glass of water","sentence":["请给我一杯水。","Qǐng gěi wǒ yì bēi shuǐ.","Please give me a glass of water."],"note":"杯 acts as a container counter. 一杯水 is one cup or glass of water."},"才来":{"word":"才来","pinyin":"cái lái","meaning":"only just arrived","sentence":["你怎么现在才来？","Nǐ zěnme xiànzài cái lái?","Why are you only arriving now?"],"note":"才 before 来 can emphasize arriving later than expected. Here 现在 makes that timing clear."},"喝茶":{"word":"喝茶","pinyin":"hē chá","meaning":"drink tea","sentence":["我喜欢喝茶。","Wǒ xǐhuan hē chá.","I like drinking tea."],"note":"喝 names drinking and 茶 names tea. The drink follows the verb."},"咖啡":{"word":"咖啡","pinyin":"kāfēi","meaning":"coffee","sentence":["你想喝咖啡吗？","Nǐ xiǎng hē kāfēi ma?","Would you like to drink coffee?"],"note":"咖啡 is a borrowed word for coffee. Read the two characters together as the name of the drink."},"给你":{"word":"给你","pinyin":"gěi nǐ","meaning":"give to you; for you","sentence":["这本书给你。","Zhè běn shū gěi nǐ.","This book is for you."],"note":"给 marks giving or something intended for a person. 你 is the recipient here."},"图书馆":{"word":"图书馆","pinyin":"túshūguǎn","meaning":"library","sentence":["我在图书馆看书。","Wǒ zài túshūguǎn kàn shū.","I read at the library."],"note":"图书馆 is a library. 在 introduces the location before the action 看书."},"喝水":{"word":"喝水","pinyin":"hē shuǐ","meaning":"drink water","sentence":["我想喝水。","Wǒ xiǎng hē shuǐ.","I want to drink water."],"note":"喝水 is drinking water. Water, 水, is the object after 喝."},"回家":{"word":"回家","pinyin":"huí jiā","meaning":"go home","sentence":["我现在回家。","Wǒ xiànzài huí jiā.","I’m going home now."],"note":"回 means return. 回家 is going back home; unlike many destinations, 家 normally follows 回 directly without 到."},"介绍":{"word":"介绍","pinyin":"jièshào","meaning":"introduce","sentence":["我介绍一下我的朋友。","Wǒ jièshào yíxià wǒ de péngyou.","Let me introduce my friend."],"note":"介绍 can mean to introduce a person or present information. 一下 makes the proposed action sound brief."},"进来":{"word":"进来","pinyin":"jìn lái","meaning":"come in","sentence":["请进来坐。","Qǐng jìn lái zuò.","Please come in and sit down."],"note":"进 means enter and 来 means toward the speaker. 进来 invites someone inside where you are."},"很快":{"word":"很快","pinyin":"hěn kuài","meaning":"very fast; soon","sentence":["他走得很快。","Tā zǒu de hěn kuài.","He walks very fast."],"note":"很快 can describe speed or something happening soon. Here it describes the speed of walking."},"来这里":{"word":"来这里","pinyin":"lái zhè lǐ","meaning":"come here","sentence":["请来这里坐。","Qǐng lái zhè lǐ zuò.","Please come sit here."],"note":"来 is movement toward the speaker or reference point. 这里 gives the destination, here."},"漂亮":{"word":"漂亮","pinyin":"piàoliang","meaning":"beautiful; pretty","sentence":["这件衣服很漂亮。","Zhè jiàn yīfu hěn piàoliang.","This item of clothing is beautiful."],"note":"漂亮 describes an attractive appearance. 亮 is neutral-toned in this word."},"聊天":{"word":"聊天","pinyin":"liáo tiān","meaning":"chat","sentence":["我们一起聊天。","Wǒmen yìqǐ liáo tiān.","We chat together."],"note":"聊天 is an informal conversation. It is different from formally giving a speech."},"哪里":{"word":"哪里","pinyin":"nǎ lǐ","meaning":"where","sentence":["你住在哪里？","Nǐ zhù zài nǎ lǐ?","Where do you live?"],"note":"哪里 asks for a place. In a location question, it can follow 在."},"一瓶水":{"word":"一瓶水","pinyin":"yì píng shuǐ","meaning":"a bottle of water","sentence":["我买了一瓶水。","Wǒ mǎi le yì píng shuǐ.","I bought a bottle of water."],"note":"瓶 acts as a container counter: number + 瓶 + drink or other contents."},"一起":{"word":"一起","pinyin":"yìqǐ","meaning":"together","sentence":["我们一起去学校。","Wǒmen yìqǐ qù xué xiào.","We go to school together."],"note":"一起 marks people doing the same action together. Place it before the verb."},"好玩":{"word":"好玩","pinyin":"hǎowán","meaning":"fun","sentence":["这个游戏很好玩。","Zhè ge yóuxì hěn hǎo wán.","This game is fun."],"note":"好玩 describes something entertaining or enjoyable. 玩 is pronounced wán, not a neutral syllable."},"下午":{"word":"下午","pinyin":"xià wǔ","meaning":"afternoon","sentence":["我下午有课。","Wǒ xià wǔ yǒu kè.","I have class in the afternoon."],"note":"下午 names the period after noon. It normally appears before the action."},"学校":{"word":"学校","pinyin":"xuéxiào","meaning":"school","sentence":["我的学校很大。","Wǒ de xuéxiào hěn dà.","My school is large."],"note":"学校 names a school. 校 is also found in other words about school or campus."},"好呀":{"word":"好呀","pinyin":"hǎo ya","meaning":"sure!; okay!","sentence":["一起喝茶？好呀！","Yìqǐ hē chá? hǎo ya!","Shall we have tea together? Sure!"],"note":"呀 can make a response sound friendly and lively. 好呀 agrees to the suggestion."},"我要":{"word":"我要","pinyin":"wǒ yào","meaning":"I want…; I’m going to…","sentence":["我要一杯水。","Wǒ yào yì bēi shuǐ.","I would like a glass of water."],"note":"我要 can introduce something you want or intend to do. Here it requests an item."},"请坐":{"word":"请坐","pinyin":"qǐng zuò","meaning":"please sit down","sentence":["请坐，我们聊一会儿。","Qǐng zuò, wǒmen liáo yíhuìr.","Please sit down. Let’s chat for a while."],"note":"请 makes the invitation polite. 坐 is the action of sitting."},"好啊":{"word":"好啊","pinyin":"hǎo a","meaning":"sure!; okay!","sentence":["一起去？好啊！","Yìqǐ qù? hǎo a!","Shall we go together? Sure!"],"note":"啊 adds a conversational tone. 好啊 is an informal way to agree."},"办公室":{"word":"办公室","pinyin":"bàngōngshì","meaning":"office","sentence":["老师在办公室。","Lǎoshī zài bàngōngshì.","The teacher is in the office."],"note":"办公室 is a room or workplace for office work. 在 describes someone’s location there."},"帮忙":{"word":"帮忙","pinyin":"bāng máng","meaning":"help","sentence":["谢谢你来帮忙。","Xièxie nǐ lái bāng máng.","Thank you for coming to help."],"note":"帮忙 means lend a hand or help with something. It can be used without naming a direct object."},"准备":{"word":"准备","pinyin":"zhǔnbèi","meaning":"prepare","sentence":["我在准备考试。","Wǒ zài zhǔnbèi kǎoshì.","I’m preparing for an exam."],"note":"准备 can take the event or activity you are preparing for after it. Here that is 考试."},"方便":{"word":"方便","pinyin":"fāng biàn","meaning":"convenient","sentence":["现在说话方便吗？","Xiànzài shuō huà fāng biàn ma?","Is now a convenient time to talk?"],"note":"方便 asks whether the situation is convenient or suitable. It can politely check someone’s availability."},"但是":{"word":"但是","pinyin":"dàn shì","meaning":"but; however","sentence":["我想去，但是我很忙。","Wǒ xiǎng qù, dàn shì wǒ hěn máng.","I want to go, but I’m busy."],"note":"但是 introduces a contrast between two statements. Here it explains why the plan is difficult."},"到家":{"word":"到家","pinyin":"dào jiā","meaning":"arrive home","sentence":["我已经到家了。","Wǒ yǐjīng dào jiā le.","I’ve arrived home."],"note":"到 emphasizes reaching the destination. 回家 is going home; 到家 is arriving there."},"等一下":{"word":"等一下","pinyin":"děng yíxià","meaning":"wait a moment","sentence":["请等一下。","Qǐng děng yíxià.","Please wait a moment."],"note":"一下 softens the request and suggests a short duration. 等 is wait."},"跟我":{"word":"跟我","pinyin":"gēn wǒ","meaning":"with me; follow me","sentence":["请跟我来。","Qǐng gēn wǒ lái.","Please follow me."],"note":"跟 can mean follow or with. 跟我来 asks someone to come along with the speaker."},"公司":{"word":"公司","pinyin":"gōng sī","meaning":"company","sentence":["他在公司工作。","Tā zài gōng sī gōng zuò.","He works at a company."],"note":"公司 names a company or business. 在公司 gives the workplace."},"以后":{"word":"以后","pinyin":"yǐ hòu","meaning":"after; later","sentence":["我们以后再见。","Wǒmen yǐ hòu zài jiàn.","We’ll see each other again later."],"note":"以后 refers to a later time or something after a reference point. Here it means in the future."},"开会":{"word":"开会","pinyin":"kāi huì","meaning":"have a meeting","sentence":["我们下午开会。","Wǒmen xià wǔ kāi huì.","We have a meeting this afternoon."],"note":"开会 is the fixed expression for holding or attending a meeting. 会 is a meeting here."},"年级":{"word":"年级","pinyin":"nián jí","meaning":"grade (school year)","sentence":["你上几年级？","Nǐ shàng jǐ nián jí?","What grade are you in?"],"note":"年级 refers to a school grade or year level. 几年级 asks which one."},"时间":{"word":"时间","pinyin":"shíjiān","meaning":"time","sentence":["你有时间吗？","Nǐ yǒu shíjiān ma?","Do you have time?"],"note":"时间 means time as a resource or a point in time. 有时间 asks whether someone is available."},"一节课":{"word":"一节课","pinyin":"yì jié kè","meaning":"one class; one lesson","sentence":["今天我只有一节课。","Jīntiān wǒ zhǐ yǒu yì jié kè.","I have only one class today."],"note":"节 counts class periods. 一节课 is one lesson or one period of class."},"就是":{"word":"就是","pinyin":"jiù shì","meaning":"precisely; that is","sentence":["这就是我的学校。","Zhè jiù shì wǒ de xuéxiào.","This is my school."],"note":"就是 can emphasize identification: this is exactly the thing being referred to."},"考试":{"word":"考试","pinyin":"kǎoshì","meaning":"exam; take an exam","sentence":["我明天有考试。","Wǒ míng tiān yǒu kǎoshì.","I have an exam tomorrow."],"note":"考试 can be an exam or the activity of taking one. 有考试 treats it as an event."},"上课":{"word":"上课","pinyin":"shàng kè","meaning":"attend class; teach class","sentence":["我们九点上课。","Wǒmen jiǔ diǎn shàng kè.","We start class at nine o’clock."],"note":"上课 means to attend, conduct, or be in class. Context identifies whether the person is a teacher or student."},"有空":{"word":"有空","pinyin":"yǒu kòng","meaning":"have free time","note":"空 is pronounced kòng here and refers to available time.","sentence":["你明天有空吗？","Nǐ míng tiān yǒu kòng ma?","Are you free tomorrow?"]},"练习":{"word":"练习","pinyin":"liànxí","meaning":"practice","sentence":["我每天练习写字。","Wǒ měi tiān liànxí xiě zì.","I practice writing characters every day."],"note":"练习 can be a verb or a noun. Here it is followed by the activity being practiced."},"见面":{"word":"见面","pinyin":"jiàn miàn","meaning":"meet","sentence":["我们明天见面。","Wǒmen míng tiān jiàn miàn.","We’ll meet tomorrow."],"note":"见面 refers to people meeting in person. A time expression can come before it."},"您好":{"word":"您好","pinyin":"nín hǎo","meaning":"hello (polite)","sentence":["老师，您好！","Lǎoshī, nín hǎo!","Hello, teacher!"],"note":"您 is the respectful version of 你. 您好 is a polite greeting."},"客气":{"word":"客气","pinyin":"kèqi","meaning":"polite; courteous","sentence":["不用客气。","Bú yòng kèqi.","You’re welcome; don’t mention it."],"note":"不用客气 tells someone they do not need to be formal or thank you so much. It is a common response to thanks."},"教室":{"word":"教室","pinyin":"jiàoshì","meaning":"classroom","sentence":["学生都在教室里。","Xuésheng dōu zài jiàoshì lǐ.","The students are all in the classroom."],"note":"教室 is the room where lessons take place. 室 means a room."},"说话":{"word":"说话","pinyin":"shuō huà","meaning":"speak; talk","sentence":["请慢一点说话。","Qǐng màn yì diǎn shuō huà.","Please speak a little more slowly."],"note":"说话 names speaking or talking. 慢一点 asks for a slower pace."},"问题":{"word":"问题","pinyin":"wèntí","meaning":"question; problem","sentence":["我有一个问题。","Wǒ yǒu yí ge wèntí.","I have a question."],"note":"问题 can be a question or a problem. Here it introduces something the speaker wants to ask."},"喂，你好":{"word":"喂，你好","pinyin":"wèi, nǐ hǎo","meaning":"hello? Hello (answering the phone)","sentence":["喂，你好，请问你找谁？","Wèi, nǐ hǎo, qǐng wèn nǐ zhǎo shéi?","Hello, who would you like to speak to?"],"note":"喂 is commonly used to answer the telephone. It is pronounced wèi in this greeting."},"一位老师":{"word":"一位老师","pinyin":"yí wèi lǎoshī","meaning":"one teacher","note":"位 is a respectful counter for people; 老师 means teacher.","sentence":["她是一位老师。","Tā shì yí wèi lǎoshī.","She is a teacher."]},"中午":{"word":"中午","pinyin":"zhōng wǔ","meaning":"noon","sentence":["我们中午吃饭。","Wǒmen zhōng wǔ chī fàn.","We eat at noon."],"note":"中午 names noon or the middle of the day. It goes before the activity."},"学习":{"word":"学习","pinyin":"xué xí","meaning":"study; learn","sentence":["我每天学习中文。","Wǒ měi tiān xué xí Zhōngwén.","I study Chinese every day."],"note":"学习 means study or learn. It can take the subject being studied after it."},"行不行":{"word":"行不行","pinyin":"xíng bu xíng","meaning":"is that okay?; will it work?","note":"Repeating the positive and negative forms asks “Is it okay?”","sentence":["我们明天去，行不行？","Wǒmen míng tiān qù, xíng bu xíng?","Can we go tomorrow? Would that work?"]},"一支笔":{"word":"一支笔","pinyin":"yì zhī bǐ","meaning":"one pen","sentence":["我需要一支笔。","Wǒ xūyào yì zhī bǐ.","I need a pen."],"note":"支 is a counter for long, narrow objects such as pens. 一支笔 is one pen."},"生词":{"word":"生词","pinyin":"shēngcí","meaning":"new vocabulary","sentence":["这个生词很难。","Zhè ge shēngcí hěn nán.","This new vocabulary word is difficult."],"note":"生词 is vocabulary that is new or unfamiliar to the learner. 生 has the unfamiliar sense here."},"第一":{"word":"第一","pinyin":"dì yī","meaning":"first","sentence":["今天是我上课的第一天。","Jīntiān shì wǒ shàng kè de dì yī tiān.","Today is my first day of class."],"note":"第 before a number makes an ordinal: 第一 means first, rather than one."},"听懂":{"word":"听懂","pinyin":"tīng dǒng","meaning":"understand what you hear","note":"听 means “listen”; 懂 means “understand.” Together they mean successfully understanding what you hear.","sentence":["我听懂了。","Wǒ tīng dǒng le.","I understood what I heard."]},"语法":{"word":"语法","pinyin":"yǔfǎ","meaning":"grammar","sentence":["中文语法很有意思。","Zhōngwén yǔfǎ hěn yǒu yìsi.","Chinese grammar is interesting."],"note":"语法 names the rules and patterns of a language. 法 has the rules or method sense here."},"复习":{"word":"复习","pinyin":"fùxí","meaning":"review","sentence":["我晚上复习生词。","Wǒ wǎnshang fùxí shēngcí.","I review new vocabulary in the evening."],"note":"复习 is studying material again after learning it. Contrast 预习, preparing before a lesson."},"功课":{"word":"功课","pinyin":"gōng kè","meaning":"schoolwork","sentence":["我做完功课了。","Wǒ zuò wán gōng kè le.","I’ve finished my schoolwork."],"note":"功课 refers to assigned schoolwork or lessons. 做功课 means do that work."},"汉字":{"word":"汉字","pinyin":"Hànzì","meaning":"Chinese characters","sentence":["这个汉字怎么读？","Zhè ge Hànzì zěnme dú?","How do you read this Chinese character?"],"note":"汉字 names Chinese written characters. A single character is a 字, not necessarily a whole word."},"教中文":{"word":"教中文","pinyin":"jiāo Zhōngwén","meaning":"teach Chinese","note":"教 means “teach” here and is pronounced jiāo. 中文 means Chinese.","sentence":["她教中文。","Tā jiāo Zhōngwén.","She teaches Chinese."]},"很酷":{"word":"很酷","pinyin":"hěn kù","meaning":"very cool","sentence":["这辆车很酷。","Zhè liàng chē hěn kù.","This car is very cool."],"note":"酷 is an informal adjective for cool or stylish. It does not mean low temperature here."},"这里":{"word":"这里","pinyin":"zhè lǐ","meaning":"here","sentence":["请坐在这里。","Qǐng zuò zài zhè lǐ.","Please sit here."],"note":"这里 refers to this place, usually near the speaker. 那里 refers to that place."},"录音":{"word":"录音","pinyin":"lù yīn","meaning":"record sound; audio recording","sentence":["我想听这段录音。","Wǒ xiǎng tīng zhè duàn lù yīn.","I want to listen to this recording."],"note":"录音 can be an audio recording or the action of recording sound. Here it is the recording you listen to."},"很慢":{"word":"很慢","pinyin":"hěn màn","meaning":"very slow","sentence":["他写字很慢。","Tā xiě zì hěn màn.","He writes characters very slowly."],"note":"很慢 describes a slow pace. Here it describes the speed of writing."},"很难":{"word":"很难","pinyin":"hěn nán","meaning":"very difficult","sentence":["这个字很难写。","Zhè ge zì hěn nán xiě.","This character is difficult to write."],"note":"难 before a verb describes difficulty doing that action. 很难写 means very hard to write."},"念书":{"word":"念书","pinyin":"niàn shū","meaning":"study; attend school","sentence":["他在北京念书。","Tā zài Běijīng niàn shū.","He attends school in Beijing."],"note":"念书 can mean study or attend school. It is not limited to reading a book aloud."},"水平":{"word":"水平","pinyin":"shuǐ píng","meaning":"level of skill","sentence":["他的中文水平很好。","Tā de Zhōngwén shuǐ píng hěn hǎo.","His Chinese proficiency is good."],"note":"水平 here means a level of skill or ability, rather than a literal horizontal surface."},"容易":{"word":"容易","pinyin":"róngyì","meaning":"easy","sentence":["这个字很容易写。","Zhè ge zì hěn róngyì xiě.","This character is easy to write."],"note":"容易 before an action describes how easy it is. 很容易写 is easy to write."},"开始":{"word":"开始","pinyin":"kāi shǐ","meaning":"start; begin","sentence":["我们现在开始吧。","Wǒmen xiànzài kāi shǐ ba.","Let’s begin now."],"note":"开始 means begin or start. It can stand alone or introduce the action that begins."},"很帅":{"word":"很帅","pinyin":"hěn shuài","meaning":"very handsome","sentence":["他今天很帅。","Tā jīntiān hěn shuài.","He looks very handsome today."],"note":"帅 describes a handsome or stylish appearance. It is commonly used about a person."},"写字":{"word":"写字","pinyin":"xiě zì","meaning":"write characters","sentence":["我正在写字。","Wǒ zhèng zài xiě zì.","I’m writing characters."],"note":"写字 refers to writing written characters. It emphasizes the writing itself, rather than composing an essay."},"汉语":{"word":"汉语","pinyin":"hàn yǔ","meaning":"Chinese (language)","sentence":["我在学习汉语。","Wǒ zài xué xí Hànyǔ.","I’m studying Chinese."],"note":"汉语 names the Chinese language. It commonly appears in language-study contexts."},"预习":{"word":"预习","pinyin":"yùxí","meaning":"preview a lesson","sentence":["我先预习明天的课。","Wǒ xiān yùxí míng tiān de kè.","I’ll preview tomorrow’s lesson first."],"note":"预习 is preparation before a lesson. 复习 is review after you have studied the material."},"早上":{"word":"早上","pinyin":"zǎo shàng","meaning":"morning","sentence":["我早上喝咖啡。","Wǒ zǎo shàng hē kāfēi.","I drink coffee in the morning."],"note":"早上 names the morning. It goes before the action it times."},"一张纸":{"word":"一张纸","pinyin":"yì zhāng zhǐ","meaning":"one sheet of paper","note":"张 counts flat things such as sheets of paper.","sentence":["请给我一张纸。","Qǐng gěi wǒ yì zhāng zhǐ.","Please give me a sheet of paper."]},"真的":{"word":"真的","pinyin":"zhēn de","meaning":"really; true","sentence":["这是真的吗？","Zhè shì zhēn de ma?","Is this really true?"],"note":"真的 can mean real or true. In conversation, 真的？ also asks Really?"},"一枝笔":{"word":"一枝笔","pinyin":"yì zhī bǐ","meaning":"one pen","sentence":["桌上有一枝笔。","Zhuō shàng yǒu yì zhī bǐ.","There is a pen on the table."],"note":"枝 can count slender things. For pens, 一支笔 is the more usual spelling; 支 and 枝 are both zhī."},"旁边":{"word":"旁边","pinyin":"páng biān","meaning":"beside; next to","sentence":["学校在我家旁边。","Xuéxiào zài wǒ jiā páng biān.","The school is next to my home."],"note":"旁边 describes the area beside something. Put the reference place before it: 我家旁边."},"早餐":{"word":"早餐","pinyin":"zǎo cān","meaning":"breakfast","sentence":["我正在吃早餐。","Wǒ zhèng zài chī zǎo cān.","I’m eating breakfast."],"note":"早餐 is the morning meal. 吃早餐 means have breakfast."},"除了":{"word":"除了","pinyin":"chúle","meaning":"apart from; except for","sentence":["除了中文，我还学英文。","Chúle Zhōngwén, wǒ hái xué Yīngwén.","Besides Chinese, I also study English."],"note":"除了 can mean apart from or except for. Here 还 shows that another item is being added."},"起床":{"word":"起床","pinyin":"qǐ chuáng","meaning":"get out of bed","sentence":["我每天七点起床。","Wǒ měi tiān qī diǎn qǐ chuáng.","I get up at seven every day."],"note":"起床 means get out of bed. It is different from merely waking up."},"知道":{"word":"知道","pinyin":"zhī dào","meaning":"know","sentence":["我知道他的名字。","Wǒ zhī dào tā de míngzi.","I know his name."],"note":"知道 is knowing a fact or piece of information. 认识 is commonly used for knowing a person."},"发音":{"word":"发音","pinyin":"fā yīn","meaning":"pronunciation; pronounce","sentence":["这个字的发音是什么？","Zhè ge zì de fā yīn shì shénme?","What is this character’s pronunciation?"],"note":"发音 can be pronunciation or the action of pronouncing. Here it names the sound of the character."},"一封信":{"word":"一封信","pinyin":"yì fēng xìn","meaning":"one letter","sentence":["我收到一封信。","Wǒ shōu dào yì fēng xìn.","I received a letter."],"note":"封 counts letters. 一封信 is one letter, not a single written character."},"告诉":{"word":"告诉","pinyin":"gào sù","meaning":"tell","sentence":["请告诉我你的名字。","Qǐng gào sù wǒ nǐ de míngzi.","Please tell me your name."],"note":"告诉 normally takes the person being told before the information: 告诉我 + information."},"日记":{"word":"日记","pinyin":"rìjì","meaning":"diary","sentence":["我每天写日记。","Wǒ měi tiān xiě rìjì.","I write a diary entry every day."],"note":"日记 is a diary or diary entry. 写日记 is keeping a diary."},"最近":{"word":"最近","pinyin":"zuì jìn","meaning":"recently; lately","sentence":["你最近怎么样？","Nǐ zuì jìn zěnmeyàng?","How have you been lately?"],"note":"最近 marks a recent period around now. The exact length depends on the situation."},"已经":{"word":"已经","pinyin":"yǐjīng","meaning":"already","sentence":["我已经吃饭了。","Wǒ yǐjīng chī fàn le.","I’ve already eaten."],"note":"已经 says an action or state has already occurred. It often appears with 了."},"很累":{"word":"很累","pinyin":"hěn lèi","meaning":"very tired","sentence":["我今天很累。","Wǒ jīntiān hěn lèi.","I’m very tired today."],"note":"累 describes tiredness. 很 can link the subject to this adjective."},"电脑":{"word":"电脑","pinyin":"diànnǎo","meaning":"computer","sentence":["我用电脑学习。","Wǒ yòng diàn nǎo xué xí.","I use a computer to study."],"note":"电脑 names a computer. 用电脑 means to use one for the action that follows."},"能不能":{"word":"能不能","pinyin":"néng bu néng","meaning":"can you?; is it possible?","note":"The positive-negative form asks whether someone can do something.","sentence":["你能不能帮忙？","Nǐ néng bu néng bāng máng?","Can you help?"]},"一篇日记":{"word":"一篇日记","pinyin":"yì piān rìjì","meaning":"one diary entry","sentence":["我写了一篇日记。","Wǒ xiě le yì piān rìjì.","I wrote a diary entry."],"note":"篇 counts pieces of writing. One entry can have many 字, written characters."},"以前":{"word":"以前","pinyin":"yǐ qián","meaning":"before; previously","sentence":["我以前住在北京。","Wǒ yǐ qián zhù zài Běijīng.","I used to live in Beijing."],"note":"以前 points to an earlier time. Here it describes a situation that held in the past."},"宿舍":{"word":"宿舍","pinyin":"sùshè","meaning":"dormitory","sentence":["我住在学校宿舍。","Wǒ zhù zài xuéxiào sùshè.","I live in a school dormitory."],"note":"宿舍 names dormitory accommodation. 舍 is pronounced shè in this word."},"餐厅":{"word":"餐厅","pinyin":"cān tīng","meaning":"dining hall; restaurant","sentence":["我们在餐厅吃饭。","Wǒmen zài cān tīng chī fàn.","We eat in the dining hall."],"note":"餐厅 can be a dining hall or restaurant. Context tells you which type of eating place."},"上网":{"word":"上网","pinyin":"shàng wǎng","meaning":"go online","sentence":["我晚上上网。","Wǒ wǎnshang shàng wǎng.","I go online in the evening."],"note":"上网 is the fixed expression for accessing the internet. 网 refers to the network here."},"希望":{"word":"希望","pinyin":"xīwàng","meaning":"hope","sentence":["我希望明天不下雨。","Wǒ xīwàng míng tiān bú xià yǔ.","I hope it doesn’t rain tomorrow."],"note":"希望 can introduce the situation you hope will happen. It can also be a noun meaning hope."},"洗澡":{"word":"洗澡","pinyin":"xǐ zǎo","meaning":"take a shower; bathe","sentence":["我晚上洗澡。","Wǒ wǎnshang xǐ zǎo.","I take a shower in the evening."],"note":"洗澡 means bathe or take a shower. It does not specify the exact bathing method by itself."},"好笑":{"word":"好笑","pinyin":"hǎo xiào","meaning":"funny","sentence":["这个故事很好笑。","Zhè ge gùshi hěn hǎo xiào.","This story is funny."],"note":"好笑 describes something that makes people laugh. It does not mean beautiful-looking."},"新年":{"word":"新年","pinyin":"xīn nián","meaning":"New Year","sentence":["新年快乐！","Xīn nián kuàilè!","Happy New Year!"],"note":"新年 names the new year. 新年快乐 is the standard good wish."},"专业":{"word":"专业","pinyin":"zhuān yè","meaning":"major; specialty","sentence":["我的专业是中文。","Wǒ de zhuān yè shì Zhōngwén.","My major is Chinese."],"note":"专业 can mean an academic major or professional specialty. Here it is a field of university study."},"用电脑":{"word":"用电脑","pinyin":"yòng diàn nǎo","meaning":"use a computer","sentence":["我用电脑写日记。","Wǒ yòng diàn nǎo xiě rìjì.","I use a computer to write my diary."],"note":"用 names the tool or method used. The next verb says what you do with it."},"正在":{"word":"正在","pinyin":"zhèng zài","meaning":"in the middle of doing…","note":"Put 正在 before an action to say it is happening right now.","sentence":["我正在看书。","Wǒ zhèng zài kàn shū.","I’m reading a book right now."]},"祝你":{"word":"祝你","pinyin":"zhù nǐ","meaning":"wish you…","note":"Follow 祝你 with a good wish, such as a happy birthday.","sentence":["祝你生日快乐！","Zhù nǐ shēng rì kuàilè!","Happy birthday!"]},"最好":{"word":"最好","pinyin":"zuì hǎo","meaning":"best; had better","sentence":["你最好早点睡觉。","Nǐ zuì hǎo zǎo diǎn shuì jiào.","You’d better go to sleep a little earlier."],"note":"最好 can mean best, but before an action it can give advice: had better do something."},"一百":{"word":"一百","pinyin":"yì bǎi","meaning":"one hundred","sentence":["这本书有一百页。","Zhè běn shū yǒu yì bǎi yè.","This book has one hundred pages."],"note":"百 is hundred. 一百 is one hundred; a counted noun or unit can follow it."},"太长":{"word":"太长","pinyin":"tài cháng","meaning":"too long","sentence":["这条裤子太长了。","Zhè tiáo kùzi tài cháng le.","These pants are too long."],"note":"太…了 indicates an excessive or strong degree. Here 长 describes length."},"衬衫":{"word":"衬衫","pinyin":"chènshān","meaning":"shirt","sentence":["我想买一件衬衫。","Wǒ xiǎng mǎi yí jiàn chènshān.","I want to buy a shirt."],"note":"衬衫 names a shirt. 件 is the counter used for one shirt."},"穿衣服":{"word":"穿衣服","pinyin":"chuān yīfu","meaning":"put on clothes; wear clothes","sentence":["他正在穿衣服。","Tā zhèng zài chuān yīfu.","He is putting on his clothes."],"note":"穿衣服 can refer to putting clothes on or wearing them. 正在 makes the action of getting dressed clear here."},"商店":{"word":"商店","pinyin":"shāng diàn","meaning":"store; shop","sentence":["那家商店很大。","Nà jiā shāng diàn hěn dà.","That shop is large."],"note":"商店 is a shop or store. 家 is a common counter for businesses."},"东西":{"word":"东西","pinyin":"dōngxi","meaning":"things; stuff","note":"Here 东西 means “things,” with a neutral-tone xi. For the directions “east and west,” it is dōng xī.","sentence":["我去买东西。","Wǒ qù mǎi dōngxi.","I’m going shopping."]},"三分钱":{"word":"三分钱","pinyin":"sān fēn qián","meaning":"three fen (money)","sentence":["这只需要三分钱。","Zhè zhǐ xūyào sān fēn qián.","This costs only three fen."],"note":"分 is a small unit of money. 三分钱 is a monetary amount, not three minutes."},"付钱":{"word":"付钱","pinyin":"fù qián","meaning":"pay","sentence":["我现在去付钱。","Wǒ xiànzài qù fù qián.","I’m going to pay now."],"note":"付钱 is paying money. It usually describes the buyer’s side of a transaction."},"一共":{"word":"一共","pinyin":"yígòng","meaning":"altogether; in total","sentence":["这些书一共多少钱？","Zhè xiē shū yígòng duōshao qián?","How much do these books cost altogether?"],"note":"一共 adds items together into a total. It commonly appears when stating a total price or quantity."},"去过":{"word":"去过","pinyin":"qù guo","meaning":"have been to…","note":"过 after 去 describes past experience: having been somewhere before.","sentence":["我去过北京。","Wǒ qù guo Běijīng.","I have been to Beijing."]},"合适":{"word":"合适","pinyin":"héshì","meaning":"suitable; fits","sentence":["这件衣服很合适。","Zhè jiàn yīfu hěn héshì.","This item of clothing fits well."],"note":"合适 means suitable. With clothing, it can describe a good fit or appropriateness."},"黑色":{"word":"黑色","pinyin":"hēi sè","meaning":"black","sentence":["我喜欢黑色的衣服。","Wǒ xǐhuan hēi sè de yīfu.","I like black clothes."],"note":"黑色 names the color black. 的 links the color description to the clothing."},"红色":{"word":"红色","pinyin":"hóng sè","meaning":"red","sentence":["这支笔是红色的。","Zhè zhī bǐ shì hóng sè de.","This pen is red."],"note":"红色 is the color red. 色 identifies it as a color word."},"换衣服":{"word":"换衣服","pinyin":"huàn yīfu","meaning":"change clothes","sentence":["我先换衣服。","Wǒ xiān huàn yīfu.","I’ll change clothes first."],"note":"换 means replace or change. 换衣服 means putting on different clothes."},"黄色":{"word":"黄色","pinyin":"huáng sè","meaning":"yellow","sentence":["这件衬衫是黄色的。","Zhè jiàn chènshān shì huáng sè de.","This shirt is yellow."],"note":"黄色 names yellow as a color. Here it describes the shirt."},"售货员":{"word":"售货员","pinyin":"shòu huò yuán","meaning":"sales assistant","sentence":["售货员在帮客人。","Shòu huò yuán zài bāng kè rén.","The sales assistant is helping a customer."],"note":"售货 means sell goods; 员 marks a person in a role. Together they name a retail worker."},"一件衣服":{"word":"一件衣服","pinyin":"yí jiàn yīfu","meaning":"one item of clothing","note":"件 counts items of clothing.","sentence":["我买了一件衣服。","Wǒ mǎi le yí jiàn yīfu.","I bought an item of clothing."]},"信用卡":{"word":"信用卡","pinyin":"xìnyòngkǎ","meaning":"credit card","sentence":["我用信用卡付钱。","Wǒ yòng xìnyòngkǎ fù qián.","I pay with a credit card."],"note":"信用卡 is a credit card. 用 introduces the payment method."},"裤子":{"word":"裤子","pinyin":"kùzi","meaning":"pants; trousers","sentence":["这条裤子很合适。","Zhè tiáo kùzi hěn héshì.","These pants fit well."],"note":"裤子 names trousers or pants. 条 is the counter, even though English uses a pair."},"十块钱":{"word":"十块钱","pinyin":"shí kuài qián","meaning":"ten yuan","sentence":["这本书十块钱。","Zhè běn shū shí kuài qián.","This book costs ten yuan."],"note":"块 is a conversational unit for yuan. 钱 makes clear that the number is an amount of money."},"买东西":{"word":"买东西","pinyin":"mǎi dōngxi","meaning":"buy things; shop","sentence":["我们去商店买东西。","Wǒmen qù shāng diàn mǎi dōngxi.","We’re going to the shop to buy things."],"note":"买东西 is a general expression for shopping. 东西 is neutral-toned at the end here."},"三毛钱":{"word":"三毛钱","pinyin":"sān máo qián","meaning":"three jiao (money)","sentence":["这个东西三毛钱。","Zhè ge dōngxi sān máo qián.","This thing costs three jiao."],"note":"毛 is the everyday term for jiao. It is a money unit here, not hair or fur."},"多少钱":{"word":"多少钱","pinyin":"duōshao qián","meaning":"how much money?","note":"Use this question to ask the price of something.","sentence":["这件衬衫多少钱？","Zhè jiàn chènshān duōshao qián?","How much is this shirt?"]},"虽然":{"word":"虽然","pinyin":"suī rán","meaning":"although","sentence":["虽然下雨，我还是去学校了。","Suī rán xià yǔ, wǒ háishi qù xué xiào le.","Although it was raining, I still went to school."],"note":"虽然 introduces a concession. The following clause explains what happened despite that condition."},"颜色":{"word":"颜色","pinyin":"yánsè","meaning":"color","sentence":["你喜欢什么颜色？","Nǐ xǐhuan shénme yánsè?","What color do you like?"],"note":"颜色 is the general noun color. Put a specific color name in the answer."},"收钱":{"word":"收钱","pinyin":"shōu qián","meaning":"collect money; receive payment","sentence":["售货员在收钱。","Shòu huò yuán zài shōu qián.","The sales assistant is taking payment."],"note":"收钱 means receive or collect payment. Contrast 付钱, paying from the customer’s side."},"刷卡":{"word":"刷卡","pinyin":"shuā kǎ","meaning":"pay by card; swipe a card","sentence":["这里可以刷卡吗？","Zhè lǐ kě yǐ shuā kǎ ma?","Can I pay by card here?"],"note":"刷卡 means swipe or use a card. In a shop, it usually refers to paying by card."},"一双鞋":{"word":"一双鞋","pinyin":"yì shuāng xié","meaning":"one pair of shoes","note":"双 counts pairs; 鞋 means shoes.","sentence":["我买了一双鞋。","Wǒ mǎi le yì shuāng xié.","I bought a pair of shoes."]},"它是":{"word":"它是","pinyin":"tā shì","meaning":"it is…","sentence":["它是我的电脑。","Tā shì wǒ de diànnǎo.","It is my computer."],"note":"它 is the written pronoun for it, usually for things or animals. It sounds the same as 他 and 她."},"一条裤子":{"word":"一条裤子","pinyin":"yì tiáo kùzi","meaning":"one pair of pants","note":"条 counts long items, including pants. In Chinese, one pair of pants is 一条裤子.","sentence":["我想买一条裤子。","Wǒ xiǎng mǎi yì tiáo kùzi.","I want to buy a pair of pants."]},"挺好":{"word":"挺好","pinyin":"tǐng hǎo","meaning":"quite good","sentence":["这件衣服挺好。","Zhè jiàn yīfu tǐng hǎo.","This item of clothing is quite nice."],"note":"挺 before an adjective means quite or rather in conversational speech."},"便宜":{"word":"便宜","pinyin":"piányi","meaning":"inexpensive","sentence":["这件衣服很便宜。","Zhè jiàn yīfu hěn piányi.","This item of clothing is inexpensive."],"note":"便宜 means cheap or inexpensive. 便 is pronounced pián in this word."},"一种":{"word":"一种","pinyin":"yì zhǒng","meaning":"one kind; one type","sentence":["这是一种水果。","Zhè shì yì zhǒng shuǐ guǒ.","This is a kind of fruit."],"note":"种 counts kinds or types. 一种 tells you one category, rather than one individual piece."},"机场":{"word":"机场","pinyin":"jīchǎng","meaning":"airport","sentence":["我现在去机场。","Wǒ xiànzài qù jīchǎng.","I’m going to the airport now."],"note":"机场 is an airport. 机 here is related to airplanes; 场 is a site or grounds."},"汽车":{"word":"汽车","pinyin":"qì chē","meaning":"car","sentence":["他开汽车去学校。","Tā kāi qì chē qù xué xiào.","He drives a car to school."],"note":"汽车 names a motor vehicle or car. 开 is the verb for driving it."},"城市":{"word":"城市","pinyin":"chéng shì","meaning":"city","sentence":["北京是一个大城市。","Běijīng shì yí ge dà chéng shì.","Beijing is a large city."],"note":"城市 names a city. 个 can count individual cities in this sentence."},"出去":{"word":"出去","pinyin":"chū qù","meaning":"go out","sentence":["我们出去走走吧。","Wǒmen chū qù zǒu zǒu ba.","Let’s go out for a walk."],"note":"出 means out and 去 means away from the reference point. 出去 describes going outside."},"地铁":{"word":"地铁","pinyin":"dìtiě","meaning":"subway","sentence":["我坐地铁去学校。","Wǒ zuò dìtiě qù xué xiào.","I take the subway to school."],"note":"坐 names taking a form of transport. 地铁 is the subway or metro."},"麻烦":{"word":"麻烦","pinyin":"máfan","meaning":"trouble; troublesome","sentence":["这件事很麻烦。","Zhè jiàn shì hěn máfan.","This matter is troublesome."],"note":"麻烦 can be trouble, troublesome, or a polite way to ask a favor. Here it describes difficulty or inconvenience."},"飞机":{"word":"飞机","pinyin":"fēijī","meaning":"airplane","sentence":["我坐飞机去北京。","Wǒ zuò fēijī qù Běijīng.","I’m flying to Beijing."],"note":"坐飞机 means travel by plane. 飞机 is the vehicle, not the act of flying."},"寒假":{"word":"寒假","pinyin":"hán jià","meaning":"winter vacation","sentence":["我寒假回家。","Wǒ hán jià huí jiā.","I’m going home during winter vacation."],"note":"寒假 is the winter school break. 假 is pronounced jià when it means a vacation."},"花钱":{"word":"花钱","pinyin":"huā qián","meaning":"spend money","note":"花 here means “spend,” rather than “flower.”","sentence":["我不想花钱。","Wǒ bù xiǎng huā qián.","I don’t want to spend money."]},"或者":{"word":"或者","pinyin":"huò zhě","meaning":"or","sentence":["我们喝茶或者咖啡都可以。","Wǒmen hē chá huò zhě kāfēi dōu kě yǐ.","Either tea or coffee is fine for us."],"note":"或者 presents alternatives in a statement. In a direct choice question, 还是 is often used instead."},"自己":{"word":"自己","pinyin":"zìjǐ","meaning":"oneself","sentence":["我自己去学校。","Wǒ zìjǐ qù xué xiào.","I’m going to school by myself."],"note":"自己 refers back to the person or thing involved. Here it emphasizes going without someone else."},"紧张":{"word":"紧张","pinyin":"jǐnzhāng","meaning":"nervous","sentence":["我考试前很紧张。","Wǒ kǎoshì qián hěn jǐnzhāng.","I’m nervous before an exam."],"note":"紧张 can describe anxiety or a tense situation. Here it is the person’s feeling."},"蓝色":{"word":"蓝色","pinyin":"lán sè","meaning":"blue","sentence":["我喜欢蓝色的衬衫。","Wǒ xǐhuan lán sè de chènshān.","I like blue shirts."],"note":"蓝色 names blue. 的 links the color to the item it describes."},"绿色":{"word":"绿色","pinyin":"lǜ sè","meaning":"green","sentence":["这件衣服是绿色的。","Zhè jiàn yīfu shì lǜ sè de.","This item of clothing is green."],"note":"绿色 names green. 绿 has an ü vowel, written lǜ in pinyin."},"每天":{"word":"每天","pinyin":"měi tiān","meaning":"every day","sentence":["我每天学习中文。","Wǒ měi tiān xué xí Zhōngwén.","I study Chinese every day."],"note":"每 means each or every. 每天 describes something occurring each day."},"买票":{"word":"买票","pinyin":"mǎi piào","meaning":"buy a ticket","sentence":["我去车站买票。","Wǒ qù chē zhàn mǎi piào.","I’m going to the station to buy a ticket."],"note":"票 is a ticket. 买票 can apply to travel, movies, performances, and other ticketed activities."},"让我":{"word":"让我","pinyin":"ràng wǒ","meaning":"let me…","note":"Follow 让我 with an action: “let me…”","sentence":["让我看一下。","Ràng wǒ kàn yíxià.","Let me take a look."]},"送你":{"word":"送你","pinyin":"sòng nǐ","meaning":"give you…; see you off","note":"送你 before a destination can mean take or accompany you there. With an object, it can instead mean give you something.","sentence":["我送你回家。","Wǒ sòng nǐ huí jiā.","I’ll take you home."]},"高速":{"word":"高速","pinyin":"gāo sù","meaning":"high speed","sentence":["这辆车正在高速行驶。","Zhè liàng chē zhèng zài gāosù xíngshǐ.","This car is traveling at high speed."],"note":"高速 describes high speed. 高速公路 means expressway; 高速 alone can also be shorthand for one in a travel context."},"特别":{"word":"特别","pinyin":"tè bié","meaning":"special; especially","sentence":["这个字很特别。","Zhè ge zì hěn tè bié.","This character is special."],"note":"特别 can mean special as an adjective or especially as an adverb. Here it describes a distinctive character."},"路线":{"word":"路线","pinyin":"lù xiàn","meaning":"route","sentence":["这条路线很方便。","Zhè tiáo lù xiàn hěn fāng biàn.","This route is convenient."],"note":"路线 is a route or planned path. 条 is used to count it."},"邮局":{"word":"邮局","pinyin":"yóu jú","meaning":"post office","sentence":["我去邮局寄信。","Wǒ qù yóu jú jì xìn.","I’m going to the post office to mail a letter."],"note":"邮局 is a post office. 寄信 names the action of sending a letter by mail."},"车站":{"word":"车站","pinyin":"chē zhàn","meaning":"station","sentence":["我在车站等你。","Wǒ zài chē zhàn děng nǐ.","I’m waiting for you at the station."],"note":"车站 names a station or stop for vehicles. More specific names can identify the kind of transport."},"出租车":{"word":"出租车","pinyin":"chūzūchē","meaning":"taxi","sentence":["我坐出租车回家。","Wǒ zuò chūzūchē huí jiā.","I’m taking a taxi home."],"note":"出租车 is a taxi. Use 坐出租车 to say you travel in one."},"离学校很近":{"word":"离学校很近","pinyin":"lí xuéxiào hěn jìn","meaning":"very close to the school","sentence":["我家离学校很近。","Wǒ jiā lí xuéxiào hěn jìn.","My home is very close to the school."],"note":"The pattern A 离 B 很近 describes A as close to B. 离 introduces the place used as the distance reference."}};
for(const [word,entry] of Object.entries(C2_CONTENT.examples))EXAMPLE_CONTEXT[word]??=entry;
const EXAMPLE_EXTRA_MEANINGS={'丝':'silk; thread','司':'manage; be in charge','壳':'shell','头':'head','局':'bureau; office','山':'mountain','干':'shield (in 干戈); dry','幼':'young','情':'feeling; emotion','支':'branch; counter for pens','旁':'beside; side','朵':'flower; counter for flowers','物':'thing; object','箭':'arrow','表':'express; show; surface','路':'road; path','阳':'sun; sunlight'};
function exampleDetailPreference(open){state.settings.detailedExamples=open;save();}
function exampleDetailParts(c){const e=EXAMPLE_CONTEXT[c.word];if(!e)return {usage:'',glossary:''};const parts=[...new Set([...e.word].filter(ch=>/\p{Script=Han}/u.test(ch)))],glossary=parts.map(ch=>{const entry=cardByChar[ch]||extra[ch],meaning=EXAMPLE_EXTRA_MEANINGS[ch]||entry?.meaning;if(!meaning)return '';return `<div class="example-part"><span lang="zh">${esc(text(ch))}</span><span>${esc(meaning)}</span></div>`}).join('');return {usage:`${e.note?`<p class="example-note">${esc(e.note)}</p>`:''}${e.sentence?`<div class="example-sentence"><div class="small muted">In a sentence</div><p lang="zh">${esc(text(e.sentence[0]))}</p><div class="sentence-pronunciation"><div class="small example-pinyin">${esc(e.sentence[1])}</div><button class="btn sentence-audio" aria-label="Listen to sentence ${esc(text(e.sentence[0]))}" onclick="speak('${text(e.sentence[0])}')">${icon('sound')} Listen</button></div><p class="small">${esc(e.sentence[2])}</p></div>`:''}`,glossary:glossary?`<div class="example-glossary"><div class="small muted">Individual character meanings</div>${glossary}<p class="small muted">These are dictionary meanings; the whole expression can have a different meaning.</p></div>`:''};}
function exampleMarkup(c,compact=false){const e=EXAMPLE_CONTEXT[c.word];if(!e)return '';const target=han(c),phrase=text(e.word),highlight=[...phrase].map(ch=>ch===target?`<mark class="example-target">${esc(ch)}</mark>`:esc(ch)).join(''),detail=exampleDetailParts(c);return `<section class="character-example${compact?' compact-example':''}"><div class="eyebrow">Example</div><div class="example-heading"><div><div class="example-word" lang="zh">${highlight}</div><div class="example-pinyin">${esc(e.pinyin)}</div></div><button class="btn example-audio${compact?' compact-audio':''}" aria-label="Listen to example ${esc(phrase)}" onclick="speak('${e.word}')">${icon('sound')} ${compact?'Listen':'Listen to example'}</button></div><p class="example-meaning">${esc(e.meaning)}</p>${compact?'':`<details class="example-details" ${state.settings.detailedExamples?'open':''}><summary>More detail</summary>${detail.usage}${detail.glossary}</details>`}</section>`;}
function showStudyDetail(button,tab){const details=button.closest('.study-details');if(!details)return;details.querySelectorAll('.study-tab').forEach(el=>{const active=el.dataset.tab===tab;el.classList.toggle('active',active);el.setAttribute('aria-selected',active)});details.querySelectorAll('.study-pane').forEach(el=>el.classList.toggle('hidden',el.dataset.pane!==tab));}
function studyDetailsMarkup(c){const detail=exampleDetailParts(c);return `<details class="study-details"><summary><span class="study-summary-icon">${icon('layers')}</span><span>Usage &amp; components</span><span class="study-summary-chevron">${icon('chevron')}</span></summary><div class="study-tabs" role="tablist" aria-label="Usage and components"><button class="study-tab active" data-tab="usage" role="tab" aria-selected="true" onclick="showStudyDetail(this,'usage')">Usage</button><button class="study-tab" data-tab="components" role="tab" aria-selected="false" onclick="showStudyDetail(this,'components')">Components</button></div><div class="study-pane" data-pane="usage">${detail.usage}${detail.glossary}</div><div class="study-pane hidden" data-pane="components">${componentMarkup(c.character)}</div></details>`;}
function openStudyCharacter(ch){if(currentView==='reader'&&activeReadingQuiz?.mode==='challenge'&&!activeReadingQuiz.done){activeReadingQuiz.assisted=true;refreshReadingQuiz(activeReadingQuiz.id)}const direct=cardByChar[ch]||extra[ch],traditional=!direct&&CARDS.find(c=>c.traditional===ch);if(direct||traditional){showCharacter((direct||traditional).character);return}if(COMPONENT_DATA[ch])return openComponentCard(ch);const base=Object.entries(tradMap).find(([,value])=>value===ch)?.[0]||ch,context=Object.values(EXAMPLE_CONTEXT).find(e=>e.sentence?.[0].includes(base)||e.word.includes(base)),label=EXAMPLE_EXTRA_MEANINGS[base]||'Used in this example';if($('overlay').innerHTML)lookupCardHistory.push($('overlay').innerHTML);lookupFocus=document.activeElement;$('overlay').innerHTML=`<div class="modal-bg" onclick="if(event.target===this)closeModal()"><section class="modal study-character-modal" role="dialog" aria-modal="true" aria-labelledby="study-character-title"><button class="iconbtn modal-close" onclick="closeModal()" aria-label="Close character">${icon('close')}</button><div class="han">${esc(ch)}</div><h2 id="study-character-title">${esc(label)}</h2><button class="btn" onclick="speak('${esc(ch)}')">${icon('sound')} Listen</button>${context?`<section class="character-example"><div class="eyebrow">From the example</div><p lang="zh" class="context-sentence">${esc(text(context.sentence?.[0]||context.word))}</p>${context.sentence?`<div class="example-pinyin">${esc(context.sentence[1])}</div><p>${esc(context.sentence[2])}</p><button class="btn sentence-audio" onclick="speak('${text(context.sentence[0])}')">${icon('sound')} Listen to sentence</button>`:''}</section>`:''}</section></div>`;document.querySelector('.modal')?.querySelector('button')?.focus();}
function activateStudyCharacters(root){if(!root?.querySelectorAll||!document.createTreeWalker||!document.createElement)return;root.querySelectorAll('.inline-hanzi').forEach(button=>{button.onclick=()=>openStudyCharacter(button.textContent.trim())});root.querySelectorAll('.study-pane').forEach(pane=>{const walker=document.createTreeWalker(pane,window.NodeFilter?.SHOW_TEXT||4),nodes=[];while(walker.nextNode()){const node=walker.currentNode,parent=node.parentElement;if(/\p{Script=Han}/u.test(node.nodeValue)&&!parent?.closest('button,a,input,textarea,select,summary'))nodes.push(node)}nodes.forEach(node=>{const frag=document.createDocumentFragment();for(const part of node.nodeValue.split(/(\p{Script=Han})/u)){if(!part)continue;if(/^\p{Script=Han}$/u.test(part)){const button=document.createElement('button');button.type='button';button.className='inline-hanzi';button.textContent=part;button.setAttribute('aria-label',`Open ${part}`);button.onclick=()=>openStudyCharacter(part);frag.appendChild(button)}else frag.appendChild(document.createTextNode(part))}node.replaceWith(frag)})})}


let lookupCardHistory=[];
PATHS.keyboard='M3 6h18v12H3z M6 9h1 M10 9h1 M14 9h1 M18 9h0 M6 12h1 M10 12h1 M14 12h1 M18 12h0 M7 15h10';
function setPracticeViewport(active){document.body.classList.toggle('practice-focus',!!active)}
function showShapeComparison(index){studyModal('<h2>Shape comparison</h2>'+compareMarkup(index))}
function showQuizAnswerComparison(correct,chosen){const cards=[contrastCard(correct),contrastCard(chosen)];studyModal('<h2>Compare the answers</h2><div class="contrast-grid">'+cards.map((c,i)=>{const d=COMPONENT_DATA[han(c)],parts=componentsOf(han(c)),other=componentsOf(han(cards[1-i])),different=[...parts].filter(p=>!other.has(p)).slice(0,4);return '<section class="contrast-card"><div class="eyebrow">'+(i===0?'Correct answer':'Your choice')+'</div><div class="contrast-glyph" lang="zh">'+esc(han(c))+'</div><strong>'+esc(c.pinyin)+'</strong><p>'+esc(c.meaning)+'</p><p class="small">'+(d?'Radical: '+esc(d.r)+' ('+esc(partName(d.r))+'). ':'')+(different.length?'Look for '+different.map(p=>esc(p)).join(', ')+'.':'Compare the positions and stroke lengths.')+'</p><button class="btn" onclick="openStudyCharacter(\''+c.character+'\')">Open card</button></section>'}).join('')+'</div>')}
function startReviewPrep(){const pool=uniqueCards().filter(c=>state.cards[c.character]?.seen).sort((a,b)=>(state.cards[a.character].streak||0)-(state.cards[b.character].streak||0)||(state.cards[a.character].due||0)-(state.cards[b.character].due||0)).slice(0,state.settings.sessionLength);if(!pool.length)return toast('Learn a few characters first.');startSession('all',null,pool.map(c=>c.character));session.queue=pool;session.batch=pool.map(c=>c.character);renderSession()}
