 const c=raw.companion||{},d=companionDefaults();
 d.enabled=c.enabled!==false;d.starter=['phoenix','dragon','turtle'].includes(c.starter)?c.starter:null;
 d.xp=Number.isSafeInteger(c.xp)&&c.xp>=0?Math.min(c.xp,100000000):Math.min(2000,Object.keys(out.cards).length*3);
 d.stage=Number.isInteger(c.stage)&&c.stage>=0&&c.stage<=2?c.stage:0;
 for(const [key,v]of Object.entries(c.credits||{}).slice(-2500))if(key.length<=250&&Number.isInteger(v)&&v>=0&&v<=100)d.credits[key]=v;
 for(const [key,v]of Object.entries(c.dailyXP||{}).slice(-60))if(/^\d{4}-\d{2}-\d{2}$/.test(key)&&Number.isInteger(v)&&v>=0&&v<=500)d.dailyXP[key]=v;
 d.reviewDays=[...new Set((Array.isArray(c.reviewDays)?c.reviewDays:[]).filter(x=>/^\d{4}-\d{2}-\d{2}$/.test(x)))].slice(-60);
 const cleanResult=r=>r&&Number.isInteger(r.total)&&r.total>=3&&r.total<=400&&Number.isInteger(r.right)&&r.right>=0&&r.right<=r.total&&Number.isFinite(r.at)&&r.at>=0?{total:r.total,right:r.right,score:Math.round(r.right/r.total*100),at:r.at}:null;
 for(const [id,r]of Object.entries(c.leagues||{}))if(/^[a-z0-9-]{1,40}$/.test(id)&&r&&typeof r==='object'){
   const entry={badges:{},trials:{},champion:cleanResult(r.champion)};
   for(const kind of ['badges','trials'])for(const [key,value]of Object.entries(r[kind]||{}))if(/^[a-z0-9-]{1,40}$/.test(key)){
     const clean=cleanResult(value);if(clean&&clean.score>=80)entry[kind][key]=clean;
   }
   if(entry.champion?.score<80)entry.champion=null;d.leagues[id]=entry;
 }
 d.originalStarter=['phoenix','dragon','turtle'].includes(c.originalStarter)?c.originalStarter:d.starter;
 const cleanPartner=p=>({xp:Number.isSafeInteger(p?.xp)&&p.xp>=0?Math.min(p.xp,100000000):0,stage:Number.isInteger(p?.stage)&&p.stage>=0&&p.stage<=2?p.stage:0,reviewDays:[...new Set((Array.isArray(p?.reviewDays)?p.reviewDays:[]).filter(x=>/^\d{4}-\d{2}-\d{2}$/.test(x)))].slice(-60),joinedAt:Number.isFinite(p?.joinedAt)&&p.joinedAt>=0?p.joinedAt:0});
 if(c.collectionVersion===1){for(const id of ['phoenix','dragon','turtle'])if(c.roster?.[id]&&typeof c.roster[id]==='object')d.roster[id]=cleanPartner(c.roster[id]);if(d.starter&&!d.roster[d.starter])d.starter=d.roster[d.originalStarter]?d.originalStarter:Object.keys(d.roster)[0]||null;}
 else if(d.starter)d.roster[d.starter]={xp:d.xp,stage:d.stage,reviewDays:[...d.reviewDays],joinedAt:0};
 if(d.starter&&d.roster[d.starter]){d.xp=d.roster[d.starter].xp;d.stage=d.roster[d.starter].stage;d.reviewDays=[...d.roster[d.starter].reviewDays]}
 if(d.originalStarter&&!d.roster[d.originalStarter])d.originalStarter=d.starter;
