function badgeCount(course=activeLeague()){const r=courseRecord(course.id);return course.badges.filter(b=>r.badges[b.id]).length}
function companionStage(){const c=state.companion,level=companionLevel(),badges=COURSE_LEAGUES.reduce((n,l)=>n+badgeCount(l),0);let stage=c.stage;if(level>=8&&badges>=2&&c.reviewDays.length>=1)stage=Math.max(stage,1);if(level>=16&&badges>=5&&c.reviewDays.length>=3)stage=2;return stage}
function reconcileCompanion(){
 state.companion??=companionDefaults();state.profile??={name:'',setupDone:false};
 for(const league of COURSE_LEAGUES){const r=courseRecord(league.id);for(const badge of league.badges){
  if(!r.badges[badge.id]&&badge.chapters.every(id=>state.quizzes.chapters[id]?.passed)){
   const all=badge.chapters.map(id=>state.quizzes.chapters[id]),total=all.reduce((n,q)=>n+q.total,0),right=all.reduce((n,q)=>n+q.right,0);
   r.badges[badge.id]={total,right,score:Math.round(right/total*100),at:Math.max(...all.map(q=>q.at)),legacy:true};
  }
 }}
 const next=companionStage();if(next>state.companion.stage){state.companion.stage=next;return true}return false;
}
function awardXP(key,amount){
 const c=state.companion,day=dayKey(),k=day+':'+key,already=c.credits[k]||0,target=Math.max(already,amount);
 const delta=Math.min(target-already,Math.max(0,500-(c.dailyXP[day]||0)));
 if(delta<=0)return 0;c.credits[k]=already+delta;c.dailyXP[day]=(c.dailyXP[day]||0)+delta;c.xp+=delta;
 const keys=Object.keys(c.credits);if(keys.length>2200)for(const old of keys.filter(k=>/^\d{4}-\d{2}-\d{2}:/.test(k)).slice(0,keys.length-1800))delete c.credits[old];
 const days=Object.keys(c.dailyXP).sort();for(const old of days.slice(0,-45))delete c.dailyXP[old];
 reconcileCompanion();return delta;
}
function awardCharacterTraining(ch,kind,correct,hinted,before){
 const later=correct&&!hinted&&before?.last&&dayKey(new Date(before.last))!==dayKey();
 if(later&&!state.companion.reviewDays.includes(dayKey()))state.companion.reviewDays.push(dayKey());
 return awardXP(kind+':'+ch,correct?(hinted?1:later?5:3):1);
}
