function leagueHintToggle(){const q=quizSession?.questions[quizSession.pos];if(!q||q.chosen!==null)return;q.usedHint=true;q.hint=!q.hint;renderQuiz()}
function leagueNext(){const s=quizSession;if(s?.kind!=='league'||s.done||s.questions[s.pos]?.chosen===null)return;s.pos++;renderQuiz()}
function recordLeagueResult(s){
 const right=s.questions.filter(q=>q.chosen===q.correct&&!q.usedHint).length,total=s.questions.length,score=Math.round(right/total*100),passed=score>=80,result={right,total,score,at:Date.now()};
 s.right=right;s.done=true;
 if(!s.recorded){const record=courseRecord(s.course),key=s.leagueKind==='champion'?'champion':s.leagueId,existing=s.leagueKind==='champion'?record.champion:record[s.leagueKind==='badge'?'badges':'trials'][key];
 if(passed){if(s.leagueKind==='champion'){if(!existing||score>existing.score)record.champion=result}else{const collection=record[s.leagueKind==='badge'?'badges':'trials'];if(!existing||score>existing.score)collection[key]=result}
 if(!existing)s.earnedXP=awardXP('milestone:'+s.course+':'+s.leagueKind+':'+key,s.leagueKind==='champion'?100:50);
 }
 s.recorded=true;reconcileCompanion();save();}
 return {score,passed,right,total};
}
