function companionReactionArt(mood='idle'){
 const s=starterData();if(!s)return '';let art=companionArt(s.id,state.companion.stage);
 if(['happy','celebrate'].includes(mood))art=art.replace(/<ellipse cx="(85|115)" cy="100" rx="6" ry="9" fill="[^"]*"\/>/g,(_,x)=>`<path d="M${Number(x)-6} 101q6-10 12 0" fill="none" stroke="${s.ink}" stroke-width="3"/>`).replace(/<circle cx="(87|117)" cy="97" r="2" fill="white"\/>/g,'');
 if(mood==='thinking')art=art.replace('<ellipse cx="115" cy="100" rx="6" ry="9"', '<ellipse cx="115" cy="100" rx="6" ry="5"');
 if(mood==='encourage')art=art.replace('M94 114q6 7 12 0','M94 115q6 4 12 0');
 const extra=mood==='celebrate'?'<path d="M24 40l3-9 4 8 9 1-7 6 2 9-8-5-8 5 2-9-7-6zM158 37l3-8 4 7 8 1-6 6 1 8-7-4-7 4 2-8-6-5z" fill="#d7ad68"/>':mood==='happy'?'<path d="M163 58c-10-13-22 1 0 16 22-15 10-29 0-16" fill="#cb796b"/>':mood==='thinking'?`<text x="156" y="64" fill="${s.ink}" font-size="27" font-family="sans-serif">?</text>`:'';
 return art.replace('</svg>',extra+'</svg>');
}
