// Short, locally generated sounds; no downloads or background music.
let studyAudioContext=null,studySoundNodes=[],studySoundPriority=0,studySoundUntil=0;
const STUDY_SOUNDS={
 correct:{priority:1,notes:[[660,0,.09],[880,.07,.13]]},
 almost:{priority:1,notes:[[520,0,.12]]},
 retry:{priority:1,notes:[[330,0,.1],[294,.08,.12]]},
 complete:{priority:2,notes:[[523,0,.12],[659,.1,.12],[784,.2,.2]]},
 milestone:{priority:3,notes:[[523,0,.13],[659,.11,.13],[784,.22,.13],[1047,.33,.26]]}
};
function stopStudySounds(){for(const node of studySoundNodes){try{node.stop()}catch(e){}}studySoundNodes=[];studySoundPriority=0;studySoundUntil=0}
function getStudyAudioContext(){
 if(!state.settings.soundEffects||document.visibilityState==='hidden')return null;
 try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return null;
 if(!studyAudioContext||studyAudioContext.state==='closed')studyAudioContext=new Audio();return studyAudioContext}catch(e){return null}
}
function unlockStudyAudio(){const ctx=getStudyAudioContext();if(ctx?.state==='suspended')ctx.resume().catch(()=>{})}
function playStudySound(kind){
 const sound=STUDY_SOUNDS[kind];if(!sound||!state.settings.soundEffects||document.visibilityState==='hidden'||window.speechSynthesis?.speaking)return;
 const ctx=getStudyAudioContext();if(!ctx)return;
 function scheduleSound(){
  if(ctx.state!=='running'||!state.settings.soundEffects||document.visibilityState==='hidden'||window.speechSynthesis?.speaking)return;
  if(ctx.currentTime<studySoundUntil&&sound.priority<studySoundPriority)return;
  stopStudySounds();studySoundPriority=sound.priority;
  const start=ctx.currentTime+.012;studySoundUntil=start+.65;
  try{for(const [frequency,offset,duration]of sound.notes){
   const oscillator=ctx.createOscillator(),gain=ctx.createGain(),at=start+offset;
   oscillator.type='sine';oscillator.frequency.setValueAtTime(frequency,at);
   gain.gain.setValueAtTime(0,at);gain.gain.linearRampToValueAtTime(.055,at+.012);gain.gain.exponentialRampToValueAtTime(.001,at+duration);
   oscillator.connect(gain);gain.connect(ctx.destination);studySoundNodes.push(oscillator);
   oscillator.onended=()=>{oscillator.disconnect();gain.disconnect();studySoundNodes=studySoundNodes.filter(n=>n!==oscillator)};
   oscillator.start(at);oscillator.stop(at+duration+.02);
  }}catch(e){stopStudySounds()}
 }
 if(ctx.state==='suspended')ctx.resume().then(scheduleSound).catch(()=>{});else scheduleSound();
}
