// Pronunciation support uses pinyin spelling, mouth position, and Mandarin audio.
const TONE_GUIDE={
 1:{name:'High and level',short:'Level',instruction:'Keep your voice high and steady from start to finish.',path:'M10 14H90'},
 2:{name:'Rising',short:'Rise',instruction:'Start at a middle pitch and glide upward. Keep it one smooth syllable.',path:'M10 42Q50 34 90 12'},
 3:{name:'Low / dipping',short:'Low',instruction:'Let your voice sink low. Alone, it can dip and rise; in connected speech it often stays low.',path:'M10 30Q46 72 90 22'},
 4:{name:'Falling',short:'Fall',instruction:'Start high and drop firmly to a low pitch. Change pitch, not just loudness.',path:'M10 12Q42 26 90 56'},
 0:{name:'Neutral',short:'Light',instruction:'Say it lightly and briefly. Its pitch follows the preceding syllable, rather than a fixed contour.',path:'M43 33H57'}
};
const INITIAL_GUIDE={
 b:['b','Close both lips, then release with little breath. Mandarin b is not the voiced English b.'],
 p:['p','Close both lips and release with a clear puff of air.'],
 m:['m','Close your lips; let the sound resonate through your nose.'],
 f:['f','Rest upper teeth lightly on the lower lip and let air pass.'],
 d:['d','Touch the tongue tip just behind the upper teeth; release with little breath.'],
 t:['t','Use the same tongue position as d, with a clear puff of air.'],
 n:['n','Touch the tongue behind the upper teeth and let sound pass through the nose.'],
 l:['l','Touch the tongue behind the upper teeth; let sound pass around its sides.'],
 g:['g','Raise the back of the tongue to the soft palate; release with little breath.'],
 k:['k','Use the same back-of-tongue position as g, with a puff of air.'],
 h:['h','Let air gently rub past the raised back of your tongue. It is stronger than English h.'],
 j:['j','Keep the tongue tip behind the lower teeth and raise the front of the tongue. Release with little breath.'],
 q:['q','Use the front-of-tongue position of j, with a clear puff of air. It is not English k.'],
 x:['x','Keep the tongue tip behind the lower teeth; raise the front and let air hiss through. It is not English ks.'],
 zh:['zh','Lift the tongue tip toward the roof, slightly curled back; release with little breath.'],
 ch:['ch','Use the curled-back position of zh, with a puff of air.'],
 sh:['sh','Lift the tongue tip slightly back and make a sustained hiss.'],
 r:['r','Lift the tongue tip slightly back and use a voiced, gentle buzzing sound. It differs from English r.'],
 z:['z','With the tongue near the upper teeth, release a short ts-like sound with little breath.'],
 c:['c','Use the same ts-like sound as z with a clear puff of air.'],
 s:['s','Keep the tongue near the upper teeth and make a hiss.'],
 y:['y','Start with a smooth ee-like glide. Pinyin y mainly marks a syllable without another initial.'],
 w:['w','Start with rounded lips and an oo-like glide. Pinyin w mainly marks a syllable without another initial.']
};
const FINAL_GUIDE={
 a:['ah','Open your mouth for an ah-like vowel.'],
 o:['rounded oh','Round your lips. After b, p, m, or f, a brief oo-like glide may lead into this vowel.'],
 e:['unrounded vowel','Keep the tongue back while your lips stay unrounded. It has no exact English equivalent.'],
 ai:['eye','Glide from an open ah toward ee in one syllable.'],
 ei:['ay','Glide toward ee, roughly like the vowel in “day.”'],
 ao:['ow','Glide from ah toward oo, roughly like the vowel in “how.”'],
 ou:['oh → oo','Make one smooth glide, roughly like the vowel in “go.”'],
 an:['ah + n','End with the tongue touching behind the upper teeth.'],
 en:['uh + n','Use a relaxed central vowel; end with n.'],
 ang:['ah + ng','End with a back-of-tongue nasal. Do not add a separate g sound.'],
 eng:['uh + ng','Use a central vowel and a back-of-tongue nasal; do not add g.'],
 ong:['rounded oo + ng','Use a short, rounded vowel and finish with the back-of-tongue nasal.'],
 i:['ee','Keep the tongue high and forward; spread the lips gently.'],
 ia:['ee → ah','Glide into ah without making two separate syllables.'],
 ie:['ee → eh','Glide into an eh-like vowel, as in “yes,” without adding s.'],
 iao:['ee → ow','Glide from a high front tongue position into the ao vowel.'],
 iou:['ee → oh → oo','Make one smooth syllable. After an initial, pinyin shortens iou to iu.'],
 ian:['ee → eh + n','The middle vowel is closer to eh than ah. End with n.'],
 in:['ee + n','End with the tongue behind the upper teeth; keep the vowel forward.'],
 iang:['ee → ah + ng','Glide into ah and finish with the back-of-tongue nasal.'],
 ing:['ee + ng','Finish with the back-of-tongue nasal. Do not add g.'],
 iong:['front glide + rounded vowel + ng','Start with a front glide, round your lips, then finish with ng.'],
 u:['oo','Round your lips and keep the tongue high toward the back.'],
 ua:['oo → ah','Move smoothly from rounded lips into an open ah vowel.'],
 uo:['oo → rounded oh','Keep the movement smooth and within one syllable.'],
 uai:['oo → eye','Make a rounded glide into ai; do not separate it into two syllables.'],
 uei:['oo → ay','A rounded glide leads into ei. After an initial, pinyin shortens uei to ui.'],
 uan:['oo → ah + n','Glide into ah and end with the front-of-tongue n.'],
 uen:['oo → uh + n','After most initials, pinyin shortens uen to un. End with n, not ng.'],
 uang:['oo → ah + ng','Glide into ah and finish with the back-of-tongue nasal.'],
 ueng:['oo → uh + ng','Keep the rounded opening, then finish with ng.'],
 ü:['rounded ee','Say ee with your tongue, but round your lips as if saying oo. Keep the tongue forward.'],
 üe:['rounded ee → eh','Start with the ü mouth position and glide into eh.'],
 üan:['rounded front glide → eh + n','Start with rounded lips and the tongue forward; end with an eh-like vowel plus n.'],
 ün:['rounded ee + n','Keep the ü tongue position and end with n.'],
 er:['curled-tongue vowel','Use a central vowel and curl the tongue tip slightly back. Do not say “air.”'],
 dentalI:['held vowel after z / c / s','Keep the tongue near the teeth after the initial. This i is not the ee of mi.'],
 retroflexI:['held vowel after zh / ch / sh / r','Keep the tongue tip slightly back after the initial. This i is not an ee vowel.']
};
const CONTEXT_READINGS={'还':'hái means still or also; huán means return.','为':'wèi is used for “for”; wéi appears in other meanings.','得':'de is a complement particle; dé means obtain; děi means must.','觉':'jué is used in 觉得; jiào is used in 睡觉.','乐':'yuè is used in 音乐; lè is used in 快乐.','只':'zhǐ means only; zhī is a counting word.','行':'xíng means okay; háng is used in 银行.','教':'jiāo means teach; jiào is used in 教室.','长':'cháng means long; zhǎng is used in 长大.','都':'dōu means all or both; dū means a capital city.','没':'méi is used in 没有; mò is used for sinking or submerging.'};
