function pinyinSound(raw){
 const source=String(raw).trim().toLowerCase(),decomposed=source.normalize('NFD');
 let tone=0;for(const [mark,value]of [['\u0304',1],['\u0301',2],['\u030c',3],['\u0300',4]])if(decomposed.includes(mark)){tone=value;break}
 const numbered=source.match(/[0-5]$/);if(numbered)tone=Number(numbered[0])%5;
 const base=decomposed.replace(/u\u0308/g,'ü').replace(/[\u0300\u0301\u0304\u030c]/g,'').replace(/[0-5]$/,'').replace(/u:|v/g,'ü');
 const initial=base.match(/^(zh|ch|sh|[bpmfdtnlgkhjqxrzcsyw])/i)?.[0]||'';
 let final=base.slice(initial.length),spelling='';
 if(initial==='y')final=({i:'i',in:'in',ing:'ing',a:'ia',e:'ie',ao:'iao',ou:'iou',an:'ian',ang:'iang',ong:'iong',u:'ü',ue:'üe',uan:'üan',un:'ün'})[final]||final;
 if(initial==='w')final=({u:'u',a:'ua',o:'uo',ai:'uai',ei:'uei',an:'uan',en:'uen',ang:'uang',eng:'ueng'})[final]||final;
 if(['j','q','x'].includes(initial)&&final.startsWith('u')){final='ü'+final.slice(1);spelling='After j, q, or x, written u is the rounded-front ü sound.'}
 if(initial==='y'&&['ü','üe','üan','ün'].includes(final))spelling='In yu, yue, yuan, and yun, the written u keeps the ü sound.';
 if(final==='iu')final='iou';if(final==='ui')final='uei';if(final==='un')final='uen';
 if(final==='i'&&['z','c','s'].includes(initial))final='dentalI';
 if(final==='i'&&['zh','ch','sh','r'].includes(initial))final='retroflexI';
 return {pinyin:raw,base,initial,final,tone,spelling,start:INITIAL_GUIDE[initial]||['Vowel start','Begin directly with the vowel; do not add an extra consonant.'],end:FINAL_GUIDE[final]||null};
}
function characterSounds(c){return String(c.pinyin).split(/\s*[/;]\s*/).map(pinyinSound)}
function toneDiagram(tone,compact=false){const guide=TONE_GUIDE[tone]||TONE_GUIDE[0];return `<svg class="tone-curve ${compact?'tone-compact':''}" viewBox="0 0 100 70" role="img" aria-label="${tone?'Tone '+tone+': ':''}${guide.name}"><path class="tone-axis" d="M10 60H92M10 60V8"/><path class="tone-motion" d="${guide.path}"/><circle class="tone-start" cx="${tone===0?43:10}" cy="${tone===1?14:tone===2?42:tone===3?30:tone===4?12:33}" r="3"/></svg>`}
function tonePill(c){const sounds=characterSounds(c),tone=sounds[0].tone;return `<button class="tone-pill" type="button" onclick="openPronunciation('${c.character}')" aria-label="Pronunciation and tone guidance">${toneDiagram(tone,true)}<span>${sounds.length>1?sounds.length+' readings':tone?'Tone '+tone+' · '+TONE_GUIDE[tone].short:'Neutral tone'}</span>${icon('chevron')}</button>`}
