function wholeShapeArt(c,hint=false){const glyph=han(c),path=SHAPE_MEMORY[glyph]||(!hint&&(MEMORY_SCENES[c.character]||SHAPE_MEMORY[c.character]));return path?`<svg class="memory-sketch" viewBox="0 0 80 80" aria-hidden="true"><path d="${path}"/></svg>`:`<span class="memory-whole" lang="zh">${hint?'⋯':esc(glyph)}</span>`}
