function readingSkill(q){return q.skill||(/why/i.test(q.prompt)?'Explain why':/first|last|when|time/i.test(q.prompt)?'Track time':/both|share|different|describe|despite|how/i.test(q.prompt)?'Connect ideas':'Find a detail')}
function evidenceQuestion(r){
 for(const original of r.quiz){const hits=r.lines.filter(line=>line[0].includes(original.evidence)||original.evidence.includes(line[0]));if(hits.length!==1)continue;
 const answer=hits[0][0],choices=[...new Set(r.lines.map(line=>line[0]))];if(choices.length<2)continue;
 return {prompt:'Which paragraph answers this question? '+original.prompt,answer,choices,chineseChoices:true,evidence:original.evidence,explanation:original.answer+' — '+original.evidence,skill:'Match Chinese evidence',original};
 }return null;
}
const learningMakeReadingQuiz=makeReadingQuiz;
makeReadingQuiz=function(id,mode='guided'){const s=learningMakeReadingQuiz(id),r=READINGS.find(r=>r.id===id);if(!s)return null;s.mode=mode==='challenge'?'challenge':'guided';s.previousChallengeBest=state.readingQuizzes[id]?.challengeBest;if(s.mode==='challenge'){const evidence=evidenceQuestion(r);if(evidence){const index=r.quiz.indexOf(evidence.original);delete evidence.original;s.questions[index]={...evidence,choices:shuffle(evidence.choices),chosen:null}}}return s};
const learningStartReadingQuiz=startReadingQuiz;
startReadingQuiz=function(id,mode='guided'){const r=READINGS.find(r=>r.id===id);if(!r)return;restoreChallengeAids();activeReadingQuiz=makeReadingQuiz(id,mode);if(mode==='challenge'){activeReadingQuiz.previousOptions={...readerOptions};readerOptions.pinyin=false;readerOptions.translation=false;renderReader(id)}refreshReadingQuiz(id);$('reading-quiz').scrollIntoView?.({block:'start',behavior:'smooth'});$('reading-quiz').querySelector('.reading-quiz-choice')?.focus()};
function showReadingHelp(id){const s=activeReadingQuiz;if(!s||s.id!==id||s.done)return;s.assisted=true;readerOptions.pinyin=true;readerOptions.translation=true;renderReader(id);$('reading-quiz').scrollIntoView?.({block:'start',behavior:'smooth'})}
const learningReadingMarkup=readingQuizMarkup;
readingQuizMarkup=function(id){const r=READINGS.find(r=>r.id===id),s=activeReadingQuiz?.id===id?activeReadingQuiz:null;
 if(!s){const best=state.readingQuizzes[id];return `<div class="row home-panel-heading"><h2>Check your reading</h2><span class="badge">${esc(readingLevel(r))}</span></div><p class="small muted">3 questions · Get all three right.</p>${best&&readingQuizCurrent(id)?`<p class="small muted">Best: ${best.best}%${best.challengeBest!==undefined?' · Challenge: '+best.challengeBest+'%':''}</p>`:''}<div class="row"><button class="btn primary" onclick="startReadingQuiz('${id}')">Quick check</button><button class="btn" onclick="startReadingQuiz('${id}','challenge')">Reading challenge</button></div><details class="quiet-details"><summary>What’s the difference?</summary><p class="small">Quick check keeps your reading aids. Challenge hides pinyin and translation and asks you to find evidence in the Chinese passage. You can ask for help; assisted challenges are saved as practice.</p></details>`}
 let markup=learningReadingMarkup(id);
 if(!s.done){const q=s.questions[s.pos];markup=markup.replace('<h2>Reading quiz</h2>',`<h2>${s.mode==='challenge'?'Reading challenge':'Quick check'}</h2>`);markup=markup.replace('<p class="reading-quiz-prompt">',`<span class="reading-skill">${esc(readingSkill(q))}</span><p class="reading-quiz-prompt">`);if(s.mode==='challenge'&&!s.assisted)markup+=`<button class="textbtn" onclick="showReadingHelp('${id}')">Show reading help</button>`}
 else{markup=markup.replace('Reading completed',s.mode==='challenge'?(s.assisted?'Practice completed':'Challenge completed'):'Reading completed').replace('<p class="muted">All answers correct.</p>',`<p class="muted">${s.assisted?'Completed with help. Try the challenge again without reading aids.':'All three correct.'}</p>`);markup=markup.replace(`onclick="startReadingQuiz('${id}')">Retry quiz`, `onclick="startReadingQuiz('${id}','${s.mode}')">Try again`)}
 return markup;
};
const learningReadingNext=nextReadingQuiz;
nextReadingQuiz=function(id){const s=activeReadingQuiz,wasDone=s?.done;learningReadingNext(id);if(s&&s.done&&!wasDone){const record=state.readingQuizzes[id];record.mode=s.assisted?'guided':s.mode;if(s.previousChallengeBest!==undefined)record.challengeBest=s.previousChallengeBest;if(s.mode==='challenge'&&!s.assisted)record.challengeBest=Math.max(s.previousChallengeBest||0,record.score);save();if(s.previousOptions){restoreChallengeAids(s);renderReader(id)}refreshReadingQuiz(id)}};
const learningReaderRender=renderReader;
renderReader=function(id){learningReaderRender(id);const s=activeReadingQuiz;if(s?.id===id&&!s.done&&s.mode==='challenge'){const controls=$('view').querySelector('.reader-controls');controls?.querySelectorAll('button').forEach(button=>{if(/^Pinyin$|^Translation$/.test(button.textContent.trim())){button.setAttribute('disabled','');button.setAttribute('title','Use Show reading help during a challenge.')}})}};
const learningStoryCards=readingStoryCards;
readingStoryCards=function(readings){return learningStoryCards(readings).replace(/(<h3>)([\s\S]*?)(<\/h3>)/g,(match,start,title,end)=>{const r=readings.find(r=>esc(r.title)===title||r.title===title);return r?`${start}${title}${end}<span class="reading-level">${esc(readingLevel(r))}</span>`:match})};

// A clear daily action and a visible course path; all chapters remain available.
PATHS.tools='M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z';
PATHS.help='M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M9 9a3 3 0 0 1 6 0c0 2-3 2-3 4 M12 17h0';
PATHS.clock='M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l3 2';
PATHS.save='M5 3h12l3 3v15H4V3z M8 3v6h8V3 M8 21v-7h8v7';
const COURSE_OUTCOMES={'I':'Shapes, components, and numbers','1':'Names, greetings, and introductions','2':'Family members and occupations','3':'Dates, birthdays, and time','4':'Likes, hobbies, and activities','5':'Visits, drinks, and conversation','6':'Calls, availability, and appointments','7':'Reading, writing, and studying','8':'Campus, classes, and routines','9':'Clothes, colors, sizes, and prices','10':'Transport, directions, and trips'};
function courseState(id){const p=progress(id),quiz=!!state.quizzes.chapters[id]?.passed,read=READINGS.some(r=>r.lesson===id&&state.read[r.id]);return {...p,quiz,read,complete:p.practiced===p.total&&quiz&&read,stage:p.practiced<p.total?0:!quiz?1:!read?2:3}}
function courseFocusId(){if(!uniqueCards().some(c=>state.cards[c.character]?.seen))return currentCourse().lessons[0];const index=courseChapters().findIndex(c=>c[0]===state.lastChapter),id=courseChapters()[index]?.[0]||currentCourse().lessons[0];if(!courseState(id).complete)return id;return courseChapters().slice(index+1).find(c=>!courseState(c[0]).complete)?.[0]||CHAPTERS.find(c=>!courseState(c[0]).complete)?.[0]||id}
function coursePercent(){return Math.round(courseChapters().reduce((sum,[id])=>{const s=courseState(id);return sum+s.practiced/s.total+Number(s.quiz)+Number(s.read)},0)/(courseChapters().length*3)*1000)/10}
function nextBatchSize(id){const all=uniqueCards(id),newCards=all.filter(c=>!state.cards[c.character]?.seen),weak=all.filter(c=>!familiar(c));return Math.min(state.settings.sessionLength,(newCards.length?newCards:weak.length?weak:all).length)}
function stageAction(id,stage){return stage===0?`startSession('learn','${id}')`:stage===1?`startQuiz('chapter','${id}')`:`openReading('${READINGS.find(r=>r.lesson===id)?.id||READINGS[0].id}')`}
function courseNext(id=courseFocusId()){const s=courseState(id),next=courseChapters()[courseChapters().findIndex(c=>c[0]===id)+1];return s.stage===0?{title:'Learn characters',label:'Learn '+nextBatchSize(id)+' characters',action:stageAction(id,0),note:s.practiced+'/'+s.total+' practiced'}:s.stage===1?{title:'Check your recall',label:'Take the chapter quiz',action:stageAction(id,1),note:'80% without hints to pass'}:s.stage===2?{title:'Read a passage',label:'Start reading',action:stageAction(id,2),note:'Put this chapter’s characters into context'}:(()=>{const after=courseChapters().slice(courseChapters().findIndex(c=>c[0]===id)+1).find(c=>!courseState(c[0]).complete)||CHAPTERS.find(c=>!courseState(c[0]).complete);return after?{title:'Chapter complete',label:'Continue to '+after[1],action:`openChapter('${after[0]}')`,note:'Characters, quiz, and reading complete'}:{title:'Course complete',label:'Review the course',action:'startDailyPractice()',note:'Keep your characters familiar with reviews'}})() }
function stageRail(id,interactive=true){const s=courseState(id),done=[s.practiced===s.total,s.quiz,s.read];return `<ol class="flow-stage-rail" aria-label="Chapter study path">${[['Learn','Characters','learn'],['Check','Recall quiz','check'],['Read','A passage','read']].map(([label,detail,glyph],i)=>`<li class="${done[i]?'done':s.stage===i?'current':''}" ${s.stage===i?'aria-current="step"':''}>${interactive?`<button type="button" onclick="${stageAction(id,i)}" aria-label="${label}: ${detail}">`:'<span class="stage-content">'}<span class="stage-dot">${icon(done[i]?'check':glyph)}</span><span><strong>${label}</strong><small>${detail}</small></span>${interactive?'</button>':'</span>'}</li>`).join('')}</ol>`}
function primaryStudyAction(){const id=courseFocusId(),next=courseNext(id),today=state.activity[dayKey()]?.cards||0,due=dueCards();if(savedResume){const r=savedResume,kind=r.kind==='write'?'writing':r.kind==='quiz'||r.kind==='league'?'quiz':'practice',total=r.kind==='quiz'||r.kind==='league'?r.data.questions.length:r.data.queue.length;return {id:CHAPTERS.some(c=>c[0]===r.chapter)?r.chapter:id,type:'resume',title:'Resume '+kind,label:'Resume session',action:'resumeSession()',note:'Item '+(r.data.pos+1)+' of '+total}}
 if(due.length&&today<state.settings.goal)return {id,type:'review',title:'Review due characters',label:'Review '+Math.min(due.length,state.settings.sessionLength)+' characters',action:"startSession('review')",note:due.length+' due for review'};
 return {id,type:'learn',...next};
}
function miniCompanion(){if(!state.companion.enabled)return '';const starter=starterData();return starter?`<button class="flow-companion" type="button" onclick="openJourney()" aria-label="Open companion and badges">${companionArt(starter.id,state.companion.stage)}<span><strong>${esc(starter.forms[state.companion.stage])}</strong><small>Level ${companionLevel()} · ${badgeCount()} / ${activeLeague().badges.length} badges</small></span>${icon('chevron')}</button>`:`<button class="flow-companion choose-companion" type="button" onclick="openCompanionSelection()">${icon('flame')}<span>Choose a companion <small>Optional</small></span>${icon('chevron')}</button>`}
function flowSaveStatus(){return storageOK?`<span class="flow-save-status">${icon('check')} Saved on this device</span>`:`<div class="flow-save-alert" role="alert"><strong>Automatic saving is unavailable.</strong><button class="btn" onclick="exportBackup()">Export a backup</button></div>`}
renderHome=function(){
 const action=primaryStudyAction(),id=action.id,ch=CHAPTERS.find(c=>c[0]===id),s=courseState(id),today=state.activity[dayKey()]?.cards||0,goal=state.settings.goal,known=uniqueCards().filter(familiar).length,complete=courseChapters().filter(c=>courseState(c[0]).complete).length,hour=new Date().getHours(),greeting=hour<12?'Good morning':hour<18?'Good afternoon':'Good evening',first=action.type!=='resume'&&!uniqueCards().some(c=>state.cards[c.character]?.seen),percent=Math.min(100,today/goal*100),starter=state.companion.enabled&&starterData();
 $('view').innerHTML=`<div class="flow-home"><div class="heading"><div><h1>${greeting}${state.profile.name?', '+esc(state.profile.name):''}.</h1></div><span class="badge">${state.settings.script==='traditional'?'Traditional':'Simplified'}</span></div>
 <section class="flow-next home-continue"><div class="flow-next-copy"><span class="eyebrow">${first?'Start here':action.type==='resume'?'Where you left off':action.type==='review'?'Due review':'Up next'} · ${id==='I'?'Foundations':lessonLabel(id)}</span><h2>${esc(first?'Foundations':action.title)}</h2><p>${esc(first?'Start with the shapes. Reveal, listen, then rate your recall.':action.note)}</p><button class="btn primary flow-primary" onclick="${action.action}">${esc(first?'Learn '+nextBatchSize('I')+' characters':action.label)} ${icon('arrow')}</button><button class="textbtn flow-secondary" onclick="${action.type==='review'?courseNext(id).action:`openChapter('${id}')`}">${action.type==='review'?'Keep learning instead':'View chapter'}</button></div><div class="flow-next-art" aria-hidden="true">${starter?companionArt(starter.id,state.companion.stage):`<span lang="zh">${text(ch[3])}</span><i></i>`}</div></section>
 <section class="flow-path-summary"><div class="flow-section-heading"><h2>${id==='I'?'Foundations':ch[1]}</h2><button class="textbtn" onclick="navigate('learn')">Course ${icon('arrow')}</button></div>${stageRail(id)}${first?'<button class="textbtn flow-first-help" onclick="showStudyStartGuide()">How to study your first card '+icon('chevron')+'</button>':''}</section>
 <div class="flow-overview"><section class="flow-daily"><div><strong>Today</strong><span>${today} / ${goal} reviews</span></div><div class="progress" role="progressbar" aria-label="Daily review goal" aria-valuemin="0" aria-valuemax="${goal}" aria-valuenow="${Math.min(today,goal)}"><span style="width:${percent}%"></span></div><small>${today>=goal?'Daily goal reached':goal-today+' to your goal'}</small></section><section class="flow-course-summary"><div><strong>Chinese 1</strong><span>${complete} / ${courseChapters().length} chapters complete</span></div><div class="progress" role="progressbar" aria-label="Course progress" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${coursePercent()}"><span style="width:${coursePercent()}%"></span></div><small>${known} familiar characters · ${Object.keys(state.read).length} readings completed</small></section></div>
 ${miniCompanion()}<div class="flow-home-footer"><div id="flow-save-status">${flowSaveStatus()}</div><button class="textbtn" onclick="openQuickLookup()">${icon('search')} Look up a character</button><details class="quiet-details"><summary>Weekly activity</summary><div class="week">${weekMarkup()}</div></details></div></div>`;
};
let flowOpenUnit=null,flowLastFocusUnit=null;
function rememberCourseUnit(element,id){if(element.isConnected===false)return;if(element.open){flowOpenUnit=id;document.querySelectorAll('.course-unit').forEach(other=>{if(other!==element)other.open=false})}else if(flowOpenUnit===id)flowOpenUnit=null}
renderLearn=function(){const id=courseFocusId();if(flowLastFocusUnit!==id){flowOpenUnit=id;flowLastFocusUnit=id}const completed=courseChapters().filter(c=>courseState(c[0]).complete).length;$('view').innerHTML=`<div class="flow-course"><div class="heading"><div><div class="eyebrow">${esc(currentCourse().name)}</div><h1>Your course</h1><p class="muted">Learn → Check → Read</p></div><span class="badge">${completed} / ${courseChapters().length} complete</span></div><div class="flow-course-intro"><span>Follow the highlighted chapter, or choose any chapter for your class.</span><button class="textbtn" onclick="openChapter('${id}')">Current chapter ${icon('arrow')}</button></div><div class="course-roadmap">${courseChapters().map(([chapterId,title,sub,glyph],i)=>{const p=courseState(chapterId),active=chapterId===id,next=courseNext(chapterId);return `<details class="course-unit ${active?'is-current':''} ${p.complete?'is-complete':''}" ${flowOpenUnit===chapterId?'open':''} ontoggle="rememberCourseUnit(this,'${chapterId}')"><summary><span class="course-marker">${p.complete?icon('check'):chapterId==='I'?'○':chapterId}</span><span class="course-unit-label"><strong>${esc(title)}</strong><small>${chapterId==='I'?'Foundations':chapterId===id?'Current chapter':lessonLabel(chapterId)} · ${p.practiced} / ${p.total} characters</small></span><span class="course-unit-status">${p.complete?'Complete':active?'Continue':p.practiced?'In progress':''}</span>${icon('chevron')}</summary><div class="course-unit-body"><p class="small muted">${esc(COURSE_OUTCOMES[chapterId]||sub)}</p>${stageRail(chapterId)}<div class="course-unit-actions"><button class="btn ${active?'primary':''}" onclick="${next.action}">${esc(next.label)} ${icon('arrow')}</button><button class="textbtn" onclick="openChapter('${chapterId}')">Explore chapter</button></div></div></details>`}).join('')}</div><button class="textbtn course-help" onclick="showCourseGuide()">How course progress works ${icon('chevron')}</button></div>`};
const SENTENCE_PATTERNS={
 I:{title:'Build a familiar word',formula:'Shape + shape → word',note:'Recognize each character, then read the pair as one word. The word’s meaning depends on how the characters are used together.',examples:[['木门','mù mén','wooden door'],['大门','dà mén','big gate; main entrance']]},
 '1':{title:'Say who someone is',formula:'Person + 是 + noun',note:'Use 是 to identify someone. In these sentences, the part after 是 names a role.',examples:[['我是学生。','Wǒ shì xuésheng.','I am a student.'],['你是老师。','Nǐ shì lǎoshī.','You are a teacher.']]},
 '2':{title:'Say what someone has',formula:'Person + 有 + thing',note:'有 introduces something someone has. A number and counting word can come before the thing.',examples:[['我有一个姐姐。','Wǒ yǒu yí ge jiějie.','I have an older sister.'],['他有两个弟弟。','Tā yǒu liǎng ge dìdi.','He has two younger brothers.']]},
 '3':{title:'Put the time before the action',formula:'Person + time + action',note:'Chinese time phrases usually go before the main action. You can also put the time at the beginning of the sentence.',examples:[['我今天晚上吃饭。','Wǒ jīntiān wǎnshang chī fàn.','I will eat tonight.'],['我们明天七点见。','Wǒmen míngtiān qī diǎn jiàn.','We will meet at seven tomorrow.']]},
 '4':{title:'Say what you enjoy doing',formula:'Person + 喜欢 + action',note:'喜欢 can be followed by an activity. Keep the activity together when reading.',examples:[['我喜欢看书。','Wǒ xǐhuan kàn shū.','I like reading.'],['她喜欢听音乐。','Tā xǐhuan tīng yīnyuè.','She likes listening to music.']]},
 '5':{title:'Invite someone politely',formula:'请 + action',note:'请 before an action can make a request or invitation polite.',examples:[['请进。','Qǐng jìn.','Please come in.'],['请坐。','Qǐng zuò.','Please sit down.']]},
 '6':{title:'Talk about what is possible',formula:'Person + 可以 + action',note:'可以 before an action often expresses permission or possibility. Here it describes being able to come at a certain time.',examples:[['我明天可以来。','Wǒ míngtiān kěyǐ lái.','I can come tomorrow.'],['你明天可以来吗？','Nǐ míngtiān kěyǐ lái ma?','Can you come tomorrow?']]},
 '7':{title:'Describe how an action goes',formula:'Action + 得 + description',note:'得 connects an action to a description of how it is done. This 得 is read lightly as de.',examples:[['他说得很好。','Tā shuō de hěn hǎo.','He speaks very well.'],['你写得很好。','Nǐ xiě de hěn hǎo.','You write very well.']]},
 '8':{title:'Describe an action happening now',formula:'Person + 在 + action',note:'在 before an action can show that it is in progress. Here it means doing something, rather than being at a place.',examples:[['我在写日记。','Wǒ zài xiě rìjì.','I am writing in my diary.'],['他在洗澡。','Tā zài xǐ zǎo.','He is taking a shower.']]},
 '9':{title:'Say something is too big or small',formula:'Thing + 太 + description + 了',note:'太…了 often expresses “too…” in context. Here the clothes do not fit because of their size.',examples:[['这件衣服太大了。','Zhè jiàn yīfu tài dà le.','This item of clothing is too big.'],['这件衣服太小了。','Zhè jiàn yīfu tài xiǎo le.','This item of clothing is too small.']]},
 '10':{title:'Ask how someone travels',formula:'Person + 怎么 + action?',note:'怎么 before an action asks how it happens. In the answer, name the way you travel before the destination.',examples:[['你怎么去学校？','Nǐ zěnme qù xuéxiào?','How do you get to school?'],['我坐地铁去学校。','Wǒ zuò dìtiě qù xuéxiào.','I take the subway to school.']]}
};
function openSentencePattern(id){const p=(courseUsageNote(id)||SENTENCE_PATTERNS[id]);if(!p)return;studyModal(`<div class="eyebrow">${id==='I'?'Foundations · word building':lessonLabel(id)+' · sentence pattern'}</div><h2>${esc(p.title)}</h2><div class="pattern-formula">${esc(p.formula)}</div><p>${esc(p.note)}</p><div class="study-pane pattern-examples">${p.examples.map(([zh,py,en])=>`<section><div class="pattern-sentence" lang="zh">${esc(text(zh))}</div><p class="small example-pinyin">${esc(py)}</p><p>${esc(en)}</p><button class="btn" onclick="speak('${zh}')">${icon('sound')} Listen</button></section>`).join('')}</div><p class="small muted">Tap a character to explore it. These notes are optional; they do not add a course requirement.</p>`);activateStudyCharacters(document.querySelector('.practice-detail-modal'))}
renderChapter=function(){const id=chapter,ch=CHAPTERS.find(c=>c[0]===id),p=courseState(id),next=courseNext(id);if(!ch)return navigate('learn');$('view').innerHTML=`<div class="flow-chapter"><button class="textbtn back" onclick="navigate('learn')">${icon('back')} Course</button><div class="heading"><div><div class="eyebrow">${id==='I'?'Foundations':lessonLabel(id)}</div><h1>${esc(ch[1])}</h1><p class="muted">${p.practiced} / ${p.total} characters practiced</p></div><button class="iconbtn" onclick="openResults('${id}')" title="Chapter results" aria-label="Chapter results">${icon('layers')}</button></div>${stageRail(id,false)}<div class="tabs flow-chapter-tabs" role="tablist" aria-label="Chapter activities">${[['cards','Learn'],['quiz','Check'],['read','Read'],['write','Write']].map(([key,label])=>`<button class="${tab===key?'active':''}" role="tab" aria-selected="${tab===key}" data-chapter-tab="${key}" tabindex="${tab===key?0:-1}" onclick="chapterTab('${key}')">${label}${key==='write'?'<span class="optional-tab">Optional</span>':''}</button>`).join('')}</div>${tab==='cards'?`<section class="panel flow-launch"><div><h2>${p.practiced<p.total?'Learn the next set':'Practice this chapter'}</h2><p class="small muted">${nextBatchSize(id)} characters · read, reveal, rate</p></div><div class="row"><button class="btn primary" onclick="startSession('learn','${id}')">Start practice ${icon('arrow')}</button>${sessionLengthControl()}</div></section><details class="flow-character-browser"><summary><span>Browse all ${p.total} characters</span>${icon('chevron')}</summary><div class="word-grid">${uniqueCards(id).map(c=>`<button class="word-card" onclick="showCharacter('${c.character}')"><div class="char">${han(c)}</div><div class="sound">${esc(c.pinyin)}</div><small>${esc(c.meaning)}</small></button>`).join('')}</div></details><details class="quiet-details flow-chapter-options"><summary>Other practice options</summary><div class="row"><button class="btn" onclick="startSession('weak','${id}')">Needs practice</button><button class="btn" onclick="startSession('all','${id}')">Full chapter</button></div></details>`:tab==='quiz'?`<section class="panel flow-launch"><div><h2>Check your recall</h2><p class="small muted">${p.total} questions · 80% without hints to pass</p>${state.quizzes.chapters[id]?`<p class="small muted">Last score: ${state.quizzes.chapters[id].score}% · ${p.quiz?'Passed':'Try again after a review'}</p>`:''}</div><button class="btn primary" onclick="startQuiz('chapter','${id}')">${p.quiz?'Retake quiz':'Start quiz'} ${icon('arrow')}</button></section>`:tab==='read'?`<button class="pattern-peek" onclick="openSentencePattern('${id}')"><span class="pattern-peek-icon">${icon('layers')}</span><span><strong>${id==='I'?'Word building':'One useful sentence pattern'}</strong><small>${esc((courseUsageNote(id)||SENTENCE_PATTERNS[id])?.title||'Reading notes')}</small></span>${icon('chevron')}</button>${storyCards(id)}`:`<section class="panel flow-launch"><div><h2>Write from memory</h2><p class="small muted">Optional practice · draw, type, or use paper</p></div><button class="btn primary" onclick="startWriting('${id}')">Start writing ${icon('arrow')}</button></section>`}</div>`};
function renderTools(){$('view').innerHTML=`<div class="flow-tools"><div class="heading"><div><h1>Study tools</h1><p class="muted">Choose what you need.</p></div></div><div class="flow-tool-grid">${[['read','Reading','Passages organized by chapter','read'],['write','Writing','Draw, type, or practice on paper','write'],['search','Dictionary','Characters, sounds, and components','search']].map(([id,title,description,glyph])=>`<button class="flow-tool" onclick="navigate('${id}')"><span>${icon(glyph)}</span><strong>${title}</strong><small>${description}</small>${icon('arrow')}</button>`).join('')}${state.companion.enabled?`<button class="flow-tool" onclick="openJourney()"><span>${icon('flame')}</span><strong>Companion</strong><small>Training, badges, and course challenges</small>${icon('arrow')}</button>`:''}</div><div class="flow-tools-footer"><button class="btn" onclick="openQuickLookup()">${icon('search')} Quick lookup <kbd>Ctrl / ⌘ K</kbd></button><button class="textbtn" onclick="showStudyStartGuide()">How to study</button><button class="textbtn" onclick="navigate('settings')">Settings</button></div></div>`}
const flowChrome=chrome;
chrome=function(){flowChrome();const active=['chapter','results'].includes(currentView)?'learn':currentView==='session'?(session?.mode==='review'||session?.mode==='missed'?'review':'learn'):currentView==='quiz'?(quizSession?.kind==='chapter'?'learn':'review'):['reader','read','write','search','components','journey','tools'].includes(currentView)?'tools':currentView==='confusions'?'review':currentView;const primary=[['home','Home'],['learn','Course'],['review','Review'],['tools','Tools']];$('mobile-nav').innerHTML=primary.map(([id,label])=>`<button type="button" class="${active===id?'active':''}" onclick="navigate('${id}')" ${active===id?'aria-current="page"':''}>${icon(id)}<span>${label}</span></button>`).join('');const nav=[['home','Home'],['learn','Course'],['review','Review']],library=[['read','Reading'],['write','Writing'],['search','Dictionary'],['listening','Listening'],['confusions','Similar characters']];const resourceView=currentView==='quiz'&&quizSession?.skill==='listening'?'listening':currentView==='reader'?'read':currentView==='components'?'search':currentView;const links=items=>items.map(([id,label])=>`<button type="button" class="${resourceView===id||id==='learn'&&active==='learn'||id==='review'&&active==='review'?'active':''}" onclick="${id==='listening'?'startListeningPractice()':id==='confusions'?'openConfusions()':`navigate('${id}')`}" ${resourceView===id||id==='learn'&&active==='learn'||id==='review'&&active==='review'?'aria-current="page"':''}>${icon(id)}<span>${label}</span></button>`).join('');$('nav').innerHTML=links(nav)+'<span class="nav-section-label">Tools</span>'+links(library)+(state.companion.enabled?`<button class="${currentView==='journey'?'active':''}" onclick="openJourney()">${icon('flame')}<span>Companion</span></button>`:'');if(currentView==='learn')$('crumb').textContent='Your course';if(currentView==='tools')$('crumb').textContent='Study tools';document.body.classList.toggle('flow-tools-page',currentView==='tools');syncFlowMotion()};
renderReview=function(){const due=dueCards().length,studied=uniqueCards().filter(c=>state.cards[c.character]?.seen).length,known=uniqueCards().filter(familiar).length,missed=Object.keys(state.quizMisses).filter(c=>cardByChar[c]).sort((a,b)=>state.quizMisses[b]-state.quizMisses[a]),weak=uniqueCards().filter(c=>state.cards[c.character]&&!familiar(c)).length;$('view').innerHTML=`<div class="flow-review"><div class="heading"><div><h1>Review</h1></div></div><section class="flow-review-main"><span class="flow-review-icon">${icon(due?'clock':'check')}</span><div><span class="eyebrow">${due?'Due now':studied?'Keep it familiar':'Start with characters'}</span><h2>${due?due+' characters ready for review':studied?'No reviews due':'Learn a few characters first'}</h2><p>${due?'Bring these back to mind before learning more.':studied?'You can revisit difficult cards or check your recall.':'Your review list builds as you practice.'}</p><button class="btn primary" onclick="${due?"startSession('review')":studied?'startReviewPrep()':courseNext().action}">${due?'Review '+Math.min(due,state.settings.sessionLength)+' characters':studied?'Practice studied characters':'Start learning'} ${icon('arrow')}</button></div></section><div class="flow-review-grid">${missed.length?`<section class="panel"><h2>Missed answers</h2><p class="small muted">${missed.length} characters from quizzes</p><button class="btn" onclick="startSession('all',null,'${missed.slice(0,state.settings.sessionLength).join('')}'.split(''))">Revisit missed characters</button></section>`:''}<section class="panel"><h2>Recall quiz</h2><p class="small muted">${known} familiar characters</p><button class="btn" ${known?'':'disabled'} onclick="startQuiz('review')">Quiz familiar characters</button></section><section class="panel"><h2>Similar shapes</h2><p class="small muted">Notice the differences before a quiz.</p><button class="btn" onclick="openConfusions()">Compare characters</button></section></div><details class="panel quiet-details"><summary>Saved cards &amp; review preferences</summary><div class="row">${sessionLengthControl()}<button class="btn" onclick="startDailyPractice()">Daily mix</button><button class="btn" ${studied?'':'disabled'} onclick="startReviewPrep()">Preview studied cards</button><button class="btn" ${weak?'':'disabled'} onclick="startSession('weak')">Needs practice (${weak})</button><button class="btn" ${state.bookmarks.length?'':'disabled'} onclick="startSession('saved')">Saved (${state.bookmarks.length})</button></div></details></div>`};
let flowWritingSetup=null;
function captureWritingSetup(){if(!flowWritingSetup)flowWritingSetup={id:courseFocusId(),kind:'characters',prompt:'pinyin'};if(currentView==='write'&&!writeSession){flowWritingSetup.id=$('write-chapter')?.value||flowWritingSetup.id;flowWritingSetup.kind=$('write-kind')?.value||flowWritingSetup.kind;flowWritingSetup.prompt=$('write-prompt')?.value||flowWritingSetup.prompt}return flowWritingSetup}
function chooseWritingMethod(method){captureWritingSetup();setSetting('writingMethod',method);renderWrite()}
renderWrite=function(){if(writeSession)return renderWritingSession();const setup=flowWritingSetup||{id:courseFocusId(),kind:'characters',prompt:'pinyin'};flowWritingSetup=setup;$('view').innerHTML=`<div class="flow-writing"><div class="heading"><div><h1>Writing</h1><p class="muted">Write from memory, then compare.</p></div></div><section class="panel writing-setup"><label class="flow-form-label">Chapter<select id="write-chapter" onchange="captureWritingSetup()">${courseChapters().map(c=>`<option value="${c[0]}" ${c[0]===setup.id?'selected':''}>${esc(c[1])}</option>`).join('')}</select></label><span class="flow-form-label">Writing method</span><div class="flow-writing-methods">${[['draw','Draw','Use a finger, stylus, or mouse'],['type','Type','Enter characters with a Chinese keyboard'],['paper','Paper','Write outside the app']].map(([key,label,detail])=>`<button class="${state.settings.writingMethod===key?'active':''}" aria-pressed="${state.settings.writingMethod===key}" onclick="chooseWritingMethod('${key}')">${icon(key==='draw'?'write':key==='type'?'keyboard':'read')}<strong>${label}</strong><small>${detail}</small></button>`).join('')}</div><details class="quiet-details flow-writing-options"><summary>More options</summary><div class="form-grid"><label>Practice<select id="write-kind" onchange="captureWritingSetup()">${[['characters','Characters'],['words','Useful words']].map(([key,label])=>`<option value="${key}" ${key===setup.kind?'selected':''}>${label}</option>`).join('')}</select></label><label>Prompt<select id="write-prompt" onchange="captureWritingSetup()">${[['pinyin','Pinyin & meaning'],['meaning','Meaning only']].map(([key,label])=>`<option value="${key}" ${key===setup.prompt?'selected':''}>${label}</option>`).join('')}</select></label>${sessionLengthControl()}</div></details><button class="btn primary flow-writing-start" onclick="captureWritingSetup();startWriting(flowWritingSetup.id,flowWritingSetup.kind,flowWritingSetup.prompt)">Start writing ${icon('arrow')}</button><p class="small muted">Reveal the model, then mark your answer yourself.</p></section></div>`};
const flowReadRender=renderRead;
renderRead=function(){flowReadRender();const h=$('view').querySelector('.heading h1');if(h)h.textContent='Reading';$('view').querySelector('.heading')?.insertAdjacentHTML('afterend',`<div class="flow-reading-current"><span>Current chapter · ${esc(CHAPTERS.find(c=>c[0]===courseFocusId())[1])}</span><button class="textbtn" onclick="openChapter('${courseFocusId()}');chapterTab('read')">Open chapter readings ${icon('arrow')}</button></div>`)};
function showStudyStartGuide(){studyModal(`<div class="eyebrow">First session</div><h2>Read. Reveal. Rate.</h2><div class="flow-help-steps"><section><span>1</span><div><strong>Try reading the character</strong><p>Say it, or recall its meaning. Use a hint if you need one.</p></div></section><section><span>2</span><div><strong>Reveal and listen</strong><p>Check the pinyin and meaning. Explore the sound guide or picture cue when useful.</p></div></section><section><span>3</span><div><strong>Rate what you remembered</strong><p>Again = could not read it. Almost = hesitation or help. Got it = read it before revealing.</p></div></section></div><button class="btn" onclick="showPracticeShortcuts()">Keyboard controls &amp; review timing</button>`)}
function showCourseGuide(){studyModal(`<div class="eyebrow">Chinese 1</div><h2>Your path through a chapter</h2><div class="flow-help-steps"><section><span>1</span><div><strong>Learn the characters</strong><p>Work through small sets. You can revisit them whenever you need.</p></div></section><section><span>2</span><div><strong>Check your recall</strong><p>Pass the chapter quiz with 80% without hints. Missed answers become review suggestions.</p></div></section><section><span>3</span><div><strong>Read a passage</strong><p>Complete a reading quiz to finish the chapter path. Extra readings and writing are optional.</p></div></section></div><p class="small muted">Choose any chapter to follow your class. Reviews keep earlier characters in your daily practice. Sentence-pattern notes help with reading; they are optional.</p>`)}
const flowNextStep=nextStep;
nextStep=function(id){if(!id)return {label:'Continue learning',action:courseNext().action};const next=courseNext(id);return {label:courseState(id).stage===0?'Next session':next.label,action:next.action}};
const flowCompletionRender=renderPracticeCompletion;
renderPracticeCompletion=function(s,kind){flowCompletionRender(s,kind);const panel=$('view').querySelector('.clean-completion');panel?.classList.add('flow-completion');panel?.insertAdjacentHTML('afterbegin',`<span class="flow-completion-seal">${icon('check')}</span>`);const main=panel?.querySelector('.continue-btn');if(main&&practiceRetryTargets(s).length)main.innerHTML='Revisit '+practiceRetryTargets(s).length+' tricky characters '+icon('arrow');const heading=panel?.querySelector('h1');if(heading)heading.textContent=kind==='write'?'Writing complete':'Session complete'};
let flowLookupQuery='';
function quickLookupCards(query){query=query.trim();const q=normalize(query),numbered=/^[a-züv:]+[1-5]$/i.test(query)?pinyinSound(query):null;if(!q)return uniqueCards().filter(c=>state.bookmarks.includes(c.character)).slice(0,8);return uniqueCards().filter(c=>numbered?characterSounds(c).some(sound=>sound.base===numbered.base&&sound.tone===numbered.tone):normalize([c.character,c.traditional,c.pinyin,c.meaning].join(' ')).includes(q)).sort((a,b)=>Number(b.character===query||b.traditional===query)-Number(a.character===query||a.traditional===query)||Number(b.pinyin.toLowerCase()===query.toLowerCase())-Number(a.pinyin.toLowerCase()===query.toLowerCase())||Number(normalize(b.pinyin)===q)-Number(normalize(a.pinyin)===q)).slice(0,10)}
function quickLookupMarkup(query){const cards=quickLookupCards(query);return cards.length?`<div class="flow-lookup-list">${cards.map(c=>`<button class="flow-lookup-hit" onclick="openStudyCharacter('${c.character}')"><span lang="zh">${esc(han(c))}</span><span><strong>${esc(c.pinyin)}</strong><small>${esc(c.meaning)}</small></span>${icon('chevron')}</button>`).join('')}</div>`:`<p class="small muted">${query?'No matches. Try a character, pinyin, or meaning.':'Search a character, pinyin, or meaning. Saved characters appear here.'}</p>`}
function openQuickLookup(){if(onboardingStep)return;if($('overlay').innerHTML.includes('id="flow-lookup-input"')){$('flow-lookup-input')?.focus({preventScroll:true});$('flow-lookup-input')?.select?.();return}flowLookupQuery='';if(currentView==='session'&&session&&!session.revealed)session.usedHint=true;if(currentView==='write'&&writeSession&&!writeSession.revealed)writeSession.usedHint=true;if(currentView==='quiz'&&quizSession&&!quizSession.done){const q=quizSession.questions[quizSession.pos];if(q&&(quizSession.kind==='league'?q.chosen:q.choice)===null)q.usedHint=true}checkpointCurrent();studyModal(`<h2>Quick lookup</h2><label class="flow-lookup-search"><span class="label">Character, pinyin, or meaning</span><input class="input full" id="flow-lookup-input" type="search" autocomplete="off" autocapitalize="none" spellcheck="false" placeholder="你, ni, you…" oninput="updateQuickLookup(this.value)"></label><div id="flow-lookup-results">${quickLookupMarkup('')}</div><p class="small muted">Lookup before answering counts as help in character practice and quizzes.</p>`);$('flow-lookup-input')?.focus({preventScroll:true})}
const flowCloseModal=closeModal;
closeModal=function(){flowCloseModal();if($('overlay').innerHTML.includes('id="flow-lookup-input"'))$('flow-lookup-input')?.focus({preventScroll:true})};
function updateQuickLookup(value){flowLookupQuery=value;$('flow-lookup-input')?.setAttribute('value',value);$('flow-lookup-results').innerHTML=quickLookupMarkup(value)}
function syncFlowMotion(){document.body.classList.toggle('flow-reduce-motion',state.settings.animations===false)}
function flowMotionAllowed(){return state.settings.animations!==false&&!matchMedia('(prefers-reduced-motion: reduce)').matches}
function flowEnterPage(){if(!flowMotionAllowed())return;const view=$('view');view.classList.remove('flow-enter');void view.offsetWidth;view.classList.add('flow-enter')}
function focusFlowPage(){const heading=$('view').querySelector('h1');heading?.setAttribute('tabindex','-1');heading?.focus({preventScroll:true})}
function flowNextCard(previous){if(!flowMotionAllowed())return;const card=$('view').querySelector('.focus-card');card?.classList.add('flow-card-next');const bar=$('view').querySelector('.focus-session>.progress>span');if(bar&&Number.isFinite(previous)){const next=bar.style.width;bar.style.transition='none';bar.style.width=previous+'%';const later=()=>{bar.style.transition='width .22s ease';bar.style.width=next};if(typeof requestAnimationFrame==='function')requestAnimationFrame(()=>requestAnimationFrame(later));else later()}}
const flowNavigate=navigate,flowOpenChapter=openChapter,flowRestore=restorePage,flowStartSession=startSession,flowStartWriting=startWriting,flowStartQuiz=startQuiz;
navigate=function(view){const before=currentView;flowNavigate(view);if(currentView!==before){flowEnterPage();focusFlowPage()}};
openChapter=function(id){flowOpenChapter(id);flowEnterPage();focusFlowPage()};
restorePage=function(page){flowRestore(page);flowEnterPage();focusFlowPage()};
startSession=function(...args){flowStartSession(...args);flowEnterPage()};
startWriting=function(...args){flowStartWriting(...args);flowEnterPage()};
startQuiz=function(...args){flowStartQuiz(...args);flowEnterPage()};
const flowOpenReading=openReading,flowOpenJourney=openJourney;
openReading=function(...args){flowOpenReading(...args);flowEnterPage();focusFlowPage()};
openJourney=function(...args){const before=currentView;flowOpenJourney(...args);if(currentView!==before){flowEnterPage();focusFlowPage()}};
const flowReveal=reveal,flowRevealWriting=revealWriting;
reveal=function(){flowReveal();if(session?.revealed)$('view').querySelector('.focus-actions .btn.primary')?.focus({preventScroll:true})};
revealWriting=function(){flowRevealWriting();if(writeSession?.revealed)$('view').querySelector('.focus-actions .btn.primary')?.focus({preventScroll:true})};
const flowRate=rate,flowWritingRate=rateWriting,flowQuizNext=quizNext,flowLeagueNext=leagueNext;
rate=function(value){const s=session,before=s?.pos,percent=s?s.pos/s.queue.length*100:0,valid=s&&!s.done&&s.revealed&&['again','hard','good'].includes(value);if(valid&&!state.settings.studyCoachSeen)state.settings.studyCoachSeen=true;flowRate(value);if(valid&&s.pos!==before){save();if(!s.done)flowNextCard(percent)}};
rateWriting=function(value){const s=writeSession,before=s?.pos,percent=s?s.pos/s.queue.length*100:0;flowWritingRate(value);if(s&&s.pos!==before&&!s.done)flowNextCard(percent)};
quizNext=function(){const s=quizSession,before=s?.pos,percent=s?s.pos/s.questions.length*100:0;flowQuizNext();if(s&&s.pos!==before&&!s.done){flowNextCard(percent);$('view').querySelector('.quiz-choice')?.focus({preventScroll:true})}};
leagueNext=function(){const s=quizSession,before=s?.pos,percent=s?s.pos/s.questions.length*100:0;flowLeagueNext();if(s&&s.pos!==before&&!s.done)flowNextCard(percent)};
const flowSessionRender=renderSession;
renderSession=function(){flowSessionRender();if(session&&!session.done&&!state.settings.studyCoachSeen){$('view').querySelector('.focus-card')?.insertAdjacentHTML('beforeend',`<p class="flow-study-coach">${session.revealed?'Needed a hint? Choose <strong>Almost</strong>.':'Try reading first. Tap <strong>Hint</strong> if you need a clue.'}</p>`)}};
const flowSetSetting=setSetting,flowSettingsRender=renderSettings;
setSetting=function(key,value){if(['animations','studyCoachSeen'].includes(key)&&typeof value!=='boolean')return;flowSetSetting(key,value);syncFlowMotion()};
renderSettings=function(){flowSettingsRender();$('view').querySelector('.clean-settings')?.insertAdjacentHTML('afterend',`<section class="panel flow-motion-settings"><div class="setting-row"><div><strong>Gentle animations</strong><p>Also respects your device’s reduced-motion preference.</p></div><input type="checkbox" role="switch" aria-label="Gentle animations" ${state.settings.animations?'checked':''} onchange="setSetting('animations',this.checked)"></div><button class="textbtn" onclick="showStudyStartGuide()">First-session guide</button></section>`)};
let flowSettingsOpen=new Set(['appearance']);
function rememberSettingsPanel(element,id){if(element.isConnected===false)return;if(element.open)flowSettingsOpen.add(id);else flowSettingsOpen.delete(id)}
function flowSettingsPanel(id,title,body){return `<details class="panel settings-accordion ${id==='audio'?'audio-speed-setting':''}" data-settings-panel="${id}" ${flowSettingsOpen.has(id)?'open':''} ontoggle="rememberSettingsPanel(this,'${id}')"><summary><strong>${title}</strong>${icon('chevron')}</summary><div class="settings-accordion-body">${body}</div></details>`}
renderSettings=function(){
 const select=(key,choices,number=false)=>`<select aria-label="${esc(key==='audioRate'?'Audio speed':key==='size'?'Reading text size':key)}" onchange="setSetting('${key}',${number?'Number(this.value)':'this.value'})">${choices.map(([value,label])=>`<option value="${value}" ${state.settings[key]===value?'selected':''}>${esc(label)}</option>`).join('')}</select>`;
 const row=(label,control,note='')=>`<div class="setting-row"><div><strong>${label}</strong>${note?`<p>${note}</p>`:''}</div>${control}</div>`;
 const toggle=(key,label)=>`<label class="flow-switch"><input type="checkbox" role="switch" aria-label="${label}" ${state.settings[key]?'checked':''} onchange="setSetting('${key}',this.checked)"></label>`;
 const appearance=`<div class="palette-section"><span class="label">Color palette</span><div class="palette-options">${Object.entries(PALETTES).map(([id,p])=>`<button class="palette-choice ${state.settings.palette===id?'selected':''}" aria-pressed="${state.settings.palette===id}" onclick="setSetting('palette','${id}');renderSettings()"><span class="palette-dot" style="background:${p.brandPale};border-color:${p.brandDark}"></span><span>${p.name}</span></button>`).join('')}</div></div>${row('Theme',select('theme',[['system','System'],['light','Light'],['dark','Dark']]))}${row('Reading text size',select('size',[[23,'Small'],[27,'Medium'],[32,'Large']],true))}${row('Gentle animations',toggle('animations','Gentle animations'),'Also respects reduced motion on your device.')}`;
 const study=`${row('Characters',select('script',[['simplified','Simplified'],['traditional','Traditional']]))}${row('Daily goal',select('goal',[10,20,30,50].map(n=>[n,n+' reviews']),true))}${row('Session size',select('sessionLength',[5,10,20].map(n=>[n,n+' items']),true))}${row('Writing method',select('writingMethod',[['draw','Draw'],['type','Type'],['paper','Paper']]))}${row('Visual memory cues',toggle('visualMemory','Visual memory cues'))}${row('Compact explanations',toggle('compactExplanations','Compact explanations'))}${row('Expand usage details',toggle('detailedExamples','Detailed examples'))}`;
 const audio=`${row('Speech speed',select('audioRate',[[.65,'Slower'],[.8,'Study pace'],[1,'Normal']],true))}${row('Sound effects',`<div class="row"><button class="iconbtn" aria-label="Preview sound effects" title="Preview sound effects" ${state.settings.soundEffects?'':'disabled'} onclick="playStudySound('correct')">${soundEffectsIcon(false)}</button>${toggle('soundEffects','Sound effects')}</div>`)}`;
 const data=`<p class="small muted">${storageOK?'Progress is saved in this browser. Export a backup to transfer it to another device.':'Automatic saving is unavailable. Export a backup before leaving.'}</p><div class="row"><button class="btn" onclick="exportBackup()">${icon('download')} Export backup</button><button class="btn" onclick="$('backup-file').click()">Import backup</button></div><details class="quiet-details settings-reset"><summary>Reset progress</summary><p class="small muted">Keep your name, starter choice, and preferences; clear learning progress. Export a backup first if you want to keep it.</p><button class="btn danger" onclick="resetProgress()">Reset progress</button></details>`;
 const help=`<div class="row"><button class="btn" onclick="showStudyStartGuide()">First-session guide</button><button class="btn" onclick="showPracticeShortcuts()">Keyboard controls</button><button class="btn" onclick="showCourseGuide()">Course path</button></div><p class="small muted">Quick lookup: Ctrl / ⌘ K. Unfinished practice, writing, and character quizzes resume in this browser. Audio uses your device’s Chinese voice.</p><details class="quiet-details"><summary>Component data &amp; references</summary><p class="small muted">Selected structural data from <a href="https://github.com/skishore/makemeahanzi" target="_blank" rel="noopener">Make Me a Hanzi</a>, derived from Unihan and CJKlib, under <a href="https://www.gnu.org/licenses/lgpl-3.0.html" target="_blank" rel="noopener">LGPL 3 or later</a>. The app selects structural fields and adds original explanations and visual notes. Uncertain stroke groups are labeled.</p><button class="btn" onclick="exportComponents()">Download component data</button></details>`;
 $('view').innerHTML=`<div class="flow-settings"><div class="heading"><div><h1>Settings</h1></div></div><section class="panel profile-settings flow-profile"><div class="setting-row"><div><strong>Your name</strong><p>${esc(state.profile.name||'No name set')}</p></div><button class="btn" onclick="editProfileName()">Edit</button></div><div class="setting-row"><strong>Companion mode</strong><label class="flow-switch"><input type="checkbox" role="switch" aria-label="Companion mode" ${state.companion.enabled?'checked':''} onchange="setCompanionMode(this.checked)"></label></div>${state.companion.enabled?`<div class="row"><button class="textbtn" onclick="openCompanionSelection()">${starterData()?'Change starter':'Choose starter'}</button><button class="textbtn" onclick="openJourney('badges')">Badges &amp; challenges</button></div>`:''}</section><div class="flow-settings-panels">${flowSettingsPanel('appearance','Appearance',appearance)}${flowSettingsPanel('study','Study preferences',study)}${flowSettingsPanel('audio','Audio',audio)}${flowSettingsPanel('data','Saved data',data)}${flowSettingsPanel('help','Help &amp; references',help)}</div></div>`;
};

const flowSave=save;
save=function(){flowSave();const status=$('flow-save-status');if(status&&currentView==='home')status.innerHTML=flowSaveStatus()};
document.addEventListener('keydown',event=>{
 if(event.repeat||event.isComposing||event.altKey)return;
 if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();openQuickLookup();return}
 if(event.defaultPrevented)return;
 if(!$('overlay').innerHTML&&currentView==='chapter'&&event.target?.getAttribute?.('role')==='tab'&&['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();const tabs=['cards','quiz','read','write'],index=tabs.indexOf(tab),next=event.key==='Home'?0:event.key==='End'?3:(index+(event.key==='ArrowRight'?1:3))%4;chapterTab(tabs[next]);$('view').querySelector('[data-chapter-tab="'+tabs[next]+'"]')?.focus({preventScroll:true});return}
 const modal=document.querySelector('.modal[role="dialog"]');
 if(modal&&event.key==='Tab'){const controls=[...modal.querySelectorAll('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),a[href],[tabindex="0"]')].filter(node=>!node.closest('.hidden')&&(!node.getClientRects||node.getClientRects().length>0));if(controls.length){const first=controls[0],last=controls.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}return}
 if(event.target?.id==='flow-lookup-input'&&event.key==='Enter'){event.preventDefault();const c=quickLookupCards(flowLookupQuery)[0];if(c)openStudyCharacter(c.character);return}
 if(currentView!=='reader'||!activeReadingQuiz||activeReadingQuiz.done||$('overlay').innerHTML||event.ctrlKey||event.metaKey||['INPUT','TEXTAREA','SELECT'].includes(event.target?.tagName))return;
 const s=activeReadingQuiz,q=s.questions[s.pos],key=event.key.toLowerCase(),index=/^[1-4]$/.test(key)?Number(key)-1:/^[a-d]$/.test(key)?key.charCodeAt(0)-97:-1;
 if(index>=0&&q.chosen===null&&q.choices[index]){event.preventDefault();answerReadingQuiz(s.id,index);$('reading-quiz').querySelector('.btn.primary')?.focus({preventScroll:true})}else if(['enter',' '].includes(key)&&q.chosen!==null&&event.target?.tagName!=='BUTTON'){event.preventDefault();nextReadingQuiz(s.id)}
});


