function studioMemoryNote(ch,value){if(!Object.hasOwn(cardByChar,ch))return;const note=String(value).slice(0,300).trim();if(note)state.memoryNotes[ch]=note;else delete state.memoryNotes[ch];save();const status=$('memory-note-status');if(status)status.textContent=storageOK?'Saved on this device':'Not saved. Export a backup before leaving.'}
function toggleMemoryCover(){const content=$('memory-study-content'),cover=$('memory-covered'),button=$('memory-cover-button');if(!content||!cover||!button)return;const hidden=content.hidden!==true;content.hidden=hidden;cover.hidden=!hidden;button.innerHTML=icon('cover')+(hidden?' Check the shape':' Cover and recall');button.setAttribute('aria-pressed',String(hidden))}
