function playReadingParagraph(){const playback=readingPlayback;if(!playback||playback.status!=='playing'||currentView!=='reader'||activeReading!==playback.id)return;const r=READINGS.find(r=>r.id===playback.id);if(!r.lines[playback.index]){stopReadingAudio();return}syncReadAlong();speak(r.lines[playback.index][0],undefined,{kind:'reading',onStart:()=>{if(readingPlayback!==playback)return;syncReadAlong();document.querySelector('[data-reading-line="'+playback.index+'"]')?.scrollIntoView?.({block:'nearest',behavior:flowMotionAllowed()?'smooth':'instant'})},onEnd:()=>{if(readingPlayback!==playback||playback.status!=='playing')return;playback.index++;if(playback.index>=r.lines.length)stopReadingAudio(false);else playReadingParagraph()},onError:()=>{if(readingPlayback===playback)stopReadingAudio(false)}})}
