function syncReadAlong(){document.querySelectorAll('[data-reading-line]').forEach(line=>line.classList.toggle('reading-spoken',!!readingPlayback&&Number(line.dataset.readingLine)===readingPlayback.index));const playback=readingPlayback,r=playback&&READINGS.find(r=>r.id===playback.id),play=$('read-along-play'),pause=$('read-along-pause'),stop=$('read-along-stop'),status=$('read-along-status');if(play)play.innerHTML=icon(playback?'stop':'play')+(playback?' Stop':' Read along');if(pause){pause.disabled=!playback;pause.innerHTML=icon(playback?.status==='paused'?'play':'pause')+(playback?.status==='paused'?' Resume':' Pause')}if(stop)stop.disabled=!playback;if(status)status.textContent=playback?(playback.status==='paused'?'Paused · ':'')+'Paragraph '+(playback.index+1)+' / '+r.lines.length:'Mandarin audio'}
