const SAFETY_KEY=KEY+'-safety-copy';
function safetyCopyInfo(){try{const raw=JSON.parse(localStorage.getItem(SAFETY_KEY)||'null');if(!raw||raw.version!==1||!Number.isFinite(raw.at)||!raw.state)return null;return {at:raw.at,reason:raw.reason,state:validateState(raw.state)}}catch{return null}}
function captureSafetyCopy(reason='Automatic',force=false){try{const previous=localStorage.getItem(KEY);if(!previous)return false;const clean=validateState(JSON.parse(previous));if(!Object.keys(clean.cards).length&&!Object.keys(clean.read).length&&!Object.keys(clean.memoryNotes||{}).length)return false;const existing=safetyCopyInfo();if(!force&&existing&&dayKey(new Date(existing.at))===dayKey())return false;localStorage.setItem(SAFETY_KEY,JSON.stringify({version:1,at:Date.now(),reason,state:clean}));return true}catch{return false}}
const studioSave=save;
save=function(){captureSafetyCopy();studioSave()};
function restoreSafetyCopy(){const copy=safetyCopyInfo();if(!copy)return toast('No safety copy is available yet.');if(!confirm('Restore the saved safety copy? Current progress will be replaced. Export your current progress first if you want to keep it.'))return;state=copy.state;adoptCourseState();save();theme();navigate('home');toast('Safety copy restored.')}
