/* A permanent collection, one active partner, and independent training progress. */
function activeCompanionProfile(){const c=state.companion;c.roster??={};if(c.starter&&!c.roster[c.starter]&&STARTERS.some(s=>s.id===c.starter)){c.roster[c.starter]={xp:c.xp,stage:c.stage,reviewDays:[...c.reviewDays],joinedAt:0};c.originalStarter??=c.starter}return c.starter&&c.roster[c.starter]||null}
function syncActiveCompanion(){const c=state.companion,p=activeCompanionProfile();if(!p)return;p.xp=c.xp;p.stage=c.stage;p.reviewDays=[...c.reviewDays];}
function collectionCapacity(){const badges=COURSE_LEAGUES.reduce((n,l)=>n+badgeCount(l),0);return badges>=3?3:badges>=1?2:1}
function companionOwned(id){return !!state.companion.roster?.[id]}
function canAdoptCompanion(id){return STARTERS.some(s=>s.id===id)&&!companionOwned(id)&&Object.keys(state.companion.roster||{}).length<collectionCapacity()}
function activateCompanion(id){const c=state.companion;if(!companionOwned(id)||id===c.starter)return;syncActiveCompanion();const profile=c.roster[id];c.starter=id;c.xp=profile.xp;c.stage=profile.stage;c.reviewDays=[...profile.reviewDays];c.enabled=true;studioFeedback=null;studyCompanionHidden=false;reconcileCompanion();save();closeModal();chrome();refreshCompanionPage();toast(STARTERS.find(s=>s.id===id).name+' is now active. Your other companions keep their progress.')}
function adoptCompanion(id){if(!canAdoptCompanion(id))return;state.companion.roster[id]={xp:0,stage:0,reviewDays:[],joinedAt:Date.now()};save();activateCompanion(id);playStudySound('milestone')}
function refreshCompanionPage(){if(currentView==='journey')renderJourney();else if(currentView==='settings')renderSettings();else if(currentView==='home')renderHome();else if(currentView==='session')renderSession();else if(currentView==='write'&&writeSession)renderWritingSession();else if(currentView==='quiz')renderQuiz()}
function collectionMarkup(modal=false){const c=state.companion,badges=COURSE_LEAGUES.reduce((n,l)=>n+badgeCount(l),0),capacity=collectionCapacity();return `<section class="companion-collection ${modal?'collection-modal':''}"><div class="collection-heading"><div><span class="eyebrow">${Object.keys(c.roster||{}).length} / 3 companions</span><h2>Your companions</h2></div>${modal?`<button class="iconbtn" onclick="closeModal()" aria-label="Close companion collection">${icon('close')}</button>`:''}</div><p class="collection-note">One active companion earns XP. Each keeps its own level and evolution. Badges belong to you.</p><div class="collection-grid">${STARTERS.map(s=>{const profile=c.roster?.[s.id],active=c.starter===s.id,available=canAdoptCompanion(s.id),level=profile?companionLevel(profile.xp):1,base=xpAtLevel(level),next=xpAtLevel(level+1),pct=profile?Math.min(100,(profile.xp-base)/(next-base)*100):0;return `<article class="collection-card ${active?'active-companion':''} ${!profile&&!available?'collection-locked':''}" style="--partner-color:${s.color}"><div class="collection-card-art">${companionArt(s.id,profile?.stage||0)}</div><div class="collection-card-label"><strong>${esc(profile?s.forms[profile.stage]:s.name)}</strong><span>${active?'Active':profile?'Resting':available?'Ready to join':'Not collected'}${c.originalStarter===s.id?' · First companion':''}</span></div>${profile?`<p class="collection-level">Level ${level} · ${profile.xp-base} / ${next-base} XP</p><div class="progress" role="progressbar" aria-label="${esc(s.name)} level progress" aria-valuemin="0" aria-valuemax="${next-base}" aria-valuenow="${profile.xp-base}"><span style="width:${pct}%"></span></div><button class="btn ${active?'soft':''}" ${active?'disabled':''} onclick="activateCompanion('${s.id}')">${active?'Active companion':'Make active'}</button>`:`<p class="collection-level">${available?'Starts at level 1. Your first companion stays.':capacity===1?'Earn your first badge to invite another.':'Earn three badges to collect all three.'}</p><button class="btn" ${available?'':'disabled'} onclick="adoptCompanion('${s.id}')">${available?'Invite companion':capacity===1?'First badge needed':'Three badges needed'}</button>`}</article>`}).join('')}</div><details class="quiet-details collection-rules"><summary>How collection &amp; XP work</summary><p class="small">Choose one companion first. Earn any course badge to invite a second; earn three badges to invite the third. Switch freely among companions you own. Switching does not transfer XP or reset a level.</p><p class="small">Only the active companion earns new training XP. Repeat rewards and the daily XP limit are shared across your collection, so switching cannot create extra rewards for the same work. Evolution requires that companion’s level and review days, plus your shared badges.</p><p class="small">Companion mode can be hidden in Settings. Your collection and badges stay saved; an active companion continues to receive earned training XP quietly.</p></details></section>`}
const collectionStarterMarkup=starterSelectionMarkup;
starterSelectionMarkup=function(first=false){if(!first&&state.companion.starter)return collectionMarkup(true);return collectionStarterMarkup(first).replace('You can change starters later without losing progress.','Your first companion stays with you. Earn badges to collect the others, then choose which one to train.')};
