const collectionAwardXP=awardXP;
awardXP=function(key,amount){if(!activeCompanionProfile())return 0;const delta=collectionAwardXP(key,amount);syncActiveCompanion();if(delta>0){const scope=currentView==='session'?session:currentView==='write'?writeSession:currentView==='quiz'?quizSession:null;if(scope){scope.partnerXP??={};scope.partnerXP[state.companion.starter]=(scope.partnerXP[state.companion.starter]||0)+delta;const undo=undoAnswers.at(-1);if(undo?.scope===scope){undo.partnerRewards??=[];undo.partnerRewards.push({id:state.companion.starter,delta,credit:dayKey()+':'+key,day:dayKey()})}}}return delta};
