const collectionUndo=undoLastAnswer;
undoLastAnswer=function(){if(!undoAvailable())return;syncActiveCompanion();const undo=undoAnswers.at(-1),current=clone(state.companion);if(undo.companion){for(const reward of undo.partnerRewards||[]){if(current.roster[reward.id])current.roster[reward.id].xp=Math.max(0,current.roster[reward.id].xp-reward.delta);current.credits[reward.credit]=Math.max(0,(current.credits[reward.credit]||0)-reward.delta);current.dailyXP[reward.day]=Math.max(0,(current.dailyXP[reward.day]||0)-reward.delta)}if(undo.kind==='quiz')current.leagues=clone(undo.companion.leagues);const active=current.roster[current.starter];if(active){current.xp=active.xp;current.stage=active.stage;current.reviewDays=[...active.reviewDays]}undo.companion=current}collectionUndo();syncActiveCompanion();studioFeedback=null};
