function cleanBuddyCaption(mood){if(!state.settings.companionMessages||!CLEAN_REACTIONS[mood])return '';const lines={happy:['Nice recall!','You remembered.','That’s it!','Looking sharp!','Got that one!','Well remembered.'],encourage:['We can try again.','One part at a time.','Let’s revisit this.','Look for one clue.','Another try?','Keep going.'],thinking:['Let’s find a clue.','Look at the shape.','Listen, then try.','Notice the parts.'],celebrate:['Set complete!','Nice work today.','We did it!','Ready for another?']};return `<span class="clean-buddy-bubble" role="status" aria-live="polite">${lines[mood][cleanReactionIndex%lines[mood].length]}</span>`}
function cleanChooseReaction(mood){const active=currentView==='quiz'?quizSession:currentView==='write'?writeSession:session,q=currentView==='quiz'?active?.questions?.[active.pos]:null;const key=[currentView,state.companion.starter,mood,active?.pos,active?.attempts,active?.hintLevel,q?.choice,q?.chosen].join('|');if(key!==cleanReactionKey){cleanReactionKey=key;cleanReactionIndex=cleanReactionCounts[mood]||0;cleanReactionCounts[mood]=cleanReactionIndex+1}}
