function cleanSoundPane(c){return `<div class="clean-audio-row"><button class="btn primary" data-speech-text="${esc(c.character)}" onclick="speak('${c.character}')">${icon('sound')} Listen</button><button class="btn" onclick="speak('${c.character}',.65)">Slower</button></div>${characterSounds(c).map(sound=>`${SOUND_ANCHORS[sound.base]?`<p class="clean-sound-anchor">Approximate English cue: <strong>“${esc(SOUND_ANCHORS[sound.base])}”</strong></p>`:''}<details class="clean-study-section"><summary>Mouth position${characterSounds(c).length>1?' · '+esc(sound.pinyin):''}</summary><div class="sound-pieces"><section><strong>${esc(sound.start[0])}</strong><p>${esc(sound.start[1])}</p></section><section><strong>${esc(sound.end?.[0]||sound.base)}</strong><p>${esc(sound.end?.[1]||'Listen and match the vowel in one syllable.')}</p></section></div>${sound.spelling?`<p class="pronunciation-note">${esc(sound.spelling)}</p>`:''}<p class="small muted">English cues are approximate; match the Mandarin audio.</p></details><details class="clean-study-section"><summary>When tones change${characterSounds(c).length>1?' · '+esc(sound.pinyin):''}</summary><section class="pronunciation-tone">${toneDiagram(sound.tone)}<div><strong>${sound.tone?'Tone '+sound.tone+' · ':''}${TONE_GUIDE[sound.tone].name}</strong><p>${esc(TONE_GUIDE[sound.tone].instruction)}</p></div></section><p class="small">Before another third tone, a third tone usually sounds like a second tone: nǐ hǎo is spoken ní hǎo. Before other tones, it often stays low. 一 and 不 also change tone in context; written pinyin can keep the dictionary tone.</p></details>`).join('')}${CONTEXT_READINGS[c.character]?`<details class="clean-study-section"><summary>Other readings &amp; context</summary><p>${esc(CONTEXT_READINGS[c.character])}</p><p class="small muted">Isolated audio can choose a different reading. The example supplies context.</p><button class="btn" onclick="speak('${c.word}')">${icon('sound')} Hear ${esc(text(c.word))}</button></details>`:''}`}
function cleanMemoryPane(c){const note=state.memoryNotes[c.character];return `<div id="memory-study-content"><div class="memory-full">${memoryDiagram(c,{interactive:true})}</div><p class="memory-story">${esc(note||memoryCue(c))}</p></div><div id="memory-covered" class="memory-cover" hidden>${icon('picture')}<strong>Picture the character.</strong><p class="small">Where do the parts go?</p></div><div class="memory-recall-controls"><button class="btn" id="memory-cover-button" aria-pressed="false" onclick="toggleMemoryCover()">${icon('cover')} Cover and recall</button></div><details class="memory-note-editor"><summary>${icon('note')} ${note?'Edit':'Add'} your memory note</summary><label for="memory-note">Use a connection that works for you.</label><textarea id="memory-note" maxlength="300" placeholder="This shape reminds me of…" oninput="studioMemoryNote('${c.character}',this.value)">${esc(note||'')}</textarea><p id="memory-note-status" class="small muted">Included in your progress backup.</p></details><details class="clean-study-section"><summary>About this picture</summary><p class="small muted">This is a memory aid, not a claim about historical origin. Tap a part to explore its role.</p></details>`}
function cleanUsagePane(c){const e=EXAMPLE_CONTEXT[c.word],detail=exampleDetailParts(c);return e?`${e.word===c.character?'':exampleMarkup(c,true)}${detail.usage}<details class="clean-study-section"><summary>Individual character meanings</summary>${detail.glossary.replace('<div class="small muted">Individual character meanings</div>','')}</details>`:`<p class="small muted">Example: <span lang="zh">${esc(text(c.word))}</span></p>`}
function cleanStudyPane(c,tab){return tab==='sound'?cleanSoundPane(c):tab==='memory'?cleanMemoryPane(c):tab==='usage'?cleanUsagePane(c):componentMarkup(c.character)}
function openCleanStudy(ch,tab='sound'){const c=courseCard(ch)||extra[ch];if(!c)return openComponentCard(ch);cleanStudyTarget=c.character;cleanStudyTab=CLEAN_STUDY_TABS.some(t=>t[0]===tab)?tab:'sound';studyModal(`<div class="clean-study-title"><span lang="zh">${esc(han(c))}</span><div><h2>${esc(c.pinyin)}</h2><p class="small muted">${esc(c.meaning)}</p></div>${cardByChar[c.character]?`<button class="iconbtn" id="clean-detail-save" aria-label="${state.bookmarks.includes(c.character)?'Remove bookmark':'Bookmark character'}" aria-pressed="${state.bookmarks.includes(c.character)}" onclick="cleanBookmarkDetails('${c.character}')">${star(c.character)}</button>`:''}</div><div class="clean-study-tabs" role="tablist" aria-label="Study details">${CLEAN_STUDY_TABS.map(([key,label])=>`<button type="button" role="tab" data-clean-tab="${key}" id="clean-tab-${key}" aria-selected="${key===cleanStudyTab}" aria-controls="clean-study-pane" tabindex="${key===cleanStudyTab?0:-1}" onclick="selectCleanStudyTab('${key}')">${label}</button>`).join('')}</div><section id="clean-study-pane" class="study-pane" data-clean-character="${esc(c.character)}" role="tabpanel" aria-labelledby="clean-tab-${cleanStudyTab}">${cleanStudyPane(c,cleanStudyTab)}</section>${state.cards[c.character]||state.writing[c.character]?`<details class="clean-study-section"><summary>Your progress</summary><button class="btn danger" onclick="unlearn('${c.character}')">Unlearn this character</button></details>`:''}`);activateStudyCharacters(document.querySelector('.practice-detail-modal'));syncSpeechButtons()}
function selectCleanStudyTab(tab){const target=$('clean-study-pane')?.dataset.cleanCharacter||cleanStudyTarget,c=courseCard(target)||extra[target];if(!c||!CLEAN_STUDY_TABS.some(t=>t[0]===tab))return;cleanStudyTarget=c.character;cleanStudyTab=tab;const title=document.querySelector('.clean-study-title');if(title)title.hidden=false;document.querySelectorAll('[data-clean-tab]').forEach(button=>{const active=button.dataset.cleanTab===tab;button.setAttribute('aria-selected',String(active));button.tabIndex=active?0:-1});const pane=$('clean-study-pane');pane.innerHTML=cleanStudyPane(c,tab);pane.setAttribute('aria-labelledby','clean-tab-'+tab);activateStudyCharacters(document.querySelector('.practice-detail-modal'));syncSpeechButtons();$('clean-tab-'+tab)?.focus({preventScroll:true})}
