function cleanCompletionActions(s,kind){const needs=practiceRetryTargets(s),next=nextStep(s.id),chars=kind==='cards'?(s.batch||[]):[...new Set(s.queue.flatMap(w=>[...w.target]).filter(ch=>cardByChar[ch]))],reading=s.id&&READINGS.find(r=>r.lesson===s.id&&!state.read[r.id]);return `<div class="clean-completion-actions"><button class="btn primary continue-btn" onclick="${needs.length?`retryPractice(false,'${kind}')`:next.action}">${needs.length?'Revisit '+needs.length+' characters':esc(next.label)} ${icon('arrow')}</button><div class="clean-secondary-actions">${needs.length?`<button class="btn" onclick="${next.action}">Continue</button>`:''}<button class="btn" onclick="navigate('home')">Home</button></div></div><details class="clean-extra-practice"><summary>Characters &amp; more practice</summary><div class="studio-set-chars">${chars.slice(0,20).map(ch=>`<button class="btn" onclick="openPracticeDetails('${ch}')">${esc(text(ch))}</button>`).join('')}</div><div class="clean-hub-actions">${kind==='cards'&&chars.length?`<button class="btn" onclick="startWritingBatch('${s.id||state.lastChapter}','${chars.join('')}')">Write these characters</button><button class="btn" onclick="startSession('all',${s.id?"'"+s.id+"'":'null'},'${chars.join('')}'.split(''))">Repeat this set</button>`:''}${reading?`<button class="btn" onclick="openReading('${reading.id}')">Try a reading</button>`:''}${(s.everMissed||[]).length?`<button class="btn" onclick="retryPractice(true,'${kind}')">Repeat all missed</button>`:''}${undoAvailable()?'<button class="btn" onclick="undoLastAnswer()">Undo last answer</button>':''}</div>${chars.map(ch=>state.cards[ch]?.due).some(at=>Number.isFinite(at)&&at>Date.now())?`<p class="small muted">Next review: ${esc(studioDueLabel(Math.min(...chars.map(ch=>state.cards[ch]?.due).filter(at=>Number.isFinite(at)&&at>Date.now()))))}.</p>`:''}</details>`}
renderPracticeCompletion=function(s,kind){setPracticeViewport(false);const needs=practiceRetryTargets(s),awards=Object.entries(s.partnerXP||{}).filter(([,xp])=>xp>0);$('view').innerHTML=`<section class="panel clean-completion clean-result"><div class="clean-result-companion">${cleanBuddyEnabled()?`<div class="clean-buddy-slot" data-clean-companion></div>`:icon('check')}</div><h1>${kind==='write'?'Writing complete':'Session complete'}</h1><p class="muted">${s.right} recalled without hints${needs.length?' · '+needs.length+' to revisit':''}</p>${cleanBuddyEnabled()&&awards.length?`<p class="clean-earned-xp">${awards.map(([id,xp])=>`+${xp} XP · ${esc(STARTERS.find(p=>p.id===id)?.name||'Companion')}`).join(' · ')}</p>`:''}${cleanCompletionActions(s,kind)}</section>`;mountStudyCompanion('celebrate');cleanSyncHeaderBuddy()};
