/* Focused review reuses the existing scheduler and reward limits. */
function targetedPracticePlan(){
 const studied=uniqueCards().filter(c=>state.cards[c.character]?.seen>0),allowed=new Set(studied.map(c=>c.character)),limit=state.settings.sessionLength;
 const weak=studied.filter(c=>state.quizMisses[c.character]||!familiar(c)).sort((a,b)=>Number(!!state.quizMisses[b.character])-Number(!!state.quizMisses[a.character])||(state.cards[a.character].streak||0)-(state.cards[b.character].streak||0)||(state.cards[a.character].last||0)-(state.cards[b.character].last||0));
 const characters=[],reasons={};const add=(ch,reason)=>{if(allowed.has(ch)&&!characters.includes(ch)&&characters.length<limit){characters.push(ch);reasons[ch]=reason}};
 for(const c of weak){add(c.character,state.quizMisses[c.character]?'missed quiz':'needs practice');const peers=CONFUSIONS.filter(g=>g.chars.includes(c.character)).flatMap(g=>[...g.chars]).filter(ch=>ch!==c.character&&allowed.has(ch));if(peers.length)add(peers.sort((a,b)=>(state.cards[a].last||0)-(state.cards[b].last||0))[0],'similar character')}
 for(const group of CONFUSIONS){const pair=[...group.chars].filter(ch=>allowed.has(ch));if(pair.length>=2)pair.forEach(ch=>add(ch,'similar character'))}
 studied.sort((a,b)=>(state.cards[a.character].due||0)-(state.cards[b.character].due||0)).forEach(c=>add(c.character,'extra review'));
 return {characters,reasons}
}
function openTargetedPractice(){const plan=targetedPracticePlan();if(!plan.characters.length)return toast('Practice a few characters first.');studyModal(`<section class="targeted-preview"><h2>Your practice set</h2><p class="small muted">Difficult characters and familiar lookalikes. No new characters.</p><div class="targeted-character-list">${plan.characters.map(ch=>`<button class="btn" onclick="showCharacter('${ch}')"><span lang="zh">${esc(text(ch))}</span><small>${esc(plan.reasons[ch])}</small></button>`).join('')}</div><button class="btn primary full" onclick="startTargetedPractice()">Practice ${plan.characters.length} ${plan.characters.length===1?'character':'characters'} ${icon('arrow')}</button></section>`)}
function startTargetedPractice(){const plan=targetedPracticePlan();if(!plan.characters.length)return toast('Practice a few characters first.');startSession('all',null,plan.characters);session.mode='missed';session.reasons=plan.reasons;session.targetedPractice=true;checkpointSession('cards',session);renderSession()}
const targetedReviewRender=renderReview;
renderReview=function(){targetedReviewRender();const tile=`<section class="panel"><h2>Targeted practice</h2><p class="small muted">Difficult cards and similar characters, in one short set.</p><button class="btn" ${Object.values(state.cards).some(c=>c.seen>0)?'':'disabled'} onclick="openTargetedPractice()">Build my practice set</button></section>`;let html=$('view').innerHTML;const missedPanel=/<section class="panel"><h2>Missed answers<\/h2>[\s\S]*?<\/section>/;html=missedPanel.test(html)?html.replace(missedPanel,tile):html.replace('<div class="flow-review-grid">','<div class="flow-review-grid">'+tile);$('view').innerHTML=html};
const targetedCompletion=cleanCompletionActions;
cleanCompletionActions=function(s,kind){return targetedCompletion(s,kind).replace('<div class="clean-hub-actions">','<div class="clean-hub-actions"><button class="btn" onclick="openTargetedPractice()">Targeted practice</button>')};
CLEAN_REACTIONS.recovered=['proud','sparkle'];
const recoveredCaptionBase=cleanBuddyCaption;
cleanBuddyCaption=function(mood){if(mood!=='recovered')return recoveredCaptionBase(mood);if(!state.settings.companionMessages)return '';const lines=['You remembered it!','You got it this time!','That tricky one clicked.','Back in your memory.'];return `<span class="clean-buddy-bubble" role="status" aria-live="polite">${lines[cleanReactionIndex%lines.length]}</span>`};
function wasTrickyCharacter(ch,s){const prior=state.cards[ch];return !!(prior?.seen>0&&(state.quizMisses[ch]||prior.streak===0||['again','hard'].includes(s?.lastRatings?.[ch])))}
function markRecoveredCharacter(s,ch){s.recoveredCharacters??=[];if(s.recoveredCharacters.includes(ch))return false;s.recoveredCharacters.push(ch);return true}
const recoveredRate=rate;
rate=function(value){const s=session,ch=s?.queue[s.pos]?.character,valid=s&&!s.done&&s.revealed&&['again','hard','good'].includes(value),recovered=valid&&value==='good'&&!studioHelped(s)&&wasTrickyCharacter(ch,s);recoveredRate(value);if(recovered&&markRecoveredCharacter(s,ch)){checkpointSession('cards',s);if(!s.done){studioFeedback={mood:'recovered',message:'You recalled a previously difficult character without help.'};mountStudyCompanion('recovered')}}};
const recoveredQuizChoose=quizChoose;
quizChoose=function(ch){const s=quizSession,q=s?.questions[s.pos],recovered=q&&q.choice===null&&ch===q.card.character&&!q.usedHint&&wasTrickyCharacter(ch,s);recoveredQuizChoose(ch);if(recovered&&q.choice===ch&&markRecoveredCharacter(s,ch)){q.recoveredRecall=true;checkpointSession('quiz',s);mountStudyCompanion('recovered')}};
const recoveredQuizRender=renderQuiz;
renderQuiz=function(){recoveredQuizRender();const q=quizSession?.questions[quizSession.pos];if(q?.recoveredRecall)mountStudyCompanion('recovered')};

/* Visual recall studio v1: small introductions, delayed retrieval, and optional drawing. */
CLEAN_STUDY_TABS.splice(0,CLEAN_STUDY_TABS.length,['usage','Usage'],['shape','Shape & memory'],['sound','Sound']);
function memoryTab(tab){return ['parts','components','memory'].includes(tab)?'shape':CLEAN_STUDY_TABS.some(t=>t[0]===tab)?tab:'usage'}
const memorySoundBase=cleanSoundPane;
cleanSoundPane=function(c){return memorySoundBase(c).replace(/<details class="clean-study-section"><summary>When tones change[\s\S]*?<\/details>/g,'')};
function memoryPartLegend(c){const parts=memoryParts(c);if(!parts)return `<p class="small muted">One whole shape. Notice its outline and stroke positions.</p>`;const names=parts.parts.map((p,i)=>`<button class="memory-part-chip memory-color-${i}" ${p==='？'?'disabled':`onclick="openComponentCard('${p}')"`}><span lang="zh">${esc(p==='？'?'⋯':p)}</span><small>${esc(p==='？'?'changed strokes':partName(p))}</small></button>`).join('');return `<div class="memory-part-legend">${names}</div><p class="memory-layout-note">${esc(IDS_LAYOUT[parts.tree.op])}</p>`}
function memoryShapePane(c){const note=state.memoryNotes[c.character];return `<div id="memory-study-content"><div class="memory-full">${memoryDiagram(c,{interactive:true})}</div>${memoryPartLegend(c)}<p class="memory-story">${esc(note||memoryCue(c))}</p></div><div id="memory-covered" class="memory-cover" hidden><strong>Picture the shape.</strong><p class="small">Where do the parts go?</p></div><div class="memory-recall-controls"><button class="btn" id="memory-cover-button" aria-pressed="false" onclick="toggleMemoryCover()">${icon('cover')} Cover the shape</button></div><details class="clean-study-section"><summary>Component roles &amp; explanation</summary>${componentMarkupBeforeQoL(c.character)}</details><details class="memory-note-editor"><summary>${note?'Edit':'Add'} your memory note</summary><label for="memory-note">Use a connection that works for you.</label><textarea id="memory-note" maxlength="300" placeholder="This shape reminds me of…" oninput="studioMemoryNote('${c.character}',this.value)">${esc(note||'')}</textarea><p id="memory-note-status" class="small muted">Saved with your progress.</p></details><p class="memory-origin-note">The picture is a memory aid, not a historical explanation.</p>`}
cleanMemoryPane=memoryShapePane;
cleanStudyPane=function(c,tab){tab=memoryTab(tab);return tab==='usage'?cleanUsagePane(c):tab==='sound'?cleanSoundPane(c):memoryShapePane(c)};
const memoryStudyOpenBase=openCleanStudy,memoryStudySelectBase=selectCleanStudyTab;
function memoryMarkHelp(){if(currentView==='session'&&session&&!session.done&&!session.revealed&&!memoryIsStudy()){session.usedHint=true;checkpointCurrent()}}
openCleanStudy=function(ch,tab='usage'){memoryMarkHelp();memoryStudyOpenBase(ch,memoryTab(tab))};
selectCleanStudyTab=function(tab){memoryStudySelectBase(memoryTab(tab))};
openPracticeDetails=function(ch,tab='usage'){openCleanStudy(ch,tab)};
openPronunciation=function(ch){openCleanStudy(ch,'sound')};openMemoryAid=function(ch){openCleanStudy(ch,'shape')};
function memoryNewLimit(){return [1,3,5].includes(state.settings.newCharacters)?state.settings.newCharacters:3}
function memoryLearningPlan(id){const chapterCards=uniqueCards(id),newCards=chapterCards.filter(c=>!state.cards[c.character]?.seen),weak=chapterCards.filter(c=>state.cards[c.character]?.seen&&!familiar(c)&&state.cards[c.character].memoryStage!==1),due=dueCards().filter(c=>state.cards[c.character]?.seen).sort((a,b)=>state.cards[a.character].due-state.cards[b.character].due),limit=weak.length>=3?1:memoryNewLimit(),fresh=newCards.slice(0,limit),review=[],add=c=>{if(c&&!fresh.some(x=>x.character===c.character)&&!review.some(x=>x.character===c.character))review.push(c)};weak.slice(0,2).forEach(add);due.slice(0,2).forEach(add);if(!fresh.length&&!review.length)chapterCards.filter(c=>state.cards[c.character]?.seen).sort((a,b)=>(state.cards[a.character].last||0)-(state.cards[b.character].last||0)).slice(0,Math.min(5,state.settings.sessionLength)).forEach(add);return {fresh,review:review.slice(0,fresh.length?2:state.settings.sessionLength)}}
nextBatchSize=function(id){const p=memoryLearningPlan(id);return p.fresh.length||p.review.length};
function memoryIsStudy(s=session){return s?.memoryCoach?.version===1&&s.memoryCoach.steps[s.pos]?.phase==='study'}
function memoryIntro(c){const parts=memoryParts(c);return `<div class="memory-intro-shape">${parts?parts.parts.map((p,i)=>`<button class="memory-inline-part memory-color-${i}" ${p==='？'?'disabled':`onclick="openComponentCard('${p}')"`} aria-label="Explore ${esc(p==='？'?'changed strokes':partName(p))}"><span lang="zh">${esc(p==='？'?'⋯':p)}</span><small>${esc(p==='？'?'changed strokes':partName(p))}</small></button>`).join(''):`<span class="memory-whole-cue">${esc(memoryCue(c,true))}</span>`}</div>${parts?`<p class="memory-short-cue">${esc(memoryCue(c,true))}</p>`:''}`}
const memoryStartBase=startSession;
startSession=function(mode,id,characters){if(mode!=='learn'||characters){memoryStartBase(mode,id,characters);return}const plan=memoryLearningPlan(id);if(!plan.fresh.length&&!plan.review.length)return toast('No characters are available in this chapter.');const pool=[...plan.fresh,...uniqueCards().filter(c=>state.cards[c.character]?.seen)],matches=plan.fresh.map(c=>({ch:c.character,phase:'choose',choices:memoryMatchChoices(c,pool),chosen:null})).filter(step=>step.choices.length>=2);const steps=[...plan.fresh.map(c=>({ch:c.character,phase:'study'})),...plan.review.map(c=>({ch:c.character,phase:'recall'})),...matches,...plan.fresh.map(c=>({ch:c.character,phase:'recall'}))];memoryStartBase('all',id,[...plan.fresh,...plan.review].map(c=>c.character));session.mode='learn';session.memoryCoach={version:1,newCharacters:plan.fresh.map(c=>c.character),steps};session.queue=steps.map(step=>courseCard(step.ch,id));session.batch=[...new Set(steps.map(step=>step.ch))];session.revealed=memoryIsStudy();session.memorySketches={};session.right=0;renderSession();checkpointCurrent()};
function memoryAdvanceStudy(){const s=session;if(!s||s.done||!memoryIsStudy(s))return;s.pos++;s.revealed=memoryIsStudy(s);s.hint=false;s.hintLevel=0;s.usedHint=false;s.covered=false;s.memoryPadOpen=false;s.memoryModelHidden=false;studioFeedback=null;renderSession();checkpointCurrent()}
const memoryRateBase=rate;
rate=function(value){const s=session,c=s?.queue[s.pos];if(memoryIsStudy(s)||memoryIsMatch(s))return;const valid=s&&!s.done&&s.revealed&&['again','hard','good'].includes(value);if(!valid)return memoryRateBase(value);const old=state.cards[c.character]?clone(state.cards[c.character]):null,assisted=studioHelped(s),pos=s.pos;s.memoryPadOpen=false;s.memoryModelHidden=false;memoryRateBase(value);if(s.pos===pos)return;
 // Keep guided step metadata aligned when the established retry loop reinserts a card.
 if(s.memoryCoach&&s.queue.length>s.memoryCoach.steps.length)s.memoryCoach.steps.splice(Math.min(s.queue.length-1,pos+5),0,{ch:c.character,phase:'recall'});
 const record=state.cards[c.character],managed=s.memoryCoach?.newCharacters.includes(c.character)||Number.isInteger(old?.memoryStage)||old?.streak===0||value!=='good'||assisted;
 if(record&&managed){const now=Date.now();if(value==='good'&&!assisted){const stage=old?.memoryStage||0;if(stage===0){record.memoryStage=1;record.interval=10/1440;record.due=now+10*60000}else if(stage===1&&old.due<=now){record.memoryStage=2;record.interval=1;record.due=now+86400000}else if(stage===1){record.memoryStage=1;record.interval=old.interval;record.due=old.due}else record.memoryStage=2}else{record.memoryStage=0;record.interval=value==='again'?10/1440:30/1440;record.due=now+(value==='again'?10:30)*60000}save()}
 if(memoryIsStudy(s))s.revealed=true;renderSession();checkpointCurrent()
};
const memoryRevealBase=reveal;
reveal=function(){if(memoryIsStudy())return memoryAdvanceStudy();if(memoryIsMatch())return memoryAdvanceMatch();if(session?.memoryPadOpen)session.memoryModelHidden=false;memoryRevealBase()};
function memoryCurrentCard(){if(currentView==='session')return session?.queue[session.pos];if(currentView==='quiz')return quizSession?.questions[quizSession.pos]?.card;if(currentView==='write'){const ch=[...(writeSession?.queue[writeSession.pos]?.target||'')][0];return cardByChar[ch]}return null}
function openCurrentStudy(tab='usage'){const c=memoryCurrentCard();if(c)openCleanStudy(c.character,tab)}
function memoryHintSheet(){const s=session,c=s?.queue[s.pos];if(!s||!c||s.revealed)return;s.hintLevel=Math.min(3,(s.hintLevel||0)+1);s.hint=true;s.usedHint=true;checkpointCurrent();const level=s.hintLevel;studyModal(`<h2>${['Shape clue','Sound clue','Meaning clue'][level-1]}</h2>${level===1&&memoryParts(c)?memoryDiagram(c,{hint:true}):''}<p>${esc(characterHints(c)[level-1])}</p>${level===2?`<button class="btn" onclick="speak('${c.character}',.65)">${icon('sound')} Listen</button>`:''}<div class="memory-hint-actions">${level<3?'<button class="btn" onclick="closeStudioDialogs();memoryHintSheet()">Another clue</button>':''}<button class="btn primary" onclick="qolReturnToPractice()">Try reading it</button></div>`)}
flashHint=memoryHintSheet;
function memoryPadStrokes(){if(!session)return [];session.memorySketches??={};const ch=session.queue[session.pos]?.character;if(!ch)return [];return session.memorySketches[ch]??=[]}
function openPracticeSketch(){const s=session;if(!s||s.done)return;s.memoryPadOpen=!s.memoryPadOpen;if(s.memoryPadOpen){s.usedHint=true;s.memoryModelHidden=!s.revealed&&!memoryIsStudy(s)}renderSession();checkpointCurrent()}
function togglePracticeModel(){if(!session?.memoryPadOpen)return;session.memoryModelHidden=!session.memoryModelHidden;if(!session.memoryModelHidden)session.usedHint=true;renderSession();checkpointCurrent()}
function memoryUndoStroke(){memoryPadStrokes().pop();paintMemoryCanvas();checkpointCurrent()}
function memoryClearSketch(){const strokes=memoryPadStrokes();strokes.length=0;paintMemoryCanvas();checkpointCurrent()}
function memorySketchMarkup(c){const hidden=session.memoryModelHidden;return `<div class="memory-sketch-model"><span class="memory-model-glyph" lang="zh">${hidden?'?':esc(han(c))}</span><div><strong>${esc(c.pinyin)}</strong><p>${esc(c.meaning)}</p></div><button class="textbtn" onclick="togglePracticeModel()">${hidden?'Show':'Hide'} model</button></div><canvas id="memory-canvas" tabindex="0" aria-label="Optional character sketch pad. Use paper if you prefer." aria-describedby="memory-sketch-note"></canvas><div class="memory-sketch-controls"><button class="textbtn" onclick="memoryUndoStroke()">Undo stroke</button><button class="textbtn" onclick="memoryClearSketch()">Clear</button><button class="textbtn" onclick="openPracticeSketch()">Done sketching</button></div><p id="memory-sketch-note">Sketch or use paper. Check the shape yourself.</p>`}
function paintMemoryCanvas(){const canvas=$('memory-canvas');if(!canvas||!session?.memoryPadOpen)return;const ctx=canvas.getContext('2d');if(!ctx)return;const w=canvas.width,h=canvas.height;ctx.clearRect(0,0,w,h);ctx.strokeStyle=getComputedStyle(document.documentElement).getPropertyValue('--line');ctx.lineWidth=1;ctx.setLineDash([5,5]);ctx.beginPath();ctx.moveTo(w/2,0);ctx.lineTo(w/2,h);ctx.moveTo(0,h/2);ctx.lineTo(w,h/2);ctx.stroke();ctx.setLineDash([]);ctx.strokeStyle=getComputedStyle(document.documentElement).getPropertyValue('--ink');ctx.lineWidth=3*(window.devicePixelRatio||1);ctx.lineCap='round';ctx.lineJoin='round';for(const stroke of memoryPadStrokes()){if(!stroke.length)continue;ctx.beginPath();ctx.moveTo(stroke[0][0]*w,stroke[0][1]*h);if(stroke.length===1)ctx.lineTo(stroke[0][0]*w+.5,stroke[0][1]*h+.5);for(const p of stroke.slice(1))ctx.lineTo(p[0]*w,p[1]*h);ctx.stroke()}}
function initMemoryCanvas(){const canvas=$('memory-canvas');if(!canvas||!session?.memoryPadOpen)return;const bounds=canvas.getBoundingClientRect(),ratio=window.devicePixelRatio||1;canvas.width=Math.max(1,Math.round(bounds.width*ratio));canvas.height=Math.max(1,Math.round(bounds.height*ratio));paintMemoryCanvas();let drawing=false;const point=e=>{const b=canvas.getBoundingClientRect();return [Math.max(0,Math.min(1,(e.clientX-b.left)/(b.width||1))),Math.max(0,Math.min(1,(e.clientY-b.top)/(b.height||1)))]};canvas.onpointerdown=e=>{if(e.button!==undefined&&e.button!==0)return;if(memoryPadStrokes().length>=100)return;e.preventDefault();canvas.setPointerCapture?.(e.pointerId);drawing=true;memoryPadStrokes().push([point(e)]);paintMemoryCanvas()};canvas.onpointermove=e=>{if(!drawing)return;const stroke=memoryPadStrokes().at(-1);if(stroke.length<500)stroke.push(point(e));paintMemoryCanvas()};canvas.onpointerup=canvas.onpointercancel=()=>{drawing=false;checkpointCurrent()}}
window.addEventListener('resize',()=>{if(session?.memoryPadOpen&&currentView==='session')initMemoryCanvas()});
function memoryActionDock(c){return `<div class="memory-action-dock"><button class="btn" title="Study details · D" onclick="openCleanStudy('${c.character}')">${icon('read')} Study details <kbd>D</kbd></button><button class="btn" title="Shape and components · C" onclick="openCleanStudy('${c.character}','shape')">${icon('layers')} Shape <kbd>C</kbd></button><button class="btn" title="Sketch · W" aria-pressed="${!!session?.memoryPadOpen}" onclick="openPracticeSketch()">${icon('write')} Sketch <kbd>W</kbd></button></div>`}
studioAidDock=function(c){return `<button class="btn clean-details-button" title="Study details · D" onclick="openCleanStudy('${c.character}')">${icon('read')}<span>Study details</span><small>Usage · Shape · Sound</small><kbd>D</kbd></button>`};
renderSession=function(){const s=session,c=s?.queue[s.pos];if(!s)return navigate('learn');setPracticeViewport(!!c);if(!c){s.done=true;renderPracticeCompletion(s,'cards');checkpointSession('cards',s);return}const study=memoryIsStudy(s),matching=memoryIsMatch(s),revealed=s.revealed||study,sketch=s.memoryPadOpen&&!matching,label=study?'Meet the shape':matching?'Find the shape':s.targetedPractice?'Targeted practice':s.memoryCoach?'Read from memory':'Practice',total=s.queue.length,buddy=cleanBuddyEnabled();
 $('view').innerHTML=`<div class="session-wrap focus-session studio-session memory-session"><div class="focus-top"><span class="small muted">${label} · ${s.pos+1} / ${total}</span>${studioSessionTools()}</div><div class="progress" role="progressbar" aria-label="Session progress" aria-valuemin="0" aria-valuemax="${total}" aria-valuenow="${s.pos}"><span style="width:${s.pos/total*100}%"></span></div><section class="focus-card memory-practice-card ${sketch?'memory-pad-open':''} ${study?'memory-study-card':''}"><button class="iconbtn save-btn" aria-label="${state.bookmarks.includes(c.character)?'Remove bookmark':'Bookmark character'}" aria-pressed="${state.bookmarks.includes(c.character)}" onclick="qolBookmarkPractice('${c.character}')">${star(c.character)}</button>${matching?memoryMatchMarkup(c):sketch?memorySketchMarkup(c):`<div class="memory-core"><div class="han" lang="zh">${esc(han(c))}</div>${revealed?`<div class="focus-answer"><div class="row"><span class="pinyin">${esc(c.pinyin)}</span><button class="btn focus-listen" onclick="speak('${c.character}')" aria-label="Listen to character · L">${icon('sound')} Listen</button></div><p class="focus-meaning">${esc(c.meaning)}</p></div>${study?memoryIntro(c):''}`:`<p class="memory-read-prompt">Read it from memory.</p><button class="textbtn memory-hint" onclick="memoryHintSheet()">${s.usedHint?'Another hint':'Hint'} <kbd>H</kbd></button>`}</div>`}${buddy?`<div class="memory-companion-shelf">${cleanBuddySlot()}</div>`:''}</section><div class="focus-actions studio-actions memory-actions">${matching?`<div class="memory-action-dock memory-match-dock"><button class="btn" onclick="openCurrentStudy()">Study details <kbd>D</kbd></button><button class="btn" onclick="openCurrentStudy('shape')">Shape <kbd>C</kbd></button></div>`:memoryActionDock(c)}${matching?`<button class="btn primary full" ${s.memoryCoach.steps[s.pos].chosen===null?'disabled':''} onclick="memoryAdvanceMatch()">Continue ${icon('arrow')}</button>`:study?`<button class="btn primary full memory-next" onclick="memoryAdvanceStudy()">${memoryIsNextStudy(s)?'Next character':'Try recalling'} ${icon('arrow')}<span class="keyboard-label">Space</span></button>`:revealed?`<div class="rate-row"><button class="btn danger" title="Could not read it · 1" onclick="rate('again')">Again <kbd>1</kbd></button><button class="btn" title="Hesitated or needed help · 2" onclick="rate('hard')">Almost <kbd>2</kbd></button><button class="btn primary" title="Read it without help · 3" onclick="rate('good')">${studioHelped(s)?'With help':'Got it'} <kbd>3</kbd></button></div>`:`<button class="btn primary full" onclick="reveal()">Show answer <span class="keyboard-label">Space</span></button>`}</div></div>`;
 mountStudyCompanion(studioFeedback?.mood||(study?'thinking':'idle'));if(sketch)initMemoryCanvas();checkpointSession('cards',s);syncSpeechButtons()
};
function memoryIsNextStudy(s){return s.memoryCoach?.steps[s.pos+1]?.phase==='study'}
function memoryMatchChoices(c,pool){const targetSig=c.pinyin+'|'+c.meaning;const peers=pool.filter(x=>x.character!==c.character&&x.pinyin+'|'+x.meaning!==targetSig),near=CONFUSIONS.filter(g=>g.chars.includes(c.character)).flatMap(g=>[...g.chars]);peers.sort((a,b)=>Number(near.includes(b.character))-Number(near.includes(a.character)));return shuffle([c,...peers.slice(0,3)]).map(x=>x.character)}
function memoryIsMatch(s=session){return s?.memoryCoach?.version===1&&s.memoryCoach.steps[s.pos]?.phase==='choose'}
function memoryChooseCharacter(ch){const s=session,step=s?.memoryCoach?.steps[s.pos];if(!memoryIsMatch(s)||step.chosen!==null||!step.choices.includes(ch))return;step.chosen=ch;s.revealed=true;if(ch!==step.ch){s.memoryCoach.matchMisses??=[];if(!s.memoryCoach.matchMisses.includes(step.ch))s.memoryCoach.matchMisses.push(step.ch)}studioFeedback={mood:ch===step.ch?'happy':'encourage'};renderSession();checkpointCurrent()}
