function mountScrollObserver(){destroyScrollObserver();const root=$('scroll-feed'),s=state.scrollSession;if(!root||!s)return;const token=scrollMountVersion,id=s.id;root.addEventListener('scroll',onScrollFeed,{passive:true});for(const name of ['pointerdown','touchstart','wheel'])root.addEventListener(name,releaseScrollTarget,{passive:true});root.addEventListener('touchstart',scrollContinueTouchStart,{passive:true});root.addEventListener('touchend',scrollContinueTouchEnd,{passive:true});root.addEventListener('touchcancel',()=>{scrollGesture=null},{passive:true});root.addEventListener('wheel',scrollContinueWheel,{passive:true});if(typeof window.IntersectionObserver==='function'){const ratios=new Map();scrollObserver=new window.IntersectionObserver(entries=>{if(token!==scrollMountVersion||currentView!=='scroll'||state.scrollSession?.id!==id)return;for(const entry of entries)ratios.set(Number(entry.target.dataset.scrollIndex),entry.intersectionRatio);const best=[...ratios].sort((a,b)=>b[1]-a[1])[0];if(!$('overlay').innerHTML&&best&&best[1]>=.55)acceptScrollPosition(best[0]);},{root,threshold:[0,.55,.8,1]});root.querySelectorAll('[data-scroll-index]').forEach(node=>scrollObserver.observe(node))}}
function scrollWordMarkup(c){const e=EXAMPLE_CONTEXT[c.word];if(!e)return '';return `<div class="scroll-word" lang="zh">${[...e.word].map(ch=>`<button class="textbtn ${ch===c.character?'scroll-target':''}" onclick="openStudyCharacter('${ch}')">${esc(text(ch))}</button>`).join('')}</div><p class="scroll-word-pinyin">${esc(e.pinyin)}</p><p class="scroll-meaning">${esc(e.meaning)}</p><button class="btn" onclick="speak('${e.word}')">${icon('sound')} Listen to example</button>`}
