function openScrollDetails(tab='usage'){const s=state.scrollSession,f=s?.frames[s.index];if(!f?.ch)return;if(['read','find'].includes(f.kind)&&f.chosen===null){f.helped=true;save()}openCleanStudy(f.ch,tab)}
function answerScrollCheck(index,ch){const s=state.scrollSession,f=s?.frames[index];if(currentView!=='scroll'||!s||s.done||!f||!['read','find'].includes(f.kind)||f.chosen!==null||!f.choices.includes(ch))return;scrollSetIndex(index);const before=state.cards[f.ch]?clone(state.cards[f.ch]):null,cold=f.cold&&!f.helped&&!scrollHasModelExposure(s,f.ch)&&before?.seen>0&&before.due<=Date.now()&&before.last<=Date.now()-600000;f.chosen=ch;f.correct=ch===f.ch;const now=Date.now();if(cold&&f.correct){state.cards[f.ch]=schedule(before,'good',now);delete state.quizMisses[f.ch]}else if(!before?.seen){state.cards[f.ch]={seen:1,streak:0,interval:10/1440,due:now+600000,last:now,memoryStage:f.correct?1:0}}else if(before.memoryStage===0||before.memoryStage===1){state.cards[f.ch]={...before,seen:before.seen+1,last:now,memoryStage:f.correct?1:0,due:before.due>now?Math.min(before.due,now+600000):now+600000}}else if(!f.correct){state.cards[f.ch]={...schedule(before,'again',now),memoryStage:0};state.quizMisses[f.ch]=now}
 awardCharacterTraining(f.ch,'recognition',f.correct,!(cold&&f.correct),before);const today=dayKey();state.activity[today]??={cards:0,readings:0};state.activity[today].cards++;s.savedAt=now;save();playStudySound(f.correct?'correct':'retry');$('scroll-card-'+index).innerHTML=scrollFrameMarkup(f,index);const last=s.frames.length-1;$('scroll-card-'+last).innerHTML=scrollFrameMarkup(s.frames[last],last);updateScrollControls();$('scroll-feedback-'+index)?.focus?.({preventScroll:true})}
