handlePracticeKeydown=function(e){if(currentView!=='scroll')return scrollKeyBase(e);if(e.defaultPrevented||e.repeat||e.isComposing||e.ctrlKey||e.metaKey||e.altKey||['INPUT','TEXTAREA','SELECT'].includes(e.target?.tagName)||e.target?.isContentEditable)return;if($('overlay').innerHTML)return scrollKeyBase(e);const key=e.key.toLowerCase(),s=state.scrollSession,f=s?.frames[s.index],native=e.target?.tagName==='BUTTON'&&[' ','enter'].includes(key);if(!s||native)return;let handled=true;if(['arrowdown','pagedown',' ','enter'].includes(key))scrollPage(1);else if(['arrowup','pageup'].includes(key))scrollPage(-1);else if(key==='d'||key==='c')openScrollDetails(key==='c'?'shape':'usage');else if(key==='l'&&f?.ch)speak(f.kind==='word'?cardByChar[f.ch].word:f.ch);else if(['1','2','3','4'].includes(key)&&f&&['read','find'].includes(f.kind)){const ch=f.choices[Number(key)-1];if(ch)answerScrollCheck(s.index,ch)}else if(key==='escape')pauseScrollPractice();else handled=false;if(handled)e.preventDefault()};
