function scrollReadingChoices(c,pool){const picks=[c],sig=c.pinyin+'|'+c.meaning;for(const x of [...pool,...uniqueCards()]){if(x.character===c.character||x.pinyin+'|'+x.meaning===sig||picks.some(y=>y.character===x.character||y.pinyin+'|'+y.meaning===x.pinyin+'|'+x.meaning))continue;picks.push(x);if(picks.length===3)break}return shuffle(picks.map(x=>x.character))}
