function anotherScrollSet(expectedId=null){const s=state.scrollSession;if(currentView!=='scroll'||!s||expectedId&&s.id!==expectedId)return;const id=s.chapter,reviewOnly=s.reviewOnly===true;s.done=true;s.savedAt=Date.now();save();startScrollPractice(id,null,reviewOnly)}
