function scrollContinueTouchStart(e){scrollGesture=null;if(!scrollCanContinue()||e.touches?.length!==1)return;scrollGesture={id:state.scrollSession.id,y:e.touches[0].clientY,at:Date.now()}}
function scrollContinueTouchEnd(e){const gesture=scrollGesture;scrollGesture=null;if(!gesture||!scrollCanContinue()||!e.changedTouches?.length)return;const delta=gesture.y-e.changedTouches[0].clientY;if(delta>=55&&Date.now()-gesture.at<1800)anotherScrollSet(gesture.id)}
