function pruneScrollShapes(s){const keep=s.frames.map((f,i)=>({f,i})).filter(({f})=>f.kind!=='part'||scrollShapeData(cardByChar[f.ch]));if(keep.length===s.frames.length)return false;const map=new Map(keep.map(({i},j)=>[i,j]));s.exposed=[...new Set([...(s.exposed||[]),...s.viewed.filter(i=>['meet','part','word'].includes(s.frames[i]?.kind)).map(i=>s.frames[i].ch)])];const next=keep.find(({i})=>i>=s.index)||keep.at(-1);s.index=map.get(next.i);s.viewed=s.viewed.filter(i=>map.has(i)).map(i=>map.get(i));s.frames=keep.map(({f})=>f);return true}

/* Companion personality v1. Reactions describe accepted actions; they never award progress. */
