function feedProgress(){const data=feedEnsureState(),all=feedCatalog(),chapter=data.mode==='chapter'||data.mode==='focus'?data.anchor:feedFrontier(data),cards=feedChapterCards(chapter);return {introduced:all.filter(c=>feedMet(c.character,data)).length,checked:all.filter(c=>state.cards[c.character]?.seen>0||data.entries[c.character]?.checks>0).length,familiar:all.filter(familiar).length,chapter,chapterIntroduced:cards.filter(c=>feedMet(c.character,data)).length,chapterTotal:cards.length,mode:data.mode}}
function currentScrollFrame(){const s=state.scrollSession;return s?.frames?.[s.index]||null}
function feedFrameRole(f){if(!f)return 'review';if(f.repair)return 'repair';if(f.cold&&['read','find'].includes(f.kind))return 'review';if(['read','find'].includes(f.kind))return 'check';if(f.kind==='word')return 'usage';if(f.kind==='part')return 'shape';return f.kind==='meet'&&state.scrollSession?.newCharacters?.includes(f.ch)?'new':'review'}
