 for(const id of ordered){let cards=feedChapterCards(id).filter(c=>!feedMet(c.character,data));if(id!=='I')cards=cards.map((c,i)=>({c,i,score:learningShapeScore(c,known)})).sort((a,b)=>a.score-b.score||a.i-b.i).map(x=>x.c);out.push(...cards)}
