function feedSetPace(pace,restart=false){if(!['balanced','fresh'].includes(pace))return false;feedEnsureState().pace=pace;save();if(restart){const data=feedEnsureState();startScrollPractice(data.mode==='discover'?undefined:data.anchor,data.focus,data.mode==='review',{mode:data.mode})}return true}
