 const data=feedEnsureState(),e=feedEntry(data,ch),seen=feedPrimeVisits(scope),at=Date.now(),firstVisit=!e.visits||!seen.has(ch)&&e.lastSetId!==scope.id;let changed=firstVisit||e.lastAt!==at;seen.add(ch);
