/* A small in-memory trail keeps backward swipes continuous without an ever-growing DOM. */
let feedBackTrail=[],feedForwardTrail=[],feedTrailContinuing=false,feedHistoryAt=0;
function feedClearTrail(){feedBackTrail=[];feedForwardTrail=[]}
function feedStopAudio(){studioSpeechToken++;window.speechSynthesis?.cancel();studioSpeaking='';studioSpeechPhase='idle'}
const feedTrailStartBase=startScrollPractice;
startScrollPractice=function(...args){if(!feedTrailContinuing)feedClearTrail();const before=state.scrollSession,result=feedTrailStartBase(...args);if(state.scrollSession!==before)feedStopAudio();return result};
const feedTrailAnotherBase=anotherScrollSet;
anotherScrollSet=function(expectedId=null){const before=state.scrollSession;if(currentView!=='scroll'||!before||expectedId&&before.id!==expectedId)return false;if(feedForwardTrail.length){const next=feedForwardTrail.pop();feedBackTrail.push(before);feedBackTrail=feedBackTrail.slice(-3);before.done=true;next.done=false;next.index=0;state.scrollSession=next;feedStopAudio();save();renderScrollPractice();feedHistoryAt=Date.now();$('scroll-frame-'+next.index)?.focus?.({preventScroll:true});return true}feedTrailContinuing=true;let result;try{result=feedTrailAnotherBase(expectedId)}finally{feedTrailContinuing=false}if(state.scrollSession!==before){feedBackTrail.push(before);feedBackTrail=feedBackTrail.slice(-3);feedHistoryAt=Date.now();updateScrollControls();$('scroll-frame-'+state.scrollSession.index)?.focus?.({preventScroll:true})}return result};
function feedPreviousChunk(){if(currentView!=='scroll'||!feedBackTrail.length||$('overlay').innerHTML)return false;const s=state.scrollSession,previous=feedBackTrail.pop();feedForwardTrail.push(s);feedForwardTrail=feedForwardTrail.slice(-3);previous.done=false;previous.index=Math.max(0,previous.frames.length-2);state.scrollSession=previous;feedStopAudio();save();renderScrollPractice();feedHistoryAt=Date.now();$('scroll-frame-'+previous.index)?.focus?.({preventScroll:true});return true}
const feedTrailPageBase=scrollPage;
scrollPage=function(direction){if(direction<0&&state.scrollSession?.index===0&&feedBackTrail.length)return feedPreviousChunk();return feedTrailPageBase(direction)};
const feedTrailControlsBase=updateScrollControls;
updateScrollControls=function(){feedTrailControlsBase();const prev=$('scroll-prev');if(prev&&state.scrollSession)prev.disabled=state.scrollSession.index===0&&!feedBackTrail.length};
const feedTrailMountBase=mountScrollObserver;
mountScrollObserver=function(){feedTrailMountBase();const root=$('scroll-feed'),id=state.scrollSession?.id;if(!root||!id)return;let touch=null;const ready=()=>currentView==='scroll'&&state.scrollSession?.id===id&&state.scrollSession.index===0&&!$('overlay').innerHTML&&root.scrollTop<=3&&!($('scroll-card-0')?.scrollTop>3)&&feedBackTrail.length&&Date.now()-feedHistoryAt>350;root.addEventListener('touchstart',e=>{touch=ready()&&e.touches?.length===1?e.touches[0].clientY:null},{passive:true});root.addEventListener('touchend',e=>{const y=touch;touch=null;if(y!==null&&ready()&&e.changedTouches?.[0]?.clientY-y>65)feedPreviousChunk()},{passive:true});root.addEventListener('touchcancel',()=>{touch=null},{passive:true});let wheel=0,last=0;root.addEventListener('wheel',e=>{const now=Date.now();if(!ready()||e.ctrlKey||e.metaKey||e.deltaY>=0){wheel=0;last=now;return}if(now-last>250)wheel=0;last=now;wheel+=Math.min(100,Math.abs(e.deltaY)*(e.deltaMode===1?16:1));if(wheel>100){wheel=0;feedPreviousChunk()}},{passive:true})};
/* Unlearn also removes discovery memory, so it can teach that form again. */
unlearn=function(ch){if(!cardByChar[ch]||!confirm(`Unlearn ${text(ch)}? This resets its learning and writing progress and affected chapter quiz results. Your bookmarks and activity history stay saved.`))return;clearSavedSession();delete state.quizMisses[ch];delete state.cards[ch];for(const w of Object.keys(state.writing))if(w.includes(ch))delete state.writing[w];for(const c of CARDS.filter(c=>c.character===ch))delete state.quizzes.chapters[c.lesson];state.quizzes.review=null;const data=feedEnsureState();delete data.entries[ch];data.recent=data.recent.filter(x=>x!==ch);data.cursor=cardByChar[ch].lesson;if(state.scrollSession?.targets.includes(ch))state.scrollSession=null;feedClearTrail();save();closeModal();chrome();if(currentView==='scroll')navigate('home');else if(currentView==='search')dictionaryResults();else if(currentView==='chapter')renderChapter();else if(currentView==='home')renderHome();else if(currentView==='review')renderReview();toast(`${text(ch)} marked as unlearned`)};

if('speechSynthesis'in window)speechSynthesis.getVoices();theme();chrome();renderHome();document.body.classList.add('app-ready');
loadSavedSession();courseRuntimeReady=true;syncCourseState();renderHome();
if(!state.profile.setupDone){showNameSetup();}
